// ---- resources/js/core/urls.js ----
// Ссылки и адреса — одно правило для всего редактора (этап 3 MODULAR_PLAN.md, «Безопасность»).
// Тот же код на сервере: src/Sanitizer.php → Sanitizer::urlOk. Общие примеры — tests/security/url-vectors.json
// (их проверяют оба теста: набор security в tests/run.html и tests/php/test-sanitize.php).
//
// Разрешено:
//   https:, http:                      — везде;
//   mailto:, tel:                      — только в ссылках (href);
//   data:image/png|jpeg|gif|webp|avif|bmp — только в src картинки (растровые картинки старых статей, решение 21.11);
//   без схемы: «/путь», «#якорь», «?запрос», «страница.html», «../папка/», «//сайт/путь» (решение 21.11).
// Всё остальное — javascript:, vbscript:, data: (в ссылке, SVG, HTML), file:, blob:, about:, любые другие схемы — нет.
// Схема определяется так же, как её видит браузер: пробелы, переводы строк, табуляция, невидимые знаки и
// управляющие символы внутри схемы игнорируются, регистр не важен; HTML-сущности (&#106;) раскрывает разбор HTML
// до проверки. Для подстраховки опасная схема ищется и после раскодирования %XX (%6Aavascript:).

const URL_KINDS = ['link', 'media', 'image'];
const IMAGE_DATA = /^data:image\/(?:png|jpe?g|gif|webp|avif|bmp)[;,]/;
const DANGER = /^(?:javascript|vbscript|livescript|mocha|data|file|blob|about|filesystem|jar|view-source|ms-[a-z-]+):/;
// пробелы, управляющие и невидимые знаки, которые браузер выбрасывает или которыми прячут схему
const HIDDEN = /[\u0000-\u0020\u007f-\u00a0\u00ad\u1680\u180e\u2000-\u200f\u2028-\u202f\u205f-\u2064\u3000\ufeff\ufffd]/g;

/** Строка без невидимых знаков, в нижнем регистре: так её схему видит браузер. */
function bare(value) {
  return String(value).replace(HIDDEN, '').toLowerCase();
}

/**
 * Адрес допустим? kind: 'link' — href ссылки (ещё mailto:, tel:); 'media' — src видео, аудио, фрейма, постер, адрес карточки;
 * 'image' — src картинки (ещё растровая data:image).
 */
function urlOk(value, kind = 'link') {
  if (typeof value !== 'string') return false;
  const v = bare(value);
  if (!v) return false;
  let decoded = v;
  try { decoded = decodeURIComponent(v); } catch (e) { decoded = v.replace(/%[0-9a-f]{2}/g, (m) => String.fromCharCode(parseInt(m.slice(1), 16))); }
  decoded = bare(decoded);
  if (kind === 'image' && IMAGE_DATA.test(v)) return true;
  if (DANGER.test(v) || DANGER.test(decoded)) return false;
  const scheme = /^([a-z][a-z0-9+.-]*):/.exec(v);
  if (!scheme) return true;   // без схемы: путь на сайте, якорь, запрос, «//сайт»
  if (scheme[1] === 'http' || scheme[1] === 'https') return true;
  return kind === 'link' && (scheme[1] === 'mailto' || scheme[1] === 'tel');
}

/** srcset: каждый адрес — по правилу картинки. */
function srcsetOk(value) {
  return typeof value === 'string' && value.split(',').every((part) => {
    const url = part.trim().split(/\s+/)[0] || '';
    return !!url && urlOk(url, 'image');
  });
}

// ---- resources/js/core/allowlist.js ----
// Белый список разметки — тот же, что на сервере (src/Sanitizer.php → Sanitizer), этап 3 MODULAR_PLAN.md.
// Им чистится «сырой» HTML старых статей (TinyMCE: таблицы, свои вставки, div со стилями), который редактор
// показывает нередактируемым блоком: в браузере остаётся ровно то, что оставит сервер.
// Списки между маркерами сверяет тест tests/php/test-sanitize.php (с константами Sanitizer). На этапе 5 они будут
// собираться из block.json блоков.


/* allowlist:begin — те же списки, что Sanitizer::ALLOWED, DROP_WITH_CONTENT, ATTRS в src/Sanitizer.php */
const ALLOWED_TAGS = [
  "div", "ul", "ol", "li", "code", "br",
  "strong", "em", "u", "s", "sub", "sup", "mark", "a", "span",
  "figure", "figcaption", "img", "picture", "source", "video", "audio",
  "table", "thead", "tbody", "tfoot", "tr", "th", "td", "caption", "colgroup", "col",
  "dl", "dt", "dd", "details", "summary", "address", "iframe", "nav"
];
const DROP_WITH_CONTENT = [
  "script", "style", "link", "meta", "base", "template", "noscript", "object", "embed", "applet", "frame", "frameset",
  "form", "input", "button", "select", "option", "textarea", "svg", "math", "xmp", "listing", "plaintext", "title", "head",
  "canvas", "audio-worklet", "bgsound", "marquee", "noframes", "noembed"
];
const ALLOWED_ATTRS = {
  "a": ["href", "target", "rel", "download", "data-ted-video"],
  "img": ["src", "alt", "width", "height", "loading", "srcset", "sizes"],
  "source": ["src", "srcset", "type", "media", "sizes"],
  "video": ["src", "controls", "preload", "playsinline", "poster", "width", "height", "loop", "muted"],
  "audio": ["src", "controls", "preload", "loop", "muted", "title"],
  "iframe": ["src", "width", "height", "allowfullscreen", "title", "loading", "referrerpolicy"],
  "td": ["colspan", "rowspan", "data-formula"],
  "th": ["colspan", "rowspan", "scope", "data-formula"],
  "table": ["data-cols"],
  "col": ["span"],
  "colgroup": ["span"],
  "ol": ["start", "reversed", "type"],
  "li": ["value"],
  "details": ["open", "itemscope", "itemprop", "itemtype"],
  "summary": ["itemprop"],
  "div": ["data-words", "data-chars", "data-minutes", "data-blocks", "itemscope", "itemprop", "itemtype"]
};
const VIDEO_HOSTS = ["www.youtube.com", "youtube.com", "www.youtube-nocookie.com", "player.vimeo.com", "rutube.ru", "vkvideo.ru", "vk.com"];
/* allowlist:end */
// Блоки из реестра (этап 5) приносят свои теги и атрибуты сами — block.json → html; сервер читает те же файлы (src/Blocks.php).

/** Тег разрешён: список ядра или блок из реестра. */
function tagAllowed(tag) {
  return ALLOWED_TAGS.includes(tag) || registeredBlocks().some((d) => Object.prototype.hasOwnProperty.call(d.html, tag));
}

/** Атрибуты тега: ядро + блоки реестра. */
function attrsAllowed(tag) {
  const out = [...(ALLOWED_ATTRS[tag] || [])];
  for (const d of registeredBlocks()) for (const a of d.html[tag] || []) if (!out.includes(a)) out.push(a);
  return out;
}

// Шаблоны: id — латиница, цифры, «_» и «-», с буквы, до 64 знаков; классы — только ted-* (оформление блоков).
const ID_PATTERN = /^[A-Za-z][A-Za-z0-9_-]{0,63}$/;
const CLASS_PATTERN = /^ted-[a-z0-9_-]{1,40}$/;
const BLOCK_SANDBOX = 'allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox allow-presentation';
const VIDEO_SANDBOX = 'allow-scripts allow-same-origin allow-presentation allow-popups';
const ALLOW_URL_ATTRS = ['href', 'src', 'poster'];

function frameUrl(value, hosts) {
  try {
    const v = String(value || '').trim();
    if (!v || /[\s<>"'`]/.test(v)) return false;
    const u = new URL(v);
    return u.protocol === 'https:' && !!u.hostname && !u.username && !u.password && !u.port && (!hosts || hosts.includes(u.hostname.toLowerCase()));
  } catch (e) { return false; }
}

/** Элемент блока с фреймом (block.json → frames: true, блок «iFrame»). */
function isFrameBlock(el) {
  return !!el && el.nodeType === 1 && registeredBlocks().some((d) => d.frames && d.match(el));
}

/** Песочница и правила фрейма — как на сервере; frameHosts — сайты блока «iFrame» (null — любой https). */
function frameOk(el, frameHosts) {
  const parent = el.parentElement;
  const block = isFrameBlock(parent);
  return block ? frameUrl(el.getAttribute('src'), frameHosts) : frameUrl(el.getAttribute('src'), VIDEO_HOSTS);
}

/** Атрибут-идентификатор CMS из block.json → ids (встраивание, товар). */
function idAttr(name) {
  return registeredBlocks().some((d) => d.ids && d.ids.includes(name));
}

function cleanAttributes(el, tag) {
  const allowed = attrsAllowed(tag);
  for (const attr of Array.from(el.attributes)) {
    const name = attr.name.toLowerCase();
    const value = attr.value;
    if (name === 'class') {
      const classes = [...new Set(value.trim().split(/\s+/).filter((c) => CLASS_PATTERN.test(c)))];
      if (classes.length) el.setAttribute('class', classes.join(' ')); else el.removeAttribute(attr.name);
      continue;
    }
    if (name === 'id') { if (!ID_PATTERN.test(value)) el.removeAttribute(attr.name); continue; }
    if (!allowed.includes(name)) { el.removeAttribute(attr.name); continue; }
    if (ALLOW_URL_ATTRS.includes(name)) {
      const kind = name === 'href' ? 'link' : (name === 'src' && (tag === 'img' || (tag === 'source' && el.parentElement && el.parentElement.tagName === 'PICTURE'))) ? 'image' : 'media';
      if (!urlOk(value, kind)) { el.removeAttribute(attr.name); continue; }
    }
    if (name === 'srcset' && !srcsetOk(value)) { el.removeAttribute(attr.name); continue; }
    if (name === 'target' && value !== '_blank' && value !== '_self') el.removeAttribute(attr.name);
    if (idAttr(name) && !/^[\w-]{1,64}$/.test(value)) el.removeAttribute(attr.name);   // block.json → ids: id статьи, товара CMS
    if (name === 'data-cols' && !/^(?:[1-9]|10)$/.test(value)) el.removeAttribute(attr.name);
    if (name === 'itemscope' && value !== '' && value !== 'itemscope') el.setAttribute('itemscope', '');
    if (name === 'itemprop' && !['mainEntity', 'name', 'acceptedAnswer', 'text'].includes(value)) el.removeAttribute(attr.name);
    if (name === 'itemtype' && !['https://schema.org/FAQPage', 'https://schema.org/Question', 'https://schema.org/Answer'].includes(value)) el.removeAttribute(attr.name);
    if (name === 'data-formula' && !/^=[0-9A-Za-zА-Яа-яЁё$:;,.+\-−–—*/×÷()%#!\s]{0,499}$/u.test(value)) el.removeAttribute(attr.name);
    if (['width', 'height', 'colspan', 'rowspan', 'span', 'start', 'value'].includes(name) && !/^\d{1,5}%?$/.test(value)) el.removeAttribute(attr.name);
  }
  if (tag === 'a') {
    if (el.getAttribute('target') === '_blank') el.setAttribute('rel', 'noopener noreferrer');
    else el.removeAttribute('rel');
    const video = el.getAttribute('data-ted-video');
    if (video && !frameUrl(video, VIDEO_HOSTS)) el.removeAttribute('data-ted-video');
  }
  if (tag === 'iframe') {
    const inBlock = isFrameBlock(el.parentElement);
    const full = el.hasAttribute('allowfullscreen');
    for (const fixed of ['loading', 'sandbox', 'referrerpolicy', 'allowfullscreen']) el.removeAttribute(fixed);
    el.setAttribute('loading', 'lazy');
    el.setAttribute('sandbox', inBlock ? BLOCK_SANDBOX : VIDEO_SANDBOX);
    el.setAttribute('referrerpolicy', 'strict-origin-when-cross-origin');
    if (full) el.setAttribute('allowfullscreen', '');
  }
}

/**
 * Очистить содержимое элемента по белому списку (как Sanitizer::walk): опасные теги — с содержимым,
 * неизвестные — без обёртки (текст остаётся), атрибуты — по списку, адреса — по общему правилу, фреймы — в песочнице.
 */
function cleanByAllowlist(parent, frameHosts = null) {
  for (const node of Array.from(parent.childNodes)) {
    if (node.nodeType === 8 || node.nodeType === 7 || node.nodeType === 10) { node.remove(); continue; }
    if (node.nodeType !== 1) continue;
    const tag = node.localName.toLowerCase();
    if (DROP_WITH_CONTENT.includes(tag)) { node.remove(); continue; }
    if (!tagAllowed(tag) || node.namespaceURI !== 'http://www.w3.org/1999/xhtml') {
      cleanByAllowlist(node, frameHosts);
      while (node.firstChild) parent.insertBefore(node.firstChild, node);
      node.remove();
      continue;
    }
    if (tag === 'iframe' && !frameOk(node, frameHosts)) { node.remove(); continue; }
    cleanAttributes(node, tag);
    cleanByAllowlist(node, frameHosts);
  }
  return parent;
}

// ---- resources/js/core/highlight.js ----
// Подсветка синтаксиса кода — своя, без библиотек и внешних запросов.
// tokenize(text, lang) → [{ t: 'kw' | 'str' | 'num' | 'com' | 'fn' | 'tag' | 'attr' | 'prop' | 'var' | null, s }]
// В сохранённом HTML токены — <span class="ted-k"> (короткие классы); в правке — CSS Custom Highlight API (без изменения DOM).

const CODE_LANGS = [
  { id: 'html', label: 'HTML' }, { id: 'css', label: 'CSS' }, { id: 'js', label: 'JavaScript' }, { id: 'ts', label: 'TypeScript' },
  { id: 'php', label: 'PHP' }, { id: 'json', label: 'JSON' }, { id: 'sql', label: 'SQL' }, { id: 'python', label: 'Python' }, { id: 'bash', label: 'Bash' },
];

const ALIAS = { javascript: 'js', jsx: 'js', mjs: 'js', typescript: 'ts', tsx: 'ts', htm: 'html', xml: 'html', svg: 'html', scss: 'css', less: 'css', py: 'python', sh: 'bash', shell: 'bash', zsh: 'bash' };

/** Привести введённое название языка к коду: «JavaScript» → js; неизвестные оставляем как есть (буквы любого алфавита, в том числе кириллица, цифры и + # . -). */
function normalizeLang(v) {
  const s = String(v || '').trim().toLowerCase().replace(/[^\p{L}\p{N}+#.-]/gu, '').slice(0, 20);
  return ALIAS[s] || s;
}

function langLabel(id) {
  const f = CODE_LANGS.find((l) => l.id === id);
  return f ? f.label : id;
}

/** Определение языка по тексту (простые признаки); пустая строка — не определился. */
function detectCodeLang(text) {
  let t = String(text || '').trim();
  if (t.length > 20000) t = `${t.slice(0, 10000)}\n${t.slice(-2000)}`;   // большой код: смотрим начало и конец
  if (!t) return '';
  if (/^<\?php|<\?=/.test(t)) return 'php';
  if (/^<!doctype html|^<\/?[a-z][\w-]*[\s>/]/i.test(t) && />\s*$/.test(t.split('\n').pop() || '')) return 'html';
  if (/^[\[{]/.test(t)) { try { JSON.parse(t); return 'json'; } catch (e) { /* не JSON */ } }
  if (/^\s*(select|insert\s+into|update|delete\s+from|create\s+table|alter\s+table|drop\s+table)\b/i.test(t)) return 'sql';
  if (/^#!.*\b(ba|z)?sh\b|^\s*(\$ |sudo |apt |npm |git |cd |ls |echo |curl |chmod |mkdir )/m.test(t)) return 'bash';
  if (/^\s*(def |class \w+.*:|import \w+|from \w+ import|print\()/m.test(t) && !/[{};]\s*$/m.test(t)) return 'python';
  if (/^[^{}\n]*\{[^}]*:\s*[^;}]+;?[^}]*\}/m.test(t) && /[.#@]?[\w-]+\s*\{/.test(t) && !/\b(function|const|let|var|=>)\b/.test(t)) return 'css';
  if (/\b(interface |type \w+ =|: (string|number|boolean)\b|enum )/.test(t)) return 'ts';
  if (/\b(function|const|let|var|=>|console\.|document\.|import .* from|export )\b/.test(t)) return 'js';
  if (/\$\w+\s*=|->\w+|\bnamespace\b|echo\s/.test(t)) return 'php';
  return '';
}

const JS_KW = 'break|case|catch|class|const|continue|debugger|default|delete|do|else|export|extends|finally|for|from|function|if|import|in|instanceof|let|new|of|return|super|switch|this|throw|try|typeof|var|void|while|with|yield|async|await|static|get|set|null|undefined|true|false|interface|type|enum|implements|public|private|protected|readonly|as';
const PHP_KW = 'abstract|and|array|as|break|case|catch|class|clone|const|continue|declare|default|do|echo|else|elseif|empty|extends|final|finally|for|foreach|function|global|if|implements|include|include_once|interface|isset|list|namespace|new|or|print|private|protected|public|require|require_once|return|static|switch|throw|trait|try|use|var|while|null|true|false|self|parent';
const PY_KW = 'and|as|assert|async|await|break|class|continue|def|del|elif|else|except|finally|for|from|global|if|import|in|is|lambda|nonlocal|not|or|pass|raise|return|try|while|with|yield|None|True|False|self';
const SQL_KW = 'select|from|where|and|or|not|insert|into|values|update|set|delete|create|table|alter|drop|join|left|right|inner|outer|on|group|by|order|having|limit|offset|as|distinct|union|all|null|is|in|like|between|exists|case|when|then|else|end|primary|key|foreign|references|index|default|unique|count|sum|avg|min|max|asc|desc';
const SH_KW = 'if|then|else|elif|fi|for|while|do|done|case|esac|in|function|return|exit|export|local|echo|cd|ls|cat|grep|sed|awk|git|npm|sudo|apt|curl|chmod|mkdir|rm|cp|mv';

const kw = (list, flags = '') => new RegExp(`^(?:${list})\\b`, flags);

// Правила: [тип, регулярное выражение с ^]; первое подошедшее правило выигрывает
const RULES = {
  js: [
    ['com', /^\/\/[^\n]*|^\/\*[\s\S]*?(?:\*\/|$)/],
    ['str', /^`(?:\\[\s\S]|[^`\\])*(?:`|$)|^"(?:\\.|[^"\\\n])*(?:"|$)|^'(?:\\.|[^'\\\n])*(?:'|$)/],
    ['num', /^(?:0x[\da-f]+|\d+\.?\d*(?:e[+-]?\d+)?)\b/i],
    ['kw', kw(JS_KW)],
    ['fn', /^[A-Za-z_$][\w$]*(?=\s*\()/],
    ['var', /^[A-Z][\w$]*/],
  ],
  php: [
    ['com', /^\/\/[^\n]*|^#[^\n]*|^\/\*[\s\S]*?(?:\*\/|$)/],
    ['str', /^"(?:\\.|[^"\\])*(?:"|$)|^'(?:\\.|[^'\\])*(?:'|$)/],
    ['var', /^\$[A-Za-z_]\w*/],
    ['kw', /^<\?php|^\?>/],
    ['num', /^\d+\.?\d*\b/],
    ['kw', kw(PHP_KW, 'i')],
    ['fn', /^[A-Za-z_]\w*(?=\s*\()/],
  ],
  python: [
    ['com', /^#[^\n]*/],
    ['str', /^(?:"""[\s\S]*?(?:"""|$)|'''[\s\S]*?(?:'''|$))|^"(?:\\.|[^"\\\n])*(?:"|$)|^'(?:\\.|[^'\\\n])*(?:'|$)/],
    ['num', /^\d+\.?\d*\b/],
    ['kw', kw(PY_KW)],
    ['fn', /^[A-Za-z_]\w*(?=\s*\()/],
  ],
  sql: [
    ['com', /^--[^\n]*|^\/\*[\s\S]*?(?:\*\/|$)/],
    ['str', /^'(?:''|[^'])*(?:'|$)|^"[^"]*(?:"|$)/],
    ['num', /^\d+\.?\d*\b/],
    ['kw', kw(SQL_KW, 'i')],
    ['fn', /^[A-Za-z_]\w*(?=\s*\()/],
  ],
  bash: [
    ['com', /^#[^\n]*/],
    ['str', /^"(?:\\.|[^"\\])*(?:"|$)|^'[^']*(?:'|$)/],
    ['var', /^\$\{?[A-Za-z_]\w*\}?|^\$[0-9@#?]/],
    ['attr', /^--?[A-Za-z][\w-]*/],
    ['num', /^\d+\b/],
    ['kw', kw(SH_KW)],
  ],
  json: [
    ['prop', /^"(?:\\.|[^"\\\n])*"(?=\s*:)/],
    ['str', /^"(?:\\.|[^"\\\n])*(?:"|$)/],
    ['num', /^-?\d+\.?\d*(?:e[+-]?\d+)?\b/i],
    ['kw', /^(?:true|false|null)\b/],
  ],
  css: [
    ['com', /^\/\*[\s\S]*?(?:\*\/|$)/],
    ['str', /^"(?:\\.|[^"\\\n])*(?:"|$)|^'(?:\\.|[^'\\\n])*(?:'|$)/],
    ['kw', /^@[\w-]+/],
    ['num', /^#[\da-f]{3,8}\b|^-?\d*\.?\d+(?:px|em|rem|vw|vh|%|s|ms|deg|fr)?\b/i],
    ['prop', /^[a-z-]+(?=\s*:)/i],
    ['tag', /^[.#]?[A-Za-z_][\w-]*(?=[^{};]*\{)/],
    ['fn', /^[a-z-]+(?=\()/i],
  ],
};
RULES.ts = RULES.js;

function tokenizeHtml(text) {
  const out = [];
  const push = (t, s) => { if (s) out.push({ t, s }); };
  let i = 0;
  while (i < text.length) {
    if (text.startsWith('<!--', i)) {
      const e = text.indexOf('-->', i + 4);
      const end = e < 0 ? text.length : e + 3;
      push('com', text.slice(i, end));
      i = end;
    } else if (text[i] === '<' && /[A-Za-z!/?]/.test(text[i + 1] || '')) {
      const e = text.indexOf('>', i);
      const end = e < 0 ? text.length : e + 1;
      const tag = text.slice(i, end);
      const m = tag.match(/^(<\/?)([A-Za-z][\w:-]*|!doctype|[!?][\w-]*)?/i) || [tag, '<', ''];
      push('tag', m[0]);
      let rest = tag.slice(m[0].length);
      const re = /^(\s+)|^([\w:@.-]+)(\s*=\s*)?|^("[^"]*"|'[^']*')|^(\/?>)|^[\s\S]/;
      while (rest) {
        const a = rest.match(re);
        const s = a[0];
        if (a[1]) push(null, s);
        else if (a[2]) { push('attr', a[2]); if (a[3]) push(null, a[3]); }
        else if (a[4]) push('str', s);
        else if (a[5]) push('tag', s);
        else push(null, s);
        rest = rest.slice(s.length);
      }
      i = end;
    } else {
      const e = text.indexOf('<', i + 1);
      const end = e < 0 ? text.length : e;
      push(null, text.slice(i, end));
      i = end;
    }
  }
  return out;
}

/** Склеить соседние токены одного типа (и пробелы между ними): в сохранённом HTML меньше <span>, в правке меньше диапазонов. */
function compact(tokens) {
  const out = [];
  for (let i = 0; i < tokens.length; i += 1) {
    const tk = tokens[i];
    const prev = out[out.length - 1];
    if (prev && prev.t === tk.t) { prev.s += tk.s; continue; }
    // пробелы между двумя одинаковыми токенами присоединяем к ним
    if (prev && prev.t && !tk.t && /^[ \t]+$/.test(tk.s) && tokens[i + 1] && tokens[i + 1].t === prev.t) {
      prev.s += tk.s + tokens[i + 1].s;
      i += 1;
      continue;
    }
    out.push({ t: tk.t, s: tk.s });
  }
  return out;
}

const SHORT = { kw: 'k', str: 's', num: 'n', com: 'c', fn: 'f', tag: 't', attr: 'a', prop: 'p', var: 'v' };

/** Разбить текст на токены. lang — код языка (см. CODE_LANGS), неизвестный язык — без подсветки. */
function tokenize(text, lang) {
  return compact(tokenizeRaw(text, lang));
}

function tokenizeRaw(text, lang) {
  const id = ALIAS[lang] || lang;
  if (text.length > 300000) return [{ t: null, s: text }];   // слишком длинный текст не подсвечиваем
  if (id === 'html') return tokenizeHtml(text);
  const rules = RULES[id];
  if (!rules) return [{ t: null, s: text }];
  const out = [];
  let plain = '';
  const flush = () => { if (plain) { out.push({ t: null, s: plain }); plain = ''; } };
  let i = 0;
  while (i < text.length) {
    const rest = text.slice(i);
    let hit = null;
    // слова целиком, чтобы ключевое слово не находилось внутри идентификатора
    if (/^[A-Za-z_$]/.test(rest) && plain && /[\w$]$/.test(plain)) { plain += rest[0]; i += 1; continue; }
    for (const [t, re] of rules) {
      const m = rest.match(re);
      if (m && m[0]) { hit = [t, m[0]]; break; }
    }
    if (hit) { flush(); out.push({ t: hit[0], s: hit[1] }); i += hit[1].length; } else { plain += rest[0]; i += 1; }
  }
  flush();
  return out;
}

/** Фрагмент с <span class="ted-k"> (k, s, n, c, f, t, a, p, v) для сохранённого HTML. */
function highlightFragment(text, lang, doc = document) {
  const frag = doc.createDocumentFragment();
  for (const tk of tokenize(text, lang)) {
    if (!tk.t) frag.appendChild(doc.createTextNode(tk.s));
    else {
      const sp = doc.createElement('span');
      sp.className = `ted-${SHORT[tk.t] || tk.t}`;
      sp.textContent = tk.s;
      frag.appendChild(sp);
    }
  }
  return frag;
}

// ---- Подсветка в правке: CSS Custom Highlight API (DOM не меняется, курсор не сбивается) ----
const store = new Map();   // корень редактора → { тип → [Range] }

function highlightSupported() {
  return typeof CSS !== 'undefined' && !!CSS.highlights && typeof Highlight !== 'undefined';
}

function applyEditorHighlight(root, getLang) {
  if (!highlightSupported()) return;
  const byType = {};
  for (const code of root.querySelectorAll(':scope > pre > code')) {
    const text = code.textContent;
    const pre = code.parentNode;
    const lang = getLang ? getLang(pre, text) : pre.getAttribute('data-lang') || detectCodeLang(text);
    const cache = `${lang}\u0000${text}`;
    if (code.__tedHl && code.__tedHl.key === cache) {
      for (const [t, rs] of Object.entries(code.__tedHl.ranges)) (byType[t] = byType[t] || []).push(...rs);
      continue;
    }
    const nodes = [];
    const starts = [];
    let total = 0;
    const w = document.createTreeWalker(code, 4);
    for (let n = w.nextNode(); n; n = w.nextNode()) { nodes.push(n); starts.push(total); total += n.data.length; }
    const ranges = {};
    let pos = 0;
    // позиция в тексте → (текстовый узел, смещение); двоичный поиск, чтобы большой код не считался квадратично
    const locate = (offset) => {
      if (!nodes.length) return null;
      let lo = 0;
      let hi = nodes.length - 1;
      while (lo < hi) {
        const mid = (lo + hi + 1) >> 1;
        if (starts[mid] < offset) lo = mid; else hi = mid - 1;
      }
      return [nodes[lo], Math.min(nodes[lo].data.length, offset - starts[lo])];
    };
    for (const tk of tokenize(text, lang)) {
      const len = tk.s.length;
      if (tk.t) {
        const a = locate(pos);
        const b = locate(pos + len);
        if (a && b) {
          const r = document.createRange();
          r.setStart(a[0], a[1]);
          r.setEnd(b[0], b[1]);
          (ranges[tk.t] = ranges[tk.t] || []).push(r);
        }
      }
      pos += len;
    }
    code.__tedHl = { key: cache, ranges };
    for (const [t, rs] of Object.entries(ranges)) (byType[t] = byType[t] || []).push(...rs);
  }
  // в редакторе без кода глобальные подсветки не трогаем (иначе при многих редакторах на странице каждая правка пересобирала бы все)
  const had = store.has(root);
  if (!Object.keys(byType).length && !had) return;
  if (Object.keys(byType).length) store.set(root, byType); else store.delete(root);
  const all = {};
  for (const [r, m] of Array.from(store)) {
    if (!r.isConnected) { store.delete(r); continue; }
    for (const [t, rs] of Object.entries(m)) (all[t] = all[t] || []).push(...rs);
  }
  for (const t of ['kw', 'str', 'num', 'com', 'fn', 'tag', 'attr', 'prop', 'var']) {
    if (all[t] && all[t].length) CSS.highlights.set(`ted-${t}`, new Highlight(...all[t]));
    else CSS.highlights.delete(`ted-${t}`);
  }
}

/** Убрать подсветку уничтоженного редактора (общие ::highlight пересобираются из остальных). */
function releaseEditorHighlight(root) {
  if (!highlightSupported() || !store.delete(root)) return;
  const all = {};
  for (const [r, m] of Array.from(store)) {
    if (!r.isConnected) { store.delete(r); continue; }
    for (const [t, rs] of Object.entries(m)) (all[t] = all[t] || []).push(...rs);
  }
  for (const t of ['kw', 'str', 'num', 'com', 'fn', 'tag', 'attr', 'prop', 'var']) {
    if (all[t] && all[t].length) CSS.highlights.set(`ted-${t}`, new Highlight(...all[t]));
    else CSS.highlights.delete(`ted-${t}`);
  }
}

// ---- resources/js/core/sanitize.js ----
// Очистка HTML: из любого входа (старый контент TinyMCE, вставка из Word /
// Google Docs, DOM редактора) получаем чистую семантическую разметку.
//
// Разрешено:
//   блоки:   p, h2–h6, ul, ol, li, blockquote, pre, hr
//   строчные: strong, em, u, s, code, a[href], sub, sup, br
// Замены: b→strong, i→em, strike/del→s, ins→u, h1→h2, div→p,
//         span со стилями жирного/курсива/подчёркивания/зачёркивания → теги.
// Незнакомые блоки (таблицы, картинки, iframe…) не удаляются, а сохраняются
// как есть в «сыром» блоке — чтобы не потерять старый контент.




const BLOCK_TAGS = ['P', 'H2', 'H3', 'H4', 'H5', 'H6', 'UL', 'OL', 'BLOCKQUOTE', 'PRE'];

/** Тег блочного элемента: ядро + блоки реестра (этап 5: тег из selector в block.json, например hr). Только у селектора
 *  без обязательного класса: figure.ted-iframe или div.ted-button не делают блоком любой <figure> / <div>. */
function isBlockTag(tag) {
  const t = String(tag).toUpperCase();
  return BLOCK_TAGS.includes(t) || registeredBlocks().some((d) => d.selector && /^[a-z0-9]+(?::not\([^)]*\))*$/.test(d.selector) && d.selector.split(/[.#[:\s]/)[0].toUpperCase() === t);
}
const HEADING_TAGS = ['H2', 'H3', 'H4', 'H5', 'H6'];

const INLINE_MAP = {
  STRONG: 'strong', B: 'strong',
  EM: 'em', I: 'em', CITE: 'em', DFN: 'em',
  U: 'u', INS: 'u',
  S: 's', STRIKE: 's', DEL: 's',
  CODE: 'code', KBD: 'code', SAMP: 'code', TT: 'code',
  SUB: 'sub', SUP: 'sup',
  A: 'a',
  MARK: 'mark',
};

const DROP_TAGS = new Set([
  'SCRIPT', 'STYLE', 'META', 'LINK', 'TITLE', 'HEAD', 'NOSCRIPT', 'TEMPLATE',
  'BUTTON', 'INPUT', 'SELECT', 'TEXTAREA', 'O:P', 'XML',
]);

// Блоки, которые пока не редактируем, но сохраняем без изменений
const RAW_TAGS = new Set([
  'TABLE', 'FIGURE', 'IMG', 'PICTURE', 'IFRAME', 'VIDEO', 'AUDIO', 'OBJECT', 'EMBED',
  'SVG', 'CANVAS', 'FORM', 'DETAILS', 'DL', 'ADDRESS', 'MAP',
]);

// Контейнеры, которые просто «разворачиваем»
const UNWRAP_BLOCK_TAGS = new Set([
  'DIV', 'SECTION', 'ARTICLE', 'MAIN', 'HEADER', 'FOOTER', 'ASIDE', 'NAV', 'CENTER',
  'BODY', 'HTML', 'FIELDSET',
]);

const ALIGN_CLASS = /^ted-align-(center|right)$/;
const BG_CLASS = /^ted-bg-(gray|color1|color2)$/;
const ID_RE = ID_PATTERN;   // id — как на сервере: с буквы, до 64 знаков (core/allowlist.js)

const isWhitespace = (s) => !/[^\t\n\r ]/.test(s);


// Подсветка в сохранённом HTML (<span class="ted-k"…>) нужна только при сохранении; при загрузке в редактор спаны сразу снимаются, поэтому их не создаём.
let emitTokens = true;
function withoutTokens(fn) {
  const prev = emitTokens;
  emitTokens = false;
  try { return fn(); } finally { emitTokens = prev; }
}
/** HTML-строка → чистый DocumentFragment (для редактора). */
function sanitizeHTML(html, doc = document) {
  const tpl = doc.createElement('template');
  tpl.innerHTML = String(html || '').replace(/<!--[\s\S]*?-->/g, '');
  const src = unwrapTedRoot(tpl.content);
  return sanitizeNodes(src.childNodes, doc);
}

/** Набор узлов → чистый DocumentFragment из блоков. */
function sanitizeNodes(nodes, doc = document) {
  const out = doc.createDocumentFragment();
  const ctx = { doc, out, para: null };
  const wordLists = [];
  let wordListId;
  for (const node of Array.from(nodes)) {
    const wordItem = readWordListItem(node);
    if (wordItem) {
      closePara(ctx);
      const { id, level, marker, tag } = wordItem;
      if (id !== wordListId) wordLists.length = 0;
      wordListId = id;
      while (wordLists.length && wordLists.at(-1).level > level) wordLists.pop();
      let entry = wordLists.at(-1);
      if (entry?.level === level && entry.list.tagName !== tag) {
        wordLists.pop();
        entry = wordLists.at(-1);
      }
      if (entry?.level !== level) {
        const list = doc.createElement(tag);
        const number = marker.textContent.trim().match(/^(\d+)[.)]$/)?.[1];
        if (tag === 'OL' && number && Number(number) !== 1) list.start = Number(number);
        (entry?.list.lastElementChild || out).appendChild(list);
        entry = { level, list };
        wordLists.push(entry);
      }
      const li = doc.createElement('li');
      cleanInlineChildren(node, li, doc, { skipNode: marker });
      trimBlock(li);
      if (li.firstChild) entry.list.appendChild(li);
      else if (!entry.list.firstChild) {
        entry.list.remove();
        wordLists.pop();
      }
      continue;
    }
    if (node.nodeType === 3 && isWhitespace(node.data)) {
      cleanBlockLevel(node, ctx);
      continue;
    }
    wordLists.length = 0;
    cleanBlockLevel(node, ctx);
  }
  return out;
}

function readWordListItem(node) {
  if (node.nodeName !== 'P' || isHiddenNode(node)) return null;
  const list = node.getAttribute('style')?.match(/(?:^|;)\s*mso-list\s*:\s*(l\d+)\s+level(\d+)\s+(lfo\d+)/i);
  if (!list) return null;
  const marker = Array.from(node.querySelectorAll('span[style]')).find((span) =>
    /(?:^|;)\s*mso-list\s*:\s*ignore\s*(?:;|$)/i.test(span.getAttribute('style')));
  if (!marker) return null;
  const tag = /^(?:\(?[\da-z]+[.)])+(?:\.)?$/i.test(marker.textContent.trim()) ? 'OL' : 'UL';
  return { id: `${list[1]} ${list[3]}`, level: Number(list[2]), marker, tag };
}

// Если на вход пришёл наш же вывод <div class="ted-content">…</div> — берём содержимое
function unwrapTedRoot(frag) {
  const els = Array.from(frag.childNodes).filter((n) => !(n.nodeType === 3 && isWhitespace(n.data)));
  if (els.length === 1 && els[0].nodeType === 1 && els[0].classList.contains('ted-content')) return els[0];
  return frag;
}

function closePara(ctx) {
  ctx.para = null;
}

function ensurePara(ctx) {
  if (!ctx.para) {
    ctx.para = ctx.doc.createElement('p');
    ctx.out.appendChild(ctx.para);
  }
  return ctx.para;
}

function cleanBlockLevel(node, ctx) {
  const { doc } = ctx;

  if (node.nodeType === 3) {
    if (isWhitespace(node.data)) {
      if (ctx.para && ctx.para.lastChild) ctx.para.appendChild(doc.createTextNode(' '));
      return;
    }
    ensurePara(ctx).appendChild(doc.createTextNode(collapse(node.data)));
    return;
  }
  if (node.nodeType !== 1) return;

  const tag = node.tagName.toUpperCase();
  if (DROP_TAGS.has(tag) || isHiddenNode(node)) return;

  // блок из реестра (этап 5): очистку делает сам блок — clean(node, doc, idOk) из blocks/<тип>/<тип>.js
  // обёртка правки (медиа, block.json → wrap): очищается блок внутри, якорь обёртки — его
  const inner = isWrap(node) && node.firstElementChild ? node.firstElementChild : null;
  // ... или чужой элемент, который блок забирает себе (block → adopt: аккордеон — одиночный <details>)
  const regDef = registeredBlocks().find((d) => d.clean && (d.match(inner || node) || (!inner && d.adopt && d.adopt(node))));
  const made = regDef ? regDef.clean(inner || node, doc, (id) => ID_RE.test(id || ''), inner ? node : null) : false;
  if (made !== false) {   // false — «не мой»: элемент очищается дальше как обычно (сложная таблица — «сырой» HTML)
    closePara(ctx);
    if (made) ctx.out.appendChild(made);
    return;
  }

  // Наш «сырой» блок — сохраняем содержимое как есть
  if (node.classList && node.classList.contains('ted-ui-raw')) {
    closePara(ctx);
    const tpl = doc.createElement('template');
    tpl.innerHTML = node.getAttribute('data-ted-raw') || node.innerHTML;
    stripDangerous(tpl.content);
    for (const n of Array.from(tpl.content.childNodes)) {
      if (n.nodeType === 1) ctx.out.appendChild(makeRaw(n, doc));
    }
    return;
  }

  // картинка внутри абзаца (старые страницы TinyMCE): абзац режется — текст до, картинка отдельным блоком, текст после
  // (решение 22.11; раньше картинка пропадала). Блок делает тот, кто умеет (block → fromRaw: изображение)
  if ((tag === 'P' || (tag === 'DIV' && !hasBlockChild(node))) && node.querySelector('img')) {
    closePara(ctx);
    let seg = doc.createElement('div');
    const flush = () => {
      if (!seg.childNodes.length) return;
      const p = withAlign(doc.createElement('p'), node);
      cleanInlineChildren(seg, p, doc);
      trimBlock(p);
      if (p.firstChild) ctx.out.appendChild(p);
      seg = doc.createElement('div');
    };
    for (const child of Array.from(node.childNodes)) {
      const own = child.nodeType === 1 && (child.tagName === 'IMG' || (child.querySelectorAll('img').length === 1 && !child.textContent.trim()));
      const made = own ? registeredBlocks().map((d) => (d.fromRaw ? d.fromRaw(child, doc) : null)).find(Boolean) : null;
      if (made) { flush(); cleanBlockLevel(made, ctx); }
      else seg.appendChild(child.cloneNode(true));
    }
    flush();
    return;
  }

  if (tag === 'P' || (tag === 'DIV' && !hasBlockChild(node))) {
    closePara(ctx);
    const p = withAlign(doc.createElement('p'), node);
    cleanInlineChildren(node, p, doc);
    trimBlock(p);
    if (p.firstChild) ctx.out.appendChild(p);
    return;
  }

  if (tag === 'H1' || HEADING_TAGS.includes(tag)) {
    closePara(ctx);
    const h = withAlign(doc.createElement(tag === 'H1' ? 'h2' : tag.toLowerCase()), node);
    cleanInlineChildren(node, h, doc, { noStrong: true });
    trimBlock(h);
    if (h.firstChild) ctx.out.appendChild(h);
    return;
  }

  if (tag === 'UL' || tag === 'OL') {
    closePara(ctx);
    const list = cleanList(node, doc);
    if (list) ctx.out.appendChild(list);
    return;
  }

  if (tag === 'LI') {
    // li без списка — заворачиваем в ul
    closePara(ctx);
    const ul = doc.createElement('ul');
    const li = cleanListItem(node, doc);
    if (li) {
      ul.appendChild(li);
      ctx.out.appendChild(ul);
    }
    return;
  }

  if (tag === 'BLOCKQUOTE') {
    closePara(ctx);
    const bq = withAlign(doc.createElement('blockquote'), node);
    // блок из реестра на основе blockquote (выноска): его классы сохраняются — block.json → classes
    const regQuote = registeredBlocks().find((d) => d.classes && d.match(node));
    if (regQuote) bq.classList.add(...regQuote.classes);
    const inner = sanitizeNodes(node.childNodes, doc);
    // автор цитаты: последний абзац p.ted-author (имя жирным, должность после <br>)
    const lastSrc = Array.from(node.children).pop();
    const hasAuthor = !!(lastSrc && lastSrc.tagName === 'P' && lastSrc.classList.contains('ted-author'));
    const kids = Array.from(inner.childNodes);
    for (const child of kids) {
      // внутри цитаты — только абзацы
      if (child.tagName === 'P') {
        if (hasAuthor && kids.length > 1 && child === kids[kids.length - 1]) {
          child.className = 'ted-author';
          // нулевые пробелы и пустое имя при сохранении убираем
          const walker = doc.createTreeWalker(child, 4);
          for (let t = walker.nextNode(); t; t = walker.nextNode()) t.data = t.data.replace(/​/g, '');
          const nm = child.firstChild;
          if (nm && nm.nodeType === 1 && nm.tagName === 'STRONG' && !nm.textContent.trim()) {
            const nb = nm.nextSibling;
            nm.remove();
            if (nb && nb.nodeType === 1 && nb.tagName === 'BR') nb.remove();
          }
          while (child.lastChild && ((child.lastChild.nodeType === 1 && child.lastChild.tagName === 'BR') || (child.lastChild.nodeType === 3 && !child.lastChild.data.trim()))) child.lastChild.remove();
          const aid = node.lastElementChild && node.lastElementChild.getAttribute('data-author-id');
          if (aid && /^[\w.-]{1,64}$/.test(aid)) child.setAttribute('data-author-id', aid);
          const strongEl = child.querySelector('strong');
          child.setAttribute('data-initials', initialsOf(strongEl ? strongEl.textContent : child.textContent));
          if (!child.textContent.trim()) continue;   // пустого автора не сохраняем
        }
        bq.appendChild(child);
      }
      else if (child.textContent.trim()) {
        const p = doc.createElement('p');
        p.textContent = child.textContent;
        bq.appendChild(p);
      }
    }
    if (bq.firstChild) ctx.out.appendChild(bq);
    return;
  }

  if (tag === 'PRE') {
    closePara(ctx);
    const pre = doc.createElement('pre');
    const text = preText(node).replace(/\n$/, '');
    if (text.trim()) {
      // <pre data-lang="js"><code data-nums="1\n2">…<span class="ted-k">…</span>…</code></pre>
      const lang = normalizeLang(node.getAttribute('data-lang')) || detectCodeLang(text);
      const nums = !node.hasAttribute('data-nonums');   // номера строк по умолчанию; data-nonums — выключены явно
      const code = doc.createElement('code');
      if (emitTokens) code.appendChild(highlightFragment(text, lang, doc)); else code.appendChild(doc.createTextNode(text));
      pre.appendChild(code);
      applyCodeMeta(pre, lang, nums);
      ctx.out.appendChild(pre);
    }
    return;
  }

  if (tag === 'BR') {
    if (ctx.para) closePara(ctx);
    return;
  }

  if (RAW_TAGS.has(tag)) {
    closePara(ctx);
    ctx.out.appendChild(makeRaw(node, doc));
    return;
  }

  if (UNWRAP_BLOCK_TAGS.has(tag) || hasBlockChild(node)) {
    closePara(ctx);
    for (const child of Array.from(node.childNodes)) cleanBlockLevel(child, ctx);
    closePara(ctx);
    return;
  }

  // Строчный элемент на верхнем уровне — в текущий абзац
  cleanInlineNode(node, ensurePara(ctx), doc, {});
}

function cleanList(node, doc) {
  const list = withAlign(doc.createElement(node.tagName.toLowerCase()), node);
  // чек-лист: <ul class="ted-checklist"> с пунктами <li class="ted-checked"> (галочка рисуется стилем, JS на сайте не нужен)
  for (const cls of ['ted-checklist', 'ted-facts', 'ted-proscons']) {
    if (list.tagName === 'UL' && node.classList && node.classList.contains(cls)) list.classList.add(cls);
  }
  // шаги: <ol class="ted-steps">, в пункте <strong>заголовок</strong><br>описание
  if (list.tagName === 'OL' && node.classList && node.classList.contains('ted-steps')) list.classList.add('ted-steps');
  const start = node.getAttribute('start');
  if (list.tagName === 'OL' && /^-?\d+$/.test(start || '')) list.start = Number(start);
  for (const child of Array.from(node.childNodes)) {
    if (child.nodeType === 1 && child.tagName === 'LI') {
      const li = cleanListItem(child, doc);
      if (li) list.appendChild(li);
    } else if (child.nodeType === 1 && (child.tagName === 'UL' || child.tagName === 'OL')) {
      // вложенный список без li — прикрепляем к предыдущему пункту
      const nested = cleanList(child, doc);
      if (nested) {
        if (list.lastElementChild) list.lastElementChild.appendChild(nested);
        else {
          const li = doc.createElement('li');
          li.appendChild(nested);
          list.appendChild(li);
        }
      }
    } else if (child.textContent && child.textContent.trim()) {
      const li = doc.createElement('li');
      cleanInlineNode(child, li, doc, {});
      trimBlock(li);
      if (li.firstChild) list.appendChild(li);
    }
  }
  if (list.classList.contains('ted-steps') || list.classList.contains('ted-facts')) tidySteps(list, doc);
  if (list.classList.contains('ted-proscons')) {
    for (const card of Array.from(list.children)) {
      const t = card.firstChild;
      if (t && t.nodeType === 1 && t.tagName === 'STRONG' && !t.textContent.trim()) t.remove();
      if (!card.textContent.trim()) card.remove();   // карточка без заголовка и пунктов
    }
  }
  return list.firstChild ? list : null;
}

/** Шаги при сохранении: без служебных нулевых пробелов и пустого заголовка (описание «поднимается» наверх). */
function tidySteps(list, doc) {
  for (const li of Array.from(list.children)) {
    const walker = doc.createTreeWalker(li, 4);
    for (let n = walker.nextNode(); n; n = walker.nextNode()) n.data = n.data.replace(/​/g, '');
    const first = li.firstElementChild;
    if (first && first.tagName === 'STRONG' && first === li.firstChild && !first.textContent.trim()) {
      const br = first.nextSibling;
      first.remove();
      if (br && br.nodeType === 1 && br.tagName === 'BR') br.remove();
    }
    // хвостовые переносы после описания
    for (let n = li.lastChild; n && ((n.nodeType === 1 && n.tagName === 'BR') || (n.nodeType === 3 && !n.data.trim())); n = li.lastChild) n.remove();
    if (!li.textContent.trim() && !li.querySelector('ul, ol')) li.remove();
  }
}

function cleanListItem(node, doc) {
  const li = doc.createElement('li');
  for (const cls of ['ted-checked', 'ted-pros', 'ted-cons']) {
    if (node.classList && node.classList.contains(cls)) li.classList.add(cls);
  }
  const nested = [];
  for (const child of Array.from(node.childNodes)) {
    if (child.nodeType === 1 && (child.tagName === 'UL' || child.tagName === 'OL')) {
      const l = cleanList(child, doc);
      if (l) nested.push(l);
    } else if (child.nodeType === 1 && isBlockish(child)) {
      if (hasInlineContent(li)) li.appendChild(doc.createElement('br'));
      cleanInlineChildren(child, li, doc);
    } else {
      cleanInlineNode(child, li, doc, {});
    }
  }
  trimBlock(li);
  for (const l of nested) li.appendChild(l);
  return li.firstChild ? li : null;
}

function cleanInlineChildren(src, dest, doc, opts = {}) {
  for (const child of Array.from(src.childNodes)) cleanInlineNode(child, dest, doc, opts);
}

function cleanInlineNode(node, dest, doc, opts) {
  if (node === opts.skipNode) return;
  if (node.nodeType === 3) {
    dest.appendChild(doc.createTextNode(collapse(node.data)));
    return;
  }
  if (node.nodeType !== 1) return;
  const tag = node.tagName.toUpperCase();
  if (DROP_TAGS.has(tag) || isHiddenNode(node)) return;

  if (tag === 'BR') {
    dest.appendChild(doc.createElement('br'));
    return;
  }

  if (tag === 'IMG' || RAW_TAGS.has(tag)) return; // внутри текста медиа не поддерживаем

  let target = dest;
  let mapped = INLINE_MAP[tag];

  // Google Docs оборачивает всё в <b style="font-weight:normal">
  if (tag === 'B' && /font-weight\s*:\s*(normal|[1-5]00)/i.test(node.getAttribute('style') || '')) mapped = null;
  if (mapped === 'strong' && opts.noStrong) mapped = null;

  if (mapped === 'a') {
    const href = (node.getAttribute('href') || '').trim();
    if (href && urlOk(href, 'link')) {   // общее правило ссылок (core/urls.js), то же на сервере
      const a = doc.createElement('a');
      a.setAttribute('href', href);
      if (node.getAttribute('target') === '_self') a.setAttribute('target', '_self');   // явно «в этой вкладке» (переключатель выключен)
      if (node.getAttribute('target') === '_blank') {
        a.setAttribute('target', '_blank');
        a.setAttribute('rel', 'noopener');
      }
      dest.appendChild(a);
      target = a;
    }
  } else if (mapped === 'mark') {
    // подложка под фрагментом текста: только с классом палитры, иначе <mark> без смысла — просто текст
    const bg = node.classList && Array.from(node.classList).find((c) => BG_CLASS.test(c));
    if (bg) {
      const el = doc.createElement('mark');
      el.className = bg;
      dest.appendChild(el);
      target = el;
    }
  } else if (mapped) {
    if (!hasAncestorTag(dest, mapped)) {
      const el = doc.createElement(mapped);
      dest.appendChild(el);
      target = el;
    }
  }

  // Стили span / font / и любых тегов: жирный, курсив, подчёркнутый, зачёркнутый
  const style = node.getAttribute('style') || '';
  if (style) {
    const wraps = [];
    if (!opts.noStrong && /font-weight\s*:\s*(bold|[6-9]00)/i.test(style)) wraps.push('strong');
    if (/font-style\s*:\s*italic/i.test(style)) wraps.push('em');
    if (/text-decoration[^;]*underline/i.test(style)) wraps.push('u');
    if (/text-decoration[^;]*line-through/i.test(style)) wraps.push('s');
    if (/vertical-align\s*:\s*super/i.test(style)) wraps.push('sup');
    if (/vertical-align\s*:\s*sub/i.test(style)) wraps.push('sub');
    for (const w of wraps) {
      if (hasAncestorTag(target, w) || w === mapped) continue;
      const el = doc.createElement(w);
      target.appendChild(el);
      target = el;
    }
  }

  const blockish = isBlockish(node);
  if (blockish && hasInlineContent(dest) && dest.lastChild && dest.lastChild.nodeName !== 'BR') {
    dest.insertBefore(doc.createElement('br'), target === dest ? null : topChildOf(dest, target));
  }
  cleanInlineChildren(node, target, doc, opts);

  // пустые обёртки не нужны
  if (target !== dest) removeEmptyChain(target, dest);
}

function topChildOf(root, el) {
  let n = el;
  while (n && n.parentNode !== root) n = n.parentNode;
  return n;
}

function removeEmptyChain(el, stopAt) {
  let n = el;
  while (n && n !== stopAt && !n.textContent && !n.querySelector('br')) {
    const parent = n.parentNode;
    parent.removeChild(n);
    n = parent;
  }
}

function hasAncestorTag(el, tagLower) {
  for (let n = el; n && n.nodeType === 1; n = n.parentNode) {
    if (n.tagName.toLowerCase() === tagLower) return true;
    if (isBlockTag(n.tagName) || n.tagName === 'LI') return false;
  }
  return false;
}

function hasBlockChild(node) {
  for (const c of node.children || []) {
    const t = c.tagName.toUpperCase();
    if (isBlockTag(t) || t === 'H1' || t === 'LI' || RAW_TAGS.has(t) || UNWRAP_BLOCK_TAGS.has(t) || t === 'TABLE') return true;
  }
  return false;
}

function isBlockish(node) {
  const t = node.tagName.toUpperCase();
  return t === 'P' || t === 'DIV' || t === 'H1' || isBlockTag(t) || UNWRAP_BLOCK_TAGS.has(t) || t === 'LI';
}

function hasInlineContent(el) {
  return !!(el.textContent && el.textContent.length);
}

function isHiddenNode(node) {
  const style = node.getAttribute && node.getAttribute('style');
  return !!(style && /display\s*:\s*none/i.test(style));
}

/** Инициалы для аватара автора: первые буквы первых двух слов. */
function initialsOf(text) {
  const words = String(text || '').trim().split(/\s+/).filter(Boolean).slice(0, 2);
  return words.map((w) => (w.match(/[\p{L}\p{N}]/u) || [''])[0]).join('').toUpperCase();
}

const LANG_RE = /^[\p{L}\p{N}+#.-]{1,20}$/u;

/** Внутри <pre> всегда есть <code>: в нём текст (в правке) или токены подсветки (в сохранённом HTML). */
function ensureCode(pre, doc = document) {
  let code = pre.querySelector(':scope > code');
  if (!code) {
    code = doc.createElement('code');
    while (pre.firstChild) code.appendChild(pre.firstChild);
    pre.appendChild(code);
  }
  return code;
}


/** Колонка номеров растягивается по самому длинному номеру: data-nums-d — число цифр (только если больше одной). */
function setNumsAttrs(pre, n) {
  pre.setAttribute('data-nums', Array.from({ length: n }, (_, i) => i + 1).join('\n'));
  const d = String(n).length;
  if (d > 1) pre.setAttribute('data-nums-d', String(d)); else pre.removeAttribute('data-nums-d');
}
/** Язык кода и номера строк — атрибуты <pre>: data-lang, data-nums (число строк считается по тексту); номера выключены явно — data-nonums. */
function applyCodeMeta(pre, lang, nums) {
  const code = ensureCode(pre, pre.ownerDocument);
  code.removeAttribute('data-nums');
  if (lang && LANG_RE.test(lang)) pre.setAttribute('data-lang', lang.toLowerCase());
  else pre.removeAttribute('data-lang');
  if (nums) {
    const n = (code.textContent.match(/\n/g) || []).length + 1;
    setNumsAttrs(pre, n);
  } else { pre.removeAttribute('data-nums'); pre.removeAttribute('data-nums-d'); }
  if (nums) pre.removeAttribute('data-nonums'); else pre.setAttribute('data-nonums', '');
}

function withAlign(el, src) {
  const align = (src.style && src.style.textAlign) || src.getAttribute('align') || '';
  let cls = '';
  let bg = '';
  if (src.classList) {
    for (const c of src.classList) { if (ALIGN_CLASS.test(c)) cls = c; if (BG_CLASS.test(c)) bg = c; }
  }
  if (!cls && /center/i.test(align)) cls = 'ted-align-center';
  if (!cls && /right|end/i.test(align)) cls = 'ted-align-right';
  // у чек-листа и шагов выравнивания нет
  if (src.classList && Array.from(src.classList).some((c) => /^ted-(checklist|steps)$/.test(c))) cls = '';
  // у чек-листа, шагов, цифр, плюсов и минусов, выноски фона нет
  if (src.classList && Array.from(src.classList).some((c) => /^ted-(checklist|steps|proscons)$/.test(c))) bg = '';
  const all = [cls, bg].filter(Boolean).join(' ');
  if (all) el.className = all;
  // якоря: id блока (латиница, цифры, дефис) сохраняется
  const id = src.getAttribute && src.getAttribute('id');
  if (id && ID_RE.test(id)) el.id = id;
  return el;
}

function collapse(text) {
  return text.replace(/[\t\n\r ]+/g, ' ').replace(/ /g, ' ');
}

function preText(node) {
  // <br> внутри <pre> → перенос строки
  let s = '';
  for (const c of node.childNodes) {
    if (c.nodeType === 3) s += c.data;
    else if (c.nodeName === 'BR') s += '\n';
    else if (c.nodeType === 1) {
      s += preText(c);
      if (c.tagName === 'DIV' || c.tagName === 'P') s += '\n';
    }
  }
  return s;
}

// Убираем пробелы и <br> по краям блока
function trimBlock(el) {
  const edge = (first) => {
    for (;;) {
      const n = first ? el.firstChild : el.lastChild;
      if (!n) return;
      if (n.nodeType === 3) {
        const t = first ? n.data.replace(/^[ \t\n\r]+/, '') : n.data.replace(/[ \t\n\r]+$/, '');
        if (!t) { el.removeChild(n); continue; }
        n.data = t;
        return;
      }
      if (n.nodeName === 'BR') { el.removeChild(n); continue; }
      if (n.nodeType === 1 && n.nodeName !== 'UL' && n.nodeName !== 'OL') {
        if (!n.textContent.trim() && !n.querySelector('br')) { el.removeChild(n); continue; }
      }
      return;
    }
  };
  edge(true);
  edge(false);
  // склеиваем соседние текстовые узлы
  el.normalize();
}

function makeRaw(node, doc = document) {
  // чистим внутри контейнера: корневой элемент блока тоже может оказаться запрещённым (<object>, <form>, чужой <iframe>)
  const holder = doc.createElement('div');
  holder.appendChild(node.cloneNode(true));
  stripDangerous(holder);
  const clone = holder.firstElementChild;
  if (!clone) return doc.createDocumentFragment();
  const wrap = doc.createElement('div');
  wrap.className = 'ted-ui-raw';
  wrap.setAttribute('contenteditable', 'false');
  wrap.setAttribute('data-ted-raw', holder.innerHTML);
  wrap.appendChild(clone);
  return wrap;
}


// Режим «сырого» HTML (старый контент TinyMCE: таблицы, картинки, iframe…). По умолчанию строгий: белый список сервера
// (core/allowlist.js) — iframe только с видеоплощадок (https) и в песочнице. Режим 'trusted' (опция rawHtml: 'trusted')
// оставляет теги как есть — только для доверенных авторов; сервер всё равно чистит по белому списку.
let strictRaw = true;
function setRawPolicy(mode) { strictRaw = mode !== 'trusted'; }
// Доверенный режим: атрибуты со ссылками — по общему правилу адресов (core/urls.js)
const URL_ATTRS = new Set(['href', 'src', 'data', 'action', 'formaction', 'poster', 'xlink:href', 'srcset', 'background', 'ping']);
const DROP_ATTRS = new Set(['srcdoc']);
const RAW_DROP_TAGS = new Set(['SCRIPT', 'STYLE', 'LINK', 'META', 'BASE', 'TEMPLATE', 'NOSCRIPT']);

/** Адрес в «сыром» HTML доверенного режима: общее правило (core/urls.js); href — ссылка, остальное — как у картинки. */
function unsafeUrl(value, name = 'src') {
  return !urlOk(String(value), name === 'href' ? 'link' : 'image');
}

/**
 * Старый «сырой» HTML. Строгий режим (по умолчанию): чистится тем же белым списком, что на сервере (core/allowlist.js) —
 * в редакторе остаётся ровно то, что сохранит и покажет сайт. Доверенный (rawHtml: 'trusted', только для доверенных авторов):
 * теги остаются, убираются скрипты, стили, обработчики, опасные адреса, srcdoc; сервер всё равно чистит по белому списку.
 */
function stripDangerous(root) {
  if (strictRaw) { cleanByAllowlist(root); return; }
  const all = root.querySelectorAll ? root.querySelectorAll('*') : [];
  for (const el of [root, ...all]) {
    if (!el || el.nodeType !== 1) continue;
    if (RAW_DROP_TAGS.has(el.tagName.toUpperCase())) { el.remove(); continue; }
    for (const attr of Array.from(el.attributes)) {
      const name = attr.name.toLowerCase();
      if (name.startsWith('on') || DROP_ATTRS.has(name)) el.removeAttribute(attr.name);
      else if (URL_ATTRS.has(name) && (name === 'srcset' ? !srcsetOk(attr.value) : unsafeUrl(attr.value, name))) el.removeAttribute(attr.name);
      else if (name === 'style' && /expression\s*\(|url\s*\(\s*['"]?\s*(javascript|vbscript):/i.test(attr.value)) el.removeAttribute(attr.name);
    }
  }
}

/** Чистый фрагмент → аккуратная HTML-строка: один блок на строку. */
function serializeBlocks(frag) {
  const parts = [];
  for (const node of Array.from(frag.childNodes)) {
    if (node.nodeType !== 1) continue;
    const wrapped = isWrap(node) ? node.firstElementChild : null;   // обёртка правки (медиа): сохраняется блок внутри
    const sd = defOf(wrapped || node);   // блок из реестра сохраняет себя сам (blocks/<тип>/<тип>.js → serialize)
    if (sd && sd.serialize) { const out = sd.serialize(wrapped || node, wrapped ? node : null); if (out) parts.push(out); continue; }
    if (isWrap(node)) continue;   // обёртка без блока внутри (всё вычищено) — не сохраняем
    if (node.classList.contains('ted-ui-raw')) {
      parts.push(node.getAttribute('data-ted-raw') || node.innerHTML);
    } else if (node.tagName === 'UL' || node.tagName === 'OL') {
      parts.push(serializeList(node, ''));
    } else if ((node.tagName === 'P' && !node.firstChild && !node.attributes.length)) {
      continue;   // <p></p> остаётся только от вычищенного (<base>, <math>…): очистка с первого раза даёт окончательный результат
    } else {
      parts.push(node.outerHTML);
    }
  }
  return parts.join('\n');
}

function serializeList(list, indent) {
  const tag = list.tagName.toLowerCase();
  const cls = (list.className ? ` class="${list.className}"` : '') + (list.id ? ` id="${list.id}"` : '');
  const items = [];
  for (const li of list.children) {
    const liCls = li.className ? ` class="${li.className}"` : '';
    let inline = '';
    const nested = [];
    for (const c of li.childNodes) {
      if (c.nodeType === 1 && (c.tagName === 'UL' || c.tagName === 'OL')) nested.push(c);
      else inline += c.nodeType === 1 ? c.outerHTML : escapeText(c.data);
    }
    if (nested.length) {
      items.push(`${indent}  <li${liCls}>${inline}\n${nested.map((n) => serializeList(n, indent + '    ')).join('\n')}\n${indent}  </li>`);
    } else {
      items.push(`${indent}  <li${liCls}>${inline}</li>`);
    }
  }
  const start = tag === 'ol' && list.hasAttribute('start') ? ` start="${list.start}"` : '';
  return `${indent}<${tag}${cls}${start}>\n${items.join('\n')}\n${indent}</${tag}>`;
}

function escapeText(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/ /g, '&nbsp;');
}

// ---- resources/js/core/selection.js ----
// Работа с выделением: сохранение/восстановление позиции курсора через
// «смещение в символах» от начала редактора. Так курсор переживает любые
// перестройки DOM (смена типа блока, undo/redo, нормализация).

/** Текущий Range, если он внутри root. */
function getRange(root) {
  const sel = root.ownerDocument.getSelection();
  if (!sel || !sel.rangeCount) return null;
  const range = sel.getRangeAt(0);
  if (!root.contains(range.commonAncestorContainer)) return null;
  return range;
}

// Каждый блок верхнего уровня добавляет 1 «символ»-разделитель, иначе позиция
// в конце одного блока и в начале следующего совпадала бы.
function walkOffset(root, container, offset) {
  let count = 0;
  let found = -1;
  const visit = (node, isBlockStart) => {
    if (found >= 0) return;
    if (node.nodeType === 1 && node.hasAttribute('data-tedui-media-panel')) return;
    if (node === container && node.nodeType !== 3) {
      // смещение указывает на дочерний узел
      for (let i = 0; i < offset && i < node.childNodes.length; i++) count += textLen(node.childNodes[i], node === root);
      found = count;
      return;
    }
    if (node.nodeType === 3) {
      if (node === container) {
        found = count + offset;
        return;
      }
      count += node.data.length;
      return;
    }
    const isRoot = node === root;
    for (const child of node.childNodes) {
      visit(child, isRoot);
      if (found >= 0) return;
      if (isRoot) count += 1;
    }
  };
  visit(root, false);
  return found < 0 ? count : found;
}

function textLen(node, isTopLevel) {
  let len = node.nodeType === 3 ? node.data.length : node.textContent.length;
  if (node.nodeType === 1 && isWrap(node)) {   // обёртка правки (медиа): текст её панели не считается
    for (const ui of node.querySelectorAll('[data-tedui-media-panel]')) len -= ui.textContent.length;
  }
  return len + (isTopLevel ? 1 : 0);
}

function saveSelection(root) {
  const range = getRange(root);
  if (!range) return null;
  return {
    start: walkOffset(root, range.startContainer, range.startOffset),
    end: walkOffset(root, range.endContainer, range.endOffset),
  };
}

function findPoint(root, target) {
  let count = 0;
  let lastText = null;
  for (let i = 0; i < root.childNodes.length; i++) {
    const block = root.childNodes[i];
    const len = textLen(block, false);
    if (target <= count + len) {
      const walker = root.ownerDocument.createTreeWalker(block, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
        acceptNode(node) {
          if (node.nodeType === 3) return NodeFilter.FILTER_ACCEPT;
          return node.hasAttribute('data-tedui-media-panel') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_SKIP;
        },
      });
      let local = target - count;
      let t;
      while ((t = walker.nextNode())) {
        lastText = t;
        if (local <= t.data.length) return { node: t, offset: local };
        local -= t.data.length;
      }
      // пустой блок: курсор в его начало
      return { node: block, offset: 0 };
    }
    count += len + 1;
  }
  if (lastText) return { node: lastText, offset: lastText.data.length };
  const last = root.lastChild;
  return last ? { node: last, offset: last.childNodes.length } : { node: root, offset: 0 };
}

function restoreSelection(root, saved) {
  if (!saved) return;
  const a = findPoint(root, saved.start);
  const b = saved.end === saved.start ? a : findPoint(root, saved.end);
  const range = root.ownerDocument.createRange();
  try {
    range.setStart(a.node, a.offset);
    range.setEnd(b.node, b.offset);
  } catch (e) {
    range.selectNodeContents(root);
    range.collapse(false);
  }
  const sel = root.ownerDocument.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
}

/** Блок верхнего уровня, в котором находится узел. */
function topBlockOf(root, node) {
  let n = node;
  while (n && n.parentNode !== root) {
    const parent = n.parentNode;
    if (!parent) return null;
    // тело контейнера (ответ аккордеона и т. п.) — свой «корень» блоков: блок — его прямой ребёнок
    if (parent.nodeType === 1 && parent.classList && parent.classList.contains('ted-ui-host') && root.contains(parent)) return n;
    n = parent;
  }
  return n && n.parentNode === root ? n : null;
}

/** Все блоки верхнего уровня, задетые выделением. */
function selectedBlocks(root) {
  const range = getRange(root);
  if (!range) return [];
  const first = topBlockOf(root, range.startContainer === root ? root.childNodes[range.startOffset] || root.lastChild : range.startContainer);
  const last = topBlockOf(root, range.endContainer === root ? root.childNodes[Math.max(0, range.endOffset - 1)] || root.lastChild : range.endContainer);
  if (!first) return [];
  const out = [];
  for (let n = first; n; n = n.nextSibling) {
    if (n.nodeType === 1) out.push(n);
    if (n === last) break;
  }
  return out;
}

/** Курсор в самом начале элемента? */
function isAtStart(el, range) {
  if (!range || !range.collapsed) return false;
  const r = el.ownerDocument.createRange();
  r.selectNodeContents(el);
  r.setEnd(range.startContainer, range.startOffset);
  return r.toString().length === 0;
}

/** Курсор в самом конце элемента? */
function isAtEnd(el, range) {
  if (!range || !range.collapsed) return false;
  const r = el.ownerDocument.createRange();
  r.selectNodeContents(el);
  r.setStart(range.endContainer, range.endOffset);
  return r.toString().length === 0;
}

function placeCaret(el, atEnd = false) {
  const range = el.ownerDocument.createRange();
  range.selectNodeContents(el);
  range.collapse(!atEnd);
  const sel = el.ownerDocument.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
}

// ---- resources/js/core/history.js ----
// Своя история изменений (Ctrl+Z / Ctrl+Y).
// Браузерный undo ломается, как только DOM меняется скриптом, поэтому
// храним снимки содержимого вместе с позицией курсора.
// Набор текста группируется: снимок делается после паузы.


const UI_ATTRS = / data-tedui-[a-z-]+="[^"]*"/g;

class History {
  constructor(root, { limit = 300, delay = 500, onRestore = null } = {}) {
    this.root = root;
    this.limit = limit;
    this.delay = delay;
    this.onRestore = onRestore;
    this.stack = [];
    this.index = -1;
    this.timer = null;
  }

  snapshot() {
    // обёртки правки (медиа) — без их панелей; служебные поля блоков (data-tedui-m: адрес, подпись) — тоже: их собирает интерфейс
    // заново, а восстановленные из снимка остались бы без обработчиков и лишний раз отличали бы снимки (22.11)
    const root = this.root.querySelector(wrapSelector() + ', [data-tedui-m]') ? this.root.cloneNode(true) : this.root;
    if (root !== this.root) root.querySelectorAll('[data-tedui-media-panel], [data-tedui-m]').forEach(node => node.remove());
    return {
      html: root.innerHTML.replace(UI_ATTRS, ''),
      sel: saveSelection(this.root),
    };
  }

  reset() {
    clearTimeout(this.timer);
    this.stack = [this.snapshot()];
    this.index = 0;
  }

  /** Зафиксировать текущее состояние (если оно изменилось). */
  commit() {
    clearTimeout(this.timer);
    this.timer = null;
    const snap = this.snapshot();
    const cur = this.stack[this.index];
    if (cur && cur.html === snap.html) {
      cur.sel = snap.sel || cur.sel;
      return false;
    }
    this.stack.splice(this.index + 1);
    this.stack.push(snap);
    if (this.stack.length > this.limit) this.stack.shift();
    this.index = this.stack.length - 1;
    return true;
  }

  /** Отложенный снимок — для набора текста. */
  schedule() {
    clearTimeout(this.timer);
    this.timer = setTimeout(() => this.commit(), this.delay);
  }

  canUndo() {
    return this.index > 0 || this.timer !== null;
  }

  canRedo() {
    return this.index < this.stack.length - 1;
  }

  undo() {
    this.commit();
    if (this.index <= 0) return false;
    this.index -= 1;
    this.apply(this.stack[this.index]);
    return true;
  }

  redo() {
    if (this.timer) this.commit();
    if (this.index >= this.stack.length - 1) return false;
    this.index += 1;
    this.apply(this.stack[this.index]);
    return true;
  }

  apply(snap) {
    this.root.innerHTML = snap.html;
    restoreSelection(this.root, snap.sel);
    if (this.onRestore) this.onRestore();
  }
}

// ---- resources/js/core/upload.js ----
// Прямая загрузка: XHR даёт реальный прогресс отправки и поддерживает отмену.
function createUpload(endpoint, { headers = {} } = {}) {
  // maxSide — картинку уменьшить до этой стороны (товар: размер карточки с запасом для ретины, 22.11); сервер ограничивает 160…2560
  const upload = (file, { kind, pagePath, signal, onProgress, maxSide } = {}) => new Promise((resolve, reject) => {
    const request = new XMLHttpRequest();
    const abortError = () => new DOMException('Загрузка отменена', 'AbortError');
    if (signal?.aborted) { reject(abortError()); return; }

    request.open('POST', endpoint);
    request.responseType = 'json';
    for (const [name, value] of Object.entries(headers)) request.setRequestHeader(name, value);
    request.upload.addEventListener('progress', (event) => {
      if (onProgress) onProgress(event.lengthComputable ? event.loaded / event.total : null);
    });
    request.addEventListener('load', () => {
      const response = request.response;
      if (request.status >= 200 && request.status < 300 && response?.url) resolve(response);
      else {
        const err = new Error(response?.error || 'Не удалось загрузить файл');
        err.status = request.status;   // 4xx (формат, размер) — повтор того же файла не поможет (проверка 22.11)
        reject(err);
      }
    });
    request.addEventListener('error', () => reject(new Error('Не удалось загрузить файл')));
    request.addEventListener('abort', () => reject(abortError()));
    const abort = () => request.abort();
    request.addEventListener('loadend', () => signal?.removeEventListener('abort', abort));
    signal?.addEventListener('abort', abort, { once: true });

    const body = new FormData();
    body.append('file', file);
    body.append('kind', kind || 'file');
    if (pagePath) body.append('pagePath', pagePath);
    if (maxSide) body.append('maxSide', String(Math.round(maxSide)));
    try { request.send(body); }
    catch (error) {
      signal?.removeEventListener('abort', abort);
      reject(error);
    }
  });
  // Удаление файлов с сервера после сохранения документа (тот же маршрут, action=delete)
  upload.remove = (urls, { pagePath } = {}) => {
    const body = new FormData();
    body.append('action', 'delete');
    body.append('urls', JSON.stringify(urls));
    if (pagePath) body.append('pagePath', pagePath);
    return fetch(endpoint, { method: 'POST', headers, body }).then((response) => {
      if (!response.ok) throw new Error('Не удалось удалить файлы');
      return response.json();
    });
  };
  // Картинка по ссылке: сервер скачивает и сжимает её сам (тот же маршрут, action=fetch) — чужой адрес в статье не остаётся
  upload.fromUrl = (url, { pagePath, signal } = {}) => {
    const body = new FormData();
    body.append('action', 'fetch');
    body.append('url', url);
    body.append('kind', 'image');
    if (pagePath) body.append('pagePath', pagePath);
    return fetch(endpoint, { method: 'POST', headers, body, signal }).then(async (response) => {
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data?.url) throw new Error(data?.error || 'Не удалось загрузить картинку');
      return data;
    });
  };
  return upload;
}

/** Первый кадр видеофайла как WebP-постер (null, если браузер не умеет этот формат). */
function videoPoster(file, maxWidth = 1280) {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const video = document.createElement('video');
    const done = (blob) => { URL.revokeObjectURL(url); video.removeAttribute('src'); video.load(); resolve(blob); };
    const timer = setTimeout(() => done(null), 8000);
    video.muted = true; video.preload = 'auto'; video.playsInline = true;
    video.addEventListener('error', () => { clearTimeout(timer); done(null); }, { once: true });
    video.addEventListener('loadeddata', () => { video.currentTime = Math.min(0.1, (video.duration || 1) / 2); }, { once: true });
    video.addEventListener('seeked', () => {
      clearTimeout(timer);
      const scale = Math.min(1, maxWidth / (video.videoWidth || maxWidth));
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(video.videoWidth * scale)); canvas.height = Math.max(1, Math.round(video.videoHeight * scale));
      try { canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height); canvas.toBlob((blob) => done(blob), 'image/webp', 0.82); }
      catch { done(null); }
    }, { once: true });
    video.src = url;
  });
}

function mediaPagePath(editor) {
  const { mediaPageUrl, pageUrl } = editor.options;
  if (mediaPageUrl) return new URL(mediaPageUrl, location.href).pathname;
  const value = typeof pageUrl === 'string' ? pageUrl : null;
  return new URL(value || location.href, location.href).pathname;
}

const MEDIA_ACCEPT = {
  image: 'image/jpeg,image/png,image/webp,image/gif,.jpg,.jpeg,.png,.webp,.gif',
  video: 'video/*,.mp4,.webm,.mov,.avi,.mkv,.m4v,.wmv,.flv,.mpg,.mpeg,.3gp',
  audio: 'audio/mpeg,audio/wav,.mp3,.wav',
  file: '.pdf,.docx,.xlsx,.zip',
};

/** Расширения, которые принимает блок (выбор из библиотеки CMS): файл другого вида не вставляется. «Файл» — любой документ. */
const MEDIA_EXT = {
  image: ['jpg', 'jpeg', 'png', 'webp', 'gif'],
  video: ['mp4', 'webm', 'mov', 'avi', 'mkv', 'm4v', 'wmv', 'flv', 'mpg', 'mpeg', '3gp'],
  audio: ['mp3', 'wav'],
  file: null,
};
const MEDIA_WRONG = { image: 'не изображение', video: 'не видео', audio: 'не аудио', file: 'не подходит' };
const extOf = (url) => (String(url).split(/[?#]/)[0].match(/\.([a-z0-9]+)$/i) || [])[1]?.toLowerCase() || '';

/**
 * Прямая загрузка и библиотека CMS вместе: загрузка настроена (upload) и передан pickFile — в зоне загрузки
 * есть ссылка «Из библиотеки» (Uploader/drop, library=true; заказчик 23.11).
 */
function canPickLibrary(editor) {
  const { mediaSource, pickFile, upload } = editor.options;
  return mediaSource === 'direct' && typeof upload === 'function' && typeof pickFile === 'function';
}

/**
 * Returns selected File objects in direct mode or asset descriptors in manager mode.
 * source: 'manager' — выбор из библиотеки и при прямой загрузке (ссылка «Из библиотеки» в зоне).
 */
async function chooseMedia(editor, kind, { multiple = false, source = null } = {}) {
  if (!Object.hasOwn(MEDIA_ACCEPT, kind)) throw new TypeError('Неизвестный тип медиа');
  const { mediaSource, pickFile, upload } = editor.options;
  if ((source || mediaSource) === 'manager') {
    if (typeof pickFile !== 'function') throw new Error('Файловый менеджер не настроен');
    // окна редактора закрываем: окно менеджера — поверх всего (22.11)
    editor.popover?.close();
    editor.subPopover?.close();
    // каждый вызов — свой номер: окно, закрытое без выбора, может так и не ответить; его поздний ответ не применяется
    const token = (editor.pickToken = (editor.pickToken || 0) + 1);
    const extensions = MEDIA_EXT[kind] || null;
    const selected = await pickFile({ kind, multiple, accept: MEDIA_ACCEPT[kind], extensions, pagePath: mediaPagePath(editor), editor });
    if (token !== editor.pickToken) return { source: 'manager', assets: [] };
    const all = [].concat(selected || []).filter(Boolean);
    // фильтр по виду: менеджер может отдать pdf в «Изображение» — такой файл пропускаем с сообщением
    const fits = (a) => !extensions || extensions.includes(extOf(a.url || a.name || ''));
    const assets = all.filter(fits);
    const wrong = all.filter((a) => !fits(a));
    if (wrong.length) editor.toast(`${wrong.map((a) => decodeURIComponent((a.name || a.url || '').split('/').pop())).join(', ')} — ${MEDIA_WRONG[kind]}, пропущено`, { status: 'error' });
    return { source: 'manager', assets: multiple ? assets : assets.slice(0, 1) };
  }
  if (typeof upload !== 'function') throw new Error('Прямая загрузка не настроена');
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = MEDIA_ACCEPT[kind];
  input.multiple = multiple;
  const assets = await new Promise((resolve) => {
    input.addEventListener('change', () => resolve([...input.files]), { once: true });
    input.addEventListener('cancel', () => resolve([]), { once: true });
    input.click();
  });
  return { source: 'direct', assets };
}

/** Карточка ссылки для блока «Встраивание»: страницу читает сервер CMS (src/OpenGraph.php), ответ — { url, title, text, image, site }. */
function createOpenGraph(endpoint, { headers = {} } = {}) {
  return async (url) => {
    const response = await fetch(endpoint, { method: 'POST', headers: { 'Content-Type': 'application/json', ...headers }, body: JSON.stringify({ url }) });
    let data = null;
    try { data = await response.json(); } catch (e) { data = null; }
    if (!response.ok || !data || data.error) throw new Error((data && data.error) || 'Не удалось получить карточку');
    return data;
  };
}

// ---- resources/js/core/presets.js ----
// Наборы (пресеты) — этап 2 MODULAR_PLAN.md. Набор = какие блоки доступны + как открывается редактор.
//
//   blocks — 'all' или список видов блоков ('p', 'h2', 'ul', 'image'…); абзац разрешён всегда;
//   mode   — 'edit' (сразу правка), 'view' (просмотр, «Редактировать» включает правку на той же странице),
//            'readonly' (только просмотр, правки нет).
//
// Набор поля задаёт СЕРВЕР CMS: Config::getClientJson($preset, $canEdit) → Ted.init({ server }). Он же очищает
// сохранённый HTML по набору (src/Presets.php) — браузеру в этом не доверяем. Опция preset в браузере — для страниц без PHP.
// Свои наборы: ted.config.php → 'presets' (сервер передаёт их в браузер сам) или Ted.definePreset(name, { blocks, mode }).

/* presets:begin — тот же список в src/Presets.php (Presets::BASE), тест tests/php/test-presets.php сравнивает */
const PRESETS = {
  "full": { "blocks": "all", "mode": "edit" },
  "mini": { "blocks": ["p", "h2", "h3", "h4", "ul", "ol", "blockquote", "image"], "mode": "edit" },
  "text": { "blocks": ["p", "ul", "ol"], "mode": "edit" },
  "readonly": { "blocks": "all", "mode": "readonly" },
  "docs": { "blocks": "all", "mode": "view" }
};
/* presets:end */

/* types:begin — виды блоков для наборов; тот же список в src/Presets.php (Presets::TYPES) */
const PRESET_TYPES = [];
/* types:end */
// Список пуст: все виды — из реестра блоков (blocks/<тип>/block.json), этап 5.
// Блоки из реестра (этап 5, blocks/<тип>/block.json) добавляются к списку сами: presetTypes(), presetAlias().

/** Другие имена видов (как в опции blocks): quote → blockquote, code → pre, separator → hr, bg / color → background. */
const PRESET_ALIASES = {};

/** Все виды блоков наборов: ядро + реестр. */
function presetTypes() { return [...PRESET_TYPES, ...registeredBlocks().map((d) => d.type)]; }

/** Вид по другому имени: quote → blockquote, separator → hr (block.json → aliases). */
function presetAlias(t) {
  if (PRESET_ALIASES[t]) return PRESET_ALIASES[t];
  const d = blockDef(t);
  return d ? d.type : t;
}
const MODES = ['edit', 'view', 'readonly'];
const NAME = /^[a-z][a-z0-9_-]{0,31}$/;

/** Свои наборы, заданные в браузере (Ted.definePreset). */
const defined = {};

/**
 * Проверить описание набора; вернуть { blocks: 'all' | [виды], mode }. Ошибка — исключение с понятным текстом
 * (те же правила, что у ted.config.php → presets).
 */
function checkPreset(name, def) {
  if (typeof name !== 'string' || !NAME.test(name)) throw new Error(`Набор «${name}»: имя — латиница, цифры, «-» и «_», начинается с буквы`);
  if (!def || typeof def !== 'object' || Array.isArray(def)) throw new Error(`Набор «${name}»: нужно описание { blocks, mode }`);
  const extra = Object.keys(def).filter((k) => k !== 'blocks' && k !== 'mode');
  if (extra.length) throw new Error(`Набор «${name}»: неизвестный ключ «${extra[0]}». Допустимы: blocks, mode`);
  const mode = def.mode === undefined ? 'edit' : def.mode;
  if (!MODES.includes(mode)) throw new Error(`Набор «${name}»: mode — ${MODES.join(', ')}`);
  let blocks = def.blocks === undefined ? 'all' : def.blocks;
  if (blocks !== 'all') {
    if (!Array.isArray(blocks) || !blocks.length) throw new Error(`Набор «${name}»: blocks — 'all' или список видов блоков`);
    const out = [];
    for (const t of blocks) {
      const type = typeof t === 'string' ? presetAlias(t) : t;
      if (!presetTypes().includes(type)) throw new Error(`Набор «${name}»: неизвестный блок «${t}». Допустимы: ${presetTypes().join(', ')}`);
      if (!out.includes(type)) out.push(type);
    }
    blocks = out;
  }
  return { blocks, mode };
}

/** Ted.definePreset(name, { blocks, mode }): свой набор в браузере. Базовые наборы не переопределяются. */
function definePreset(name, def) {
  if (Object.prototype.hasOwnProperty.call(PRESETS, name)) throw new Error(`Набор «${name}» — базовый, его нельзя переопределить; дайте своему набору другое имя`);
  defined[name] = checkPreset(name, def);
  return defined[name];
}

/** Описание набора по имени: базовые → с сервера (ted.config.php) → заданные в браузере. Нет такого — null. */
function presetOf(name, serverPresets = null) {
  if (typeof name !== 'string') return null;
  if (Object.prototype.hasOwnProperty.call(PRESETS, name)) return PRESETS[name];
  if (serverPresets && Object.prototype.hasOwnProperty.call(serverPresets, name)) return serverPresets[name];
  if (Object.prototype.hasOwnProperty.call(defined, name)) return defined[name];
  return null;
}

/** Имена всех известных наборов. */
function presetNames(serverPresets = null) {
  return [...new Set([...Object.keys(PRESETS), ...Object.keys(serverPresets || {}), ...Object.keys(defined)])];
}

// ---- resources/js/core/server.js ----
// Настройки с сервера (этап 1 MODULAR_PLAN.md): то, что браузеру нужно знать из ted.config.php.
// CMS передаёт их в Ted.init({ server: <?= Config::load()->getClientJson() ?> }). Пути на диске, ffmpeg и ключи сюда не попадают.
//   filesUrl    — адрес папки файлов ('/uf' или 'https://cdn…/uf'): по нему редактор узнаёт свои файлы (удаление после сохранения)
//   limits      — наибольший размер файла по видам, байт: слишком большой файл не отправляется на сервер
//   opengraph   — false: карточки по ссылке выключены на сервере (опция opengraph не используется)
//   iframeHosts — сайты для блока «iFrame»: null — любой https, список — только эти (сервер проверяет то же самое)
//   preset      — набор поля ('full', 'mini', 'text', 'readonly', 'docs' или свой): его задаёт сервер по настройке поля (этап 2)
//   presets     — свои наборы из ted.config.php → presets: { имя: { blocks, mode } }
//   canEdit     — false: у пользователя нет права правки — только просмотр, кнопки «Редактировать» нет

const KINDS = ['image', 'video', 'audio', 'file'];
const HOST = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i;

/** Проверенные настройки сервера; неверное значение заменяется значением по умолчанию (как до этапа 1). */
function serverOptions(raw) {
  const s = raw && typeof raw === 'object' ? raw : {};
  const url = typeof s.filesUrl === 'string' ? s.filesUrl.trim().replace(/\/+$/, '') : '';
  const filesUrl = /^(?:\/(?!\/)[^\s?#]*|https?:\/\/[^\s/?#@]+(?:\/[^\s?#]*)?)$/i.test(url) ? url : '/uf';
  const limits = {};
  for (const kind of KINDS) {
    const n = s.limits && Number(s.limits[kind]);
    if (Number.isFinite(n) && n > 0) limits[kind] = n;
  }
  const hosts = Array.isArray(s.iframeHosts)
    ? [...new Set(s.iframeHosts.filter((x) => typeof x === 'string' && HOST.test(x)).map((x) => x.toLowerCase()))]
    : null;
  // этап 2: набор поля, свои наборы из ted.config.php и право на правку — тоже решает сервер
  const presets = {};
  if (s.presets && typeof s.presets === 'object' && !Array.isArray(s.presets)) {
    for (const [name, def] of Object.entries(s.presets)) {
      if (Object.prototype.hasOwnProperty.call(PRESETS, name)) continue;   // базовые наборы не переопределяются
      try { presets[name] = checkPreset(name, def); } catch (e) { /* неверное описание пропускаем: сервер его не пропустил бы */ }
    }
  }
  const preset = typeof s.preset === 'string' && presetOf(s.preset, presets) ? s.preset : null;
  return { filesUrl, limits, opengraph: s.opengraph !== false, iframeHosts: hosts, preset, presets, canEdit: s.canEdit !== false };
}

/** Размер для сообщения: «5 МБ», «2,5 МБ». */
function formatLimit(bytes) {
  const mb = bytes / 1048576;
  return `${(Math.round(mb * 10) / 10).toString().replace('.', ',')} МБ`;
}

// ---- resources/js/core/containers.js ----
// Блоки-контейнеры этапа 6: внутри — обычные блоки (абзацы, списки, медиа, таблица …), кроме цветного фона и других контейнеров.
// В редакторе тело контейнера — «хост» блоков (.ted-ui-host): определение текущего блока, «/», медиа и Enter работают в нём,
// как в корне. На сайте — своя разметка без скриптов (аккордеон — <details>/<summary> с разметкой FAQ schema.org).

const HOST_CLASS = 'ted-ui-host';
/** CSS-селектор контейнеров: блоки реестра с block.json → container (аккордеон, вкладки, колонки). */
const containerSel = () => registeredBlocks().filter((d) => d.container && d.selector).map((d) => d.selector).join(', ') || ':not(*)';

/** Элемент — тело контейнера, где лежат блоки. */
const isHost = (el) => !!(el && el.nodeType === 1 && el.classList.contains(HOST_CLASS));

/** Родитель блоков: корень редактора или тело контейнера внутри него. */
const isBlockParent = (el, root) => el === root || (isHost(el) && root.contains(el));

/** Блок верхнего уровня (прямой ребёнок корня), внутри которого лежит узел. */
function rootBlockOf(root, node) {
  let n = node;
  while (n && n.parentNode !== root) { n = n.parentNode; if (!n) return null; }
  return n && n.parentNode === root ? n : null;
}

const isContainer = (el) => !!(el && el.nodeType === 1 && el.matches(containerSel()));

/** Внутри тела контейнера нет цветного фона и других контейнеров (вложенные раскрываются в текст). */
function stripInHost(frag, doc) {
  for (const el of [...frag.querySelectorAll('[class*="ted-bg-"]')]) {
    for (const c of [...el.classList]) if (c.startsWith('ted-bg-')) el.classList.remove(c);
    if (!el.className) el.removeAttribute('class');
  }
  // блок, который в теле контейнера не живёт, раскрывается в текст сам (blocks/<тип>/<тип>.js → unnest: вкладки, аккордеон, колонки)
  for (const d of registeredBlocks()) {
    if (!d.unnest || !d.selector) continue;
    for (const inner of [...frag.querySelectorAll(d.selector)]) inner.replaceWith(d.unnest(inner, doc));
  }
}

// ---- blocks/table/formula.js ----
// Формулы в таблице (этап 6.1б): свой разборщик без eval.
// Ссылки A1 … J100 (столбцы A–J, строки с 1 — первая строка таблицы, включая шапку), диапазоны B2:B5, закреплённые $A$1.
// Арифметика + − * /, скобки, унарный минус, проценты (20%). Функции: SUM, AVERAGE, MIN, MAX, COUNT, ROUND
// и русские СУММ, СРЗНАЧ, МИН, МАКС, СЧЁТ, ОКРУГЛ. Разделитель аргументов — «;» (запятая — десятичная).
// Ошибки: #ДЕЛ/0!, #ССЫЛКА!, #ЦИКЛ!, #ОШИБКА!. Числа — по-русски (1 234,5), единицы ₽ и %.

const FORMULA_ERRORS = ['#ДЕЛ/0!', '#ССЫЛКА!', '#ЦИКЛ!', '#ОШИБКА!'];
const ERR = { div: '#ДЕЛ/0!', ref: '#ССЫЛКА!', cycle: '#ЦИКЛ!', bad: '#ОШИБКА!' };

/** Функции для списка под ячейкой: русское имя (оно вставляется), английское, подсказка. */
const FORMULA_FUNCS = [
  { name: 'СУММ', en: 'SUM', hint: 'Сумма' },
  { name: 'СРЗНАЧ', en: 'AVERAGE', hint: 'Среднее' },
  { name: 'МИН', en: 'MIN', hint: 'Наименьшее' },
  { name: 'МАКС', en: 'MAX', hint: 'Наибольшее' },
  { name: 'СЧЁТ', en: 'COUNT', hint: 'Количество чисел' },
  { name: 'ОКРУГЛ', en: 'ROUND', hint: 'Округление' },
];
const FN = {};
for (const f of FORMULA_FUNCS) { FN[f.name] = f.en; FN[f.en] = f.en; }
FN['СЧЕТ'] = 'COUNT';

const MAX_COL = 10;
const MAX_ROW = 100;
const colName = (c) => String.fromCharCode(65 + c);
const refName = (c, r, ac = false, ar = false) => `${ac ? '$' : ''}${colName(c)}${ar ? '$' : ''}${r + 1}`;

// ---------- лексер ----------

const LETTER = /[A-Za-zА-Яа-яЁё_]/;

function formulaTokens(src) {
  const out = [];
  let i = 0;
  while (i < src.length) {
    const ch = src[i];
    if (/\s/.test(ch)) { i += 1; continue; }
    // ссылка: $?БУКВА$?ЦИФРЫ, за ней не буква, не цифра и не «(»
    const ref = /^(\$?)([A-Za-z])(\$?)(\d{1,3})(?![\dA-Za-zА-Яа-яЁё_(])/.exec(src.slice(i));
    if (ref && !(i > 0 && LETTER.test(src[i - 1]))) {
      out.push({ t: 'ref', c: ref[2].toUpperCase().charCodeAt(0) - 65, r: Number(ref[4]) - 1, ac: !!ref[1], ar: !!ref[3], s: i, e: i + ref[0].length });
      i += ref[0].length;
      continue;
    }
    const num = /^\d+(?:[.,]\d+)?/.exec(src.slice(i));
    if (num) { out.push({ t: 'num', v: Number(num[0].replace(',', '.')) }); i += num[0].length; continue; }
    const word = /^[A-Za-zА-Яа-яЁё_]+/.exec(src.slice(i));
    if (word) { out.push({ t: 'name', v: word[0].toUpperCase() }); i += word[0].length; continue; }
    if ('+-*/()%:;,'.includes(ch)) { out.push({ t: ch }); i += 1; continue; }
    if (ch === '−' || ch === '–' || ch === '—') { out.push({ t: '-' }); i += 1; continue; }   // типограф мог заменить минус
    if (ch === '×') { out.push({ t: '*' }); i += 1; continue; }
    if (ch === '÷') { out.push({ t: '/' }); i += 1; continue; }
    if (ch === '#') {   // ссылка на удалённую ячейку после правки структуры
      const m = /^#[^\s+\-*/();,]+/.exec(src.slice(i));
      out.push({ t: 'err', v: ERR.ref });
      i += m ? m[0].length : 1;
      continue;
    }
    throw new Error('bad');
  }
  return out;
}

// ---------- разбор (рекурсивный спуск) ----------

/** Разобрать формулу «=…» в дерево. Ошибка синтаксиса — исключение. */
function parseFormula(text) {
  const src = String(text || '').replace(/^\s*=/, '');
  const toks = formulaTokens(src);
  let p = 0;
  const peek = () => toks[p];
  const take = (t) => { if (!toks[p] || toks[p].t !== t) throw new Error('bad'); return toks[p++]; };
  const expr = () => {
    let left = term();
    while (peek() && (peek().t === '+' || peek().t === '-')) { const op = toks[p++].t; left = { t: 'bin', op, l: left, r: term() }; }
    return left;
  };
  const term = () => {
    let left = unary();
    while (peek() && (peek().t === '*' || peek().t === '/')) { const op = toks[p++].t; left = { t: 'bin', op, l: left, r: unary() }; }
    return left;
  };
  const unary = () => {
    if (peek() && peek().t === '-') { p += 1; return { t: 'neg', x: unary() }; }
    if (peek() && peek().t === '+') { p += 1; return unary(); }
    let x = primary();
    while (peek() && peek().t === '%') { p += 1; x = { t: 'pct', x }; }
    return x;
  };
  const primary = () => {
    const tk = peek();
    if (!tk) throw new Error('bad');
    if (tk.t === 'num') { p += 1; return { t: 'num', v: tk.v }; }
    if (tk.t === 'err') { p += 1; return { t: 'err', v: tk.v }; }
    if (tk.t === 'ref') {
      p += 1;
      if (peek() && peek().t === ':') { p += 1; const b = take('ref'); return { t: 'range', a: tk, b }; }
      return { t: 'ref', ...tk };
    }
    if (tk.t === 'name') {
      p += 1;
      const fn = FN[tk.v];
      if (!fn) throw new Error('bad');
      take('(');
      const args = [];
      if (peek() && peek().t !== ')') {
        args.push(expr());
        while (peek() && (peek().t === ';' || peek().t === ',')) { p += 1; args.push(expr()); }
      }
      take(')');
      return { t: 'fn', fn, args };
    }
    if (tk.t === '(') { p += 1; const x = expr(); take(')'); return x; }
    throw new Error('bad');
  };
  const tree = expr();
  if (p !== toks.length) throw new Error('bad');
  return tree;
}

// ---------- значения ячеек ----------

/** Текст ячейки → число с единицей ({ v, unit }), пусто ({ empty }) или текст ({ text }). «1 234,5 ₽», «15%», «−3». */
function parseCellValue(text) {
  const s = String(text || '').replace(/[   ​]/g, ' ').trim();
  if (!s) return { empty: true };
  if (FORMULA_ERRORS.includes(s)) return { err: s };
  const m = /^([-−–+]?)\s*(\d{1,3}(?:[ ]\d{3})+|\d+)(?:[.,](\d+))?\s*(₽|руб\.?|р\.|%)?$/i.exec(s);
  if (!m) return { text: s };
  let v = Number(`${m[2].replace(/ /g, '')}.${m[3] || '0'}`);
  if (m[1] && m[1] !== '+') v = -v;
  const u = m[4] ? (m[4] === '%' ? '%' : '₽') : '';
  if (u === '%') v /= 100;
  return { v, unit: u };
}

const nf = new Map();
function fmt(v, digits) {
  if (!nf.has(digits)) nf.set(digits, new Intl.NumberFormat('ru-RU', { maximumFractionDigits: digits, useGrouping: true }));
  return nf.get(digits).format(v).replace(/ /g, ' ');
}

/** Число → текст ячейки: по-русски, с ₽ или %. */
function formatValue(v, unit = '') {
  if (!Number.isFinite(v)) return ERR.bad;
  const clean = Math.abs(v) < 1e-12 ? 0 : Number(v.toPrecision(12));
  if (unit === '%') return `${fmt(clean * 100, 2)}%`;
  if (unit === '₽') return `${fmt(clean, 2)} ₽`;
  return fmt(clean, 10);
}

// ---------- вычисление ----------

class FErr extends Error { constructor(code) { super(code); this.code = code; } }

/**
 * Вычислить дерево. cell(r, c) → { v, unit } | { empty } | { text } | { err } — значение ячейки (формулы считает сама таблица).
 * Возвращает { v, unit } или { err }.
 */
function evaluate(tree, cell, size) {
  const inside = (r, c) => r >= 0 && c >= 0 && r < size.rows && c < size.cols;
  const at = (r, c) => {
    if (!inside(r, c)) throw new FErr(ERR.ref);
    const x = cell(r, c);
    if (x.err) throw new FErr(x.err);
    return x;
  };
  const scalar = (x) => {
    if (x.empty) return { v: 0, unit: '' };
    if (x.text !== undefined) throw new FErr(ERR.bad);
    return x;
  };
  const unitOf = (a, b, op) => {
    if (op === '+' || op === '-') return a.unit && b.unit && a.unit !== b.unit ? '' : (a.unit || b.unit);
    if (op === '*') { if (a.unit === '%') return b.unit === '%' ? '' : b.unit; if (b.unit === '%') return a.unit; return a.unit && b.unit ? '' : (a.unit || b.unit); }
    if (op === '/') { if (b.unit === '%') return a.unit; return a.unit && a.unit === b.unit ? '' : a.unit; }
    return '';
  };
  const values = (node) => {   // аргумент функции: диапазон или выражение → список чисел (пустые и текст в диапазоне пропускаются)
    if (node.t === 'range') {
      const r1 = Math.min(node.a.r, node.b.r); const r2 = Math.max(node.a.r, node.b.r);
      const c1 = Math.min(node.a.c, node.b.c); const c2 = Math.max(node.a.c, node.b.c);
      const out = [];
      for (let r = r1; r <= r2; r += 1) for (let c = c1; c <= c2; c += 1) { const x = at(r, c); if (x.v !== undefined) out.push(x); }
      return out;
    }
    if (node.t === 'ref') { const x = at(node.r, node.c); return x.v !== undefined ? [x] : []; }
    return [ev(node)];
  };
  const common = (list) => { const u = new Set(list.map((x) => x.unit).filter(Boolean)); return u.size === 1 ? [...u][0] : ''; };
  const ev = (n) => {
    switch (n.t) {
      case 'num': return { v: n.v, unit: '' };
      case 'err': throw new FErr(n.v);
      case 'ref': return scalar(at(n.r, n.c));
      case 'range': throw new FErr(ERR.bad);
      case 'neg': { const x = ev(n.x); return { v: -x.v, unit: x.unit }; }
      case 'pct': { const x = ev(n.x); return { v: x.v / 100, unit: '%' }; }
      case 'bin': {
        const a = ev(n.l); const b = ev(n.r);
        let v;
        if (n.op === '+') v = a.v + b.v;
        else if (n.op === '-') v = a.v - b.v;
        else if (n.op === '*') v = a.v * b.v;
        else { if (b.v === 0) throw new FErr(ERR.div); v = a.v / b.v; }
        return { v, unit: unitOf(a, b, n.op) };
      }
      case 'fn': {
        if (n.fn === 'ROUND') {
          if (!n.args.length || n.args.length > 2) throw new FErr(ERR.bad);
          const x = ev(n.args[0]);
          const d = n.args[1] ? Math.trunc(ev(n.args[1]).v) : 0;
          const k = 10 ** d;
          return { v: Math.round((x.v + Math.sign(x.v) * Number.EPSILON) * k) / k, unit: x.unit };
        }
        const list = n.args.flatMap(values);
        if (n.fn === 'COUNT') return { v: list.length, unit: '' };
        if (!n.args.length) throw new FErr(ERR.bad);
        const unit = common(list);
        if (n.fn === 'SUM') return { v: list.reduce((s, x) => s + x.v, 0), unit };
        if (!list.length) { if (n.fn === 'AVERAGE') throw new FErr(ERR.div); return { v: 0, unit }; }
        if (n.fn === 'AVERAGE') return { v: list.reduce((s, x) => s + x.v, 0) / list.length, unit };
        if (n.fn === 'MIN') return { v: Math.min(...list.map((x) => x.v)), unit };
        return { v: Math.max(...list.map((x) => x.v)), unit };
      }
      default: throw new FErr(ERR.bad);
    }
  };
  try {
    const x = ev(tree);
    if (!Number.isFinite(x.v)) return { err: ERR.bad };
    return x;
  } catch (e) {
    return { err: e instanceof FErr ? e.code : ERR.bad };
  }
}

/** Вычислить все формулы сетки. grid[r][c] = { formula?: '=…', text: '…' }. Возвращает Map 'r:c' → { v, unit } | { err }. */
function computeGrid(grid) {
  const rows = grid.length;
  const cols = rows ? Math.max(...grid.map((r) => r.length)) : 0;
  const memo = new Map();
  const busy = new Set();
  const trees = new Map();
  const value = (r, c) => {
    const key = `${r}:${c}`;
    const cellData = grid[r] && grid[r][c];
    if (!cellData) return { empty: true };
    if (!cellData.formula) return parseCellValue(cellData.text);
    if (memo.has(key)) return memo.get(key);
    if (busy.has(key)) return { err: ERR.cycle };
    busy.add(key);
    let res;
    try {
      if (!trees.has(key)) trees.set(key, parseFormula(cellData.formula));
      res = evaluate(trees.get(key), value, { rows, cols });
    } catch (e) {
      res = { err: ERR.bad };
    }
    busy.delete(key);
    // ячейка в цикле: ошибка цикла у всех, кто в нём
    memo.set(key, res);
    return res;
  };
  const out = new Map();
  for (let r = 0; r < rows; r += 1) {
    for (let c = 0; c < (grid[r] || []).length; c += 1) if (grid[r][c] && grid[r][c].formula) out.set(`${r}:${c}`, value(r, c));
  }
  return out;
}

/** Результат → текст ячейки. */
const resultText = (res) => (res.err ? res.err : formatValue(res.v, res.unit));

// ---------- правка ссылок ----------

/**
 * Переписать ссылки формулы. map({ c, r, ac, ar }) → { c, r } (новое место) или null (ячейка удалена → #ССЫЛКА!).
 * Остальной текст формулы не меняется.
 */
function rewriteRefs(formula, map) {
  const src = String(formula || '');
  const body = src.replace(/^\s*=/, '');
  const offset = src.length - body.length;
  let toks;
  try { toks = formulaTokens(body); } catch (e) { return src; }
  // роль ссылки: одиночная или начало / конец диапазона (при удалении строки диапазон сужается, а не ломается)
  toks.forEach((tk, i) => {
    if (tk.t !== 'ref') return;
    if (toks[i + 1] && toks[i + 1].t === ':' && toks[i + 2] && toks[i + 2].t === 'ref') { tk.role = 'start'; tk.pair = toks[i + 2]; toks[i + 2].role = 'end'; toks[i + 2].pair = tk; }
    else if (!tk.role) tk.role = 'single';
  });
  let out = src;
  for (const tk of toks.filter((x) => x.t === 'ref').reverse()) {
    const to = map(tk);
    const text = to ? refName(to.c, to.r, tk.ac, tk.ar) : ERR.ref;
    out = out.slice(0, offset + tk.s) + text + out.slice(offset + tk.e);
  }
  return out;
}

/** Сдвиг формулы при копировании протягиванием (как в Google Таблицах): $ не сдвигается; вышедшие за таблицу — #ССЫЛКА!. */
function shiftFormula(formula, dr, dc) {
  return rewriteRefs(formula, (tk) => {
    const r = tk.ar ? tk.r : tk.r + dr;
    const c = tk.ac ? tk.c : tk.c + dc;
    return r < 0 || c < 0 || r >= MAX_ROW || c >= MAX_COL ? null : { r, c };
  });
}

/** Ссылки формулы (для подсветки при правке): [{ r1, c1, r2, c2 }]. */
function formulaRanges(formula) {
  let toks;
  try { toks = formulaTokens(String(formula || '').replace(/^\s*=/, '')); } catch (e) { return []; }
  const out = [];
  for (let i = 0; i < toks.length; i += 1) {
    const a = toks[i];
    if (a.t !== 'ref') continue;
    if (toks[i + 1] && toks[i + 1].t === ':' && toks[i + 2] && toks[i + 2].t === 'ref') {
      const b = toks[i + 2];
      out.push({ r1: Math.min(a.r, b.r), c1: Math.min(a.c, b.c), r2: Math.max(a.r, b.r), c2: Math.max(a.c, b.c) });
      i += 2;
    } else out.push({ r1: a.r, c1: a.c, r2: a.r, c2: a.c });
  }
  return out;
}

/** Можно ли сохранить формулу (для очистки HTML): начинается с «=», только допустимые знаки, до 500 знаков. */
function formulaAllowed(text) {
  return typeof text === 'string' && text.length <= 500 && /^=[0-9A-Za-zА-Яа-яЁё$:;,.+\-−–—*/×÷()%#!\s]*$/.test(text);
}

/**
 * Ссылки формул таблицы после правки структуры. axis — 'row' или 'col'; kind — 'move' (from, to), 'insert' (at), 'remove' (at).
 * Ссылка на удалённую ячейку — #ССЫЛКА!; диапазон, задевший удалённую строку, сужается.
 */
function structureMap(kind, a, b) {
  if (kind === 'move') return (i) => (i === a ? b : a < b && i > a && i <= b ? i - 1 : b < a && i >= b && i < a ? i + 1 : i);
  if (kind === 'insert') return (i) => (i >= a ? i + 1 : i);
  return (i, tk) => {
    if (i < a) return i;
    if (i > a) return i - 1;
    if (tk.role === 'start' && tk.pair && (tk.pair.ar ? tk.pair.r : tk.pair.r) !== undefined) {
      const other = tk.pair;
      const otherIdx = tk.axis === 'row' ? other.r : other.c;
      return otherIdx > a ? a : null;
    }
    if (tk.role === 'end' && tk.pair) {
      const otherIdx = tk.axis === 'row' ? tk.pair.r : tk.pair.c;
      return otherIdx < a ? a - 1 : null;
    }
    return null;
  };
}

/** Переписать все формулы ячеек (cells — элементы с data-formula) по карте индексов строки или столбца. */
function remapFormulas(cells, axis, map) {
  for (const cell of cells) {
    const v = cell.getAttribute('data-formula');
    const n = rewriteRefs(v, (tk) => {
      tk.axis = axis;
      const idx = axis === 'row' ? tk.r : tk.c;
      const ni = map(idx, tk);
      if (ni === null || ni < 0) return null;
      return axis === 'row' ? { r: ni, c: tk.c } : { r: tk.r, c: ni };
    });
    if (n !== v) cell.setAttribute('data-formula', n);
  }
}

// ---- blocks/media/file-names.js ----
// Название файла в плитке: не длиннее двух строк, дальше многоточие. Для обрезки текст ссылки оборачивается в <span class="ted-media__name">
// (одно CSS-правило на самой ссылке обрезало бы текст только при авто-высоте и ломало бы центровку). В сохранённом HTML обёртки нет:
// её ставит редактор в блоке и content.js на сайте.
function wrapFileNames(root) {
  for (const link of root.querySelectorAll('.ted-media--file > a')) {
    if (link.querySelector(':scope > .ted-media__name')) continue;
    const texts = [...link.childNodes].filter((node) => node.nodeType === 3);
    if (!texts.length) continue;
    const name = link.ownerDocument.createElement('span');
    name.className = 'ted-media__name';
    texts[0].before(name);
    name.append(...texts);
  }
}

// ---- blocks/media/video-link.js ----
// Кнопка «Смотреть на YouTube» (Buttons/main secondary s) под плеером площадки: если автор запретил встраивание,
// читатель всё равно может открыть видео на самой площадке. Ставят content.js на сайте и редактор под превью; в сохранённом HTML её нет.
function videoSourceLabel(href) {
  let host = '';
  try { host = new URL(href).hostname.replace(/^www\./, ''); } catch { return ''; }
  if (/^(m\.)?youtube(-nocookie)?\.com$|^youtu\.be$/.test(host)) return 'Смотреть на YouTube';
  if (host === 'rutube.ru') return 'Смотреть на RuTube';
  if (host === 'vkvideo.ru' || host === 'vk.com') return 'Смотреть в VK Видео';
  return '';
}

function videoSourceButton(doc, href) {
  const label = videoSourceLabel(href);
  if (!label) return null;
  const link = doc.createElement('a');
  link.className = 'ted-media__source';
  link.href = href;
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
  link.textContent = label;
  return link;
}

// ---- blocks/media/audio-player.js ----
// Аудиоплеер по макету Media/audio (библиотека «Симфлекс АИ»): кнопка play, волна, время, линия и название.
// Файл в HTML остаётся обычным <audio controls>; плеер строится поверх него и управляет им.
// В редакторе плеер стоит в панели блока, на сайте его собирает Ted.enhance().

const AP_PLAY = '<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M8 5.5v13a1 1 0 0 0 1.54.84l10-6.5a1 1 0 0 0 0-1.68l-10-6.5A1 1 0 0 0 8 5.5Z" fill="currentColor"/></svg>';
const AP_PAUSE = '<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><rect x="6.5" y="5" width="4" height="14" rx="1" fill="currentColor"/><rect x="13.5" y="5" width="4" height="14" rx="1" fill="currentColor"/></svg>';
const AP_BASE = 160;          // сколько значений громкости хранится; столбиков на экране столько, сколько помещается
const AP_BAR = 5;             // ширина столбика в макете
const AP_GAP = 2;             // промежуток между столбиками

const apTime = (s) => {
  if (!Number.isFinite(s) || s < 0) return '0:00';
  return `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
};

/** Условная волна, если настоящую прочитать нельзя (чужой сервер, большой файл): одна и та же для одного адреса. */
function apPseudoPeaks(seed) {
  let x = 2166136261;
  for (const ch of String(seed)) x = Math.imul(x ^ ch.charCodeAt(0), 16777619);
  const rand = () => { x ^= x << 13; x ^= x >>> 17; x ^= x << 5; return (x >>> 0) / 4294967296; };
  const out = [];
  let level = 0.5;
  for (let i = 0; i < AP_BASE; i++) {
    level = Math.max(0.08, Math.min(1, level + (rand() - 0.5) * 0.7));
    out.push(level);
  }
  return out;
}

/** Настоящая волна из файла (только свой сервер и файл до 12 МБ), иначе null. */
const AP_CACHE = new Map();   // волна одного файла считается один раз, а не при каждой перерисовке блока
async function apReadPeaks(src) {
  if (AP_CACHE.has(src)) return AP_CACHE.get(src);
  const value = await apDecode(src);
  AP_CACHE.set(src, value);
  return value;
}

async function apDecode(src) {
  try {
    const url = new URL(src, location.href);
    if (url.origin !== location.origin) return null;
    const response = await fetch(url);
    if (!response.ok || Number(response.headers.get('content-length') || 0) > 12e6) return null;
    const Context = window.AudioContext || window.webkitAudioContext;
    if (!Context) return null;
    const ctx = new Context();
    const decoded = await ctx.decodeAudioData(await response.arrayBuffer());
    ctx.close();
    const data = decoded.getChannelData(0);
    const step = Math.max(1, Math.floor(data.length / AP_BASE));
    // громкость участка — среднеквадратичное, а не максимум: у плотной музыки максимум везде одинаков и волна получается сплошной
    const loud = [];
    for (let i = 0; i < AP_BASE; i++) {
      let sum = 0;
      let n = 0;
      for (let j = i * step; j < Math.min(data.length, (i + 1) * step); j += 8) { sum += data[j] * data[j]; n++; }
      loud.push(Math.sqrt(sum / Math.max(1, n)));
    }
    const sorted = [...loud].sort((x, y) => x - y);
    const top = sorted[Math.floor(sorted.length * 0.95)] || 1;
    return loud.map((p) => Math.max(0.08, Math.min(1, p / top) ** 1.6));
  } catch { return null; }
}

/**
 * Плеер для готового элемента <audio>. name — название под волной (по макету «Название»).
 * Возвращает элемент плеера; обработчики снимаются, когда элемент уходит из документа.
 */
function buildAudioPlayer(audio, { name = '', placeholder = '', onName = null } = {}) {
  const doc = audio.ownerDocument;
  const el = doc.createElement('div');
  el.className = 'ted-audio';
  const play = doc.createElement('button');
  play.type = 'button';
  play.className = 'ted-audio__play';
  play.setAttribute('aria-label', 'Воспроизвести');
  play.innerHTML = AP_PLAY;
  const wave = doc.createElement('div');
  wave.className = 'ted-audio__wave';
  wave.setAttribute('role', 'slider');
  wave.setAttribute('aria-label', 'Положение в записи');
  wave.tabIndex = 0;
  const now = doc.createElement('span');
  now.textContent = '0:00';
  const total = doc.createElement('span');
  total.textContent = '0:00';
  const clock = doc.createElement('div');
  clock.className = 'ted-audio__time';
  clock.append(now, total);
  const track = doc.createElement('div');
  track.className = 'ted-audio__track';
  track.append(wave, clock);
  const controls = doc.createElement('div');
  controls.className = 'ted-audio__controls';
  controls.append(play, track);
  const line = doc.createElement('div');
  line.className = 'ted-audio__line';
  const title = doc.createElement('div');
  title.className = 'ted-audio__name';
  // в редакторе без названия стоит заготовка «Название» (по макету строка есть всегда), на сайте пустая строка скрыта
  title.textContent = name || placeholder;
  title.classList.toggle('is-empty', !name && !!placeholder);
  title.hidden = !name && !placeholder;
  line.hidden = title.hidden;
  if (onName) { title.addEventListener('click', onName); title.style.cursor = 'text'; }
  const body = doc.createElement('div');
  body.className = 'ted-audio__body';
  body.append(controls, line, title);
  el.append(body);

  let peaks = apPseudoPeaks(audio.getAttribute('src') || '');
  let bars = [];
  let layoutHeight = 0;
  let layoutWidth = 0;
  const paint = () => {
    const fraction = audio.duration ? audio.currentTime / audio.duration : 0;
    const played = Math.round(fraction * bars.length);
    bars.forEach((bar, i) => bar.classList.toggle('is-played', i < played));
    now.textContent = apTime(audio.currentTime);
    total.textContent = apTime(audio.duration);
    wave.setAttribute('aria-valuenow', String(Math.round(fraction * 100)));
  };
  const layout = () => {
    if (wave.clientWidth === layoutWidth && wave.clientHeight === layoutHeight && bars.length) return;
    layoutWidth = wave.clientWidth;
    layoutHeight = wave.clientHeight;
    // ширина столбика и промежуток зависят от размера страницы (vw-режим), поэтому измеряем их, а не считаем в px
    const probe = doc.createElement('i');
    wave.replaceChildren(probe);
    const barWidth = probe.getBoundingClientRect().width || AP_BAR;
    const gap = parseFloat(getComputedStyle(wave).columnGap) || AP_GAP;
    const count = Math.max(12, Math.floor((wave.clientWidth + gap) / (barWidth + gap)));
    wave.replaceChildren();
    bars = Array.from({ length: count }, (_, i) => {
      const bar = doc.createElement('i');
      const value = peaks[Math.min(AP_BASE - 1, Math.floor((i / count) * AP_BASE))];
      bar.style.height = `${4 + Math.round((value * (Math.max(wave.clientHeight, 16) - 4)) / 4) * 4}px`;
      wave.appendChild(bar);
      return bar;
    });
    paint();
  };

  const toggle = () => { if (audio.paused) audio.play().catch(() => {}); else audio.pause(); };
  const sync = () => {
    const paused = audio.paused;
    play.innerHTML = paused ? AP_PLAY : AP_PAUSE;
    play.setAttribute('aria-label', paused ? 'Воспроизвести' : 'Пауза');
    el.classList.toggle('is-playing', !paused);
  };
  const seek = (event) => {
    if (!audio.duration) return;
    const box = wave.getBoundingClientRect();
    audio.currentTime = Math.max(0, Math.min(1, (event.clientX - box.left) / box.width)) * audio.duration;
    paint();
  };
  play.addEventListener('click', toggle);
  wave.addEventListener('pointerdown', (event) => {
    seek(event);
    wave.setPointerCapture?.(event.pointerId);
    const move = (e) => seek(e);
    const up = () => { wave.removeEventListener('pointermove', move); wave.removeEventListener('pointerup', up); };
    wave.addEventListener('pointermove', move);
    wave.addEventListener('pointerup', up);
  });
  wave.addEventListener('keydown', (event) => {
    const step = { ArrowLeft: -5, ArrowRight: 5, Home: -Infinity, End: Infinity }[event.key];
    if (step === undefined || !audio.duration) return;
    event.preventDefault();
    audio.currentTime = Math.max(0, Math.min(audio.duration, audio.currentTime + step));
    paint();
  });
  const listeners = ['timeupdate', 'durationchange', 'loadedmetadata', 'seeked', 'ended'];
  for (const name of listeners) audio.addEventListener(name, paint);
  for (const name of ['play', 'pause', 'ended']) audio.addEventListener(name, sync);
  // блок удалили (или заменили содержимое), а звук продолжает играть из памяти — останавливаем
  const stray = () => { if (!audio.isConnected && !audio.paused) audio.pause(); };
  audio.addEventListener('timeupdate', stray);
  const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(layout);
  observer?.observe(wave);
  Promise.resolve().then(layout);   // уже после вставки в документ; без requestAnimationFrame, он не срабатывает в фоновых вкладках
  setTimeout(layout, 60);
  if (audio.readyState >= 1) paint();
  const src = audio.getAttribute('src');
  if (src) apReadPeaks(src).then((real) => { if (real && el.isConnected !== false) { peaks = real; bars = []; layout(); } });
  el.addEventListener('ted-audio-destroy', () => {
    observer?.disconnect();
    for (const name of listeners) audio.removeEventListener(name, paint);
    for (const name of ['play', 'pause', 'ended']) audio.removeEventListener(name, sync);
    audio.removeEventListener('timeupdate', stray);
  });
  return el;
}

/** Сайт: заменить родные элементы управления аудио плеером из макета. Для тех, у кого не подключился скрипт, остаётся <audio controls>. */
function enhanceAudio(root = document) {
  for (const figure of root.querySelectorAll('figure.ted-media--audio:not([data-ted-player])')) {
    const audio = figure.querySelector(':scope > audio');
    if (!audio) continue;
    figure.setAttribute('data-ted-player', '');
    audio.removeAttribute('controls');
    figure.insertBefore(buildAudioPlayer(audio, { name: audio.getAttribute('title') || '' }), audio);
  }
}

// ---- resources/js/core/blocks-json.js ----
// Описание документа списком блоков (JSON) → HTML редактора. Для агентов и скриптов: не нужно знать классы ted-*.
// Текст везде простой (экранируется), строчное форматирование — через поле html у абзаца не поддерживается намеренно.
// Результат всё равно проходит Ted.clean / Sanitizer::clean, поэтому ошибка в описании не создаёт небезопасную разметку.


const bjEsc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const bjBg = (b) => (['gray', 'color1', 'color2'].includes(b.bg) ? `ted-bg-${b.bg}` : '');
const bjCls = (...names) => { const list = names.filter(Boolean); return list.length ? ` class="${list.join(' ')}"` : ''; };
const bjLines = (t) => bjEsc(t).replace(/\r?\n/g, '<br>');
const bjUrl = (u) => bjEsc(u);
const bjAlign = (b) => (b.align && ['center', 'right'].includes(b.align) ? `ted-align-${b.align}` : '');

const BJ_RENDER = {
  // любой блок как есть: { "type": "html", "html": "<figure class=\"ted-table\">…" } — дальше обычная очистка (выгрузка в JSON, 22.11)
  html: (b) => String(b.html || ''),
  // кусок Markdown: { "type": "markdown", "text": "## Раздел … - пункт" } — удобно нейросетям (22.11)
  markdown: (b) => markdownToHtml(String(b.text || '')),
};


/** Список блоков → HTML. Неизвестный тип пропускается и попадает в `skipped`, если передан массив. */
function blocksToHtml(list, skipped = []) {
  const out = [];
  for (const b of Array.isArray(list) ? list : []) {
    const def = b ? blockDef(b.type) : null;   // блок из реестра (этап 5): fromJson в blocks/<тип>/<тип>.js
    const fn = def && def.fromJson ? def.fromJson : (b && Object.hasOwn(BJ_RENDER, b.type) ? BJ_RENDER[b.type] : null);
    if (fn) out.push(fn(b)); else skipped.push(b?.type ?? null);
  }
  return out.join('');
}

/** Виды блоков JSON: ядро + блоки реестра с fromJson. */
function blockJsonTypes() { return [...Object.keys(BJ_RENDER), ...registeredBlocks().filter((d) => d.fromJson).map((d) => d.jsonType || d.type)]; }

/**
 * Сохранённый HTML → список блоков JSON (выгрузка, 22.11). Простой текст (абзац, заголовок без оформления) — { type, text },
 * линия — { type: "hr" }, остальное — { type: "html", html } без потерь: Ted.fromBlocks собирает его обратно.
 */
function htmlToBlocks(html, doc = document) {
  const box = doc.createElement('div');
  box.innerHTML = String(html || '');
  const root = box.querySelector(':scope > .ted-content') || box;
  const plain = (el) => !el.attributes.length && [...el.childNodes].every((n) => n.nodeType === 3 || n.nodeName === 'BR');
  const text = (el) => [...el.childNodes].map((n) => (n.nodeName === 'BR' ? '\n' : n.textContent)).join('');
  return [...root.children].map((el) => {
    const t = el.tagName.toLowerCase();
    const d = defOf(el);   // блок без текста и без настроек (линия) — просто вид
    if (d && d.object && d.fromJson && !el.attributes.length && !el.childNodes.length) return { type: d.jsonType || d.type };
    if (/^(p|h[2-6])$/.test(t) && plain(el)) return { type: t, text: text(el) };
    return { type: 'html', html: el.outerHTML };
  });
}

// ---- resources/js/core/markdown.js ----
// Markdown ⇄ блоки texted (решение заказчика 22.11: загрузка и выгрузка .md, вставка Markdown-текста, меню «Нейросети»).
// markdownToHtml — Markdown → HTML блоков; результат всегда проходит обычную очистку (sanitizeHTML / Ted.clean),
// поэтому здесь нет своих белых списков. htmlToMarkdown — сохранённый (чистый) HTML → Markdown.
// Поддерживается: заголовки, абзацы, жирный, курсив, зачёркнутый, код в строке, ссылки, картинки, списки (вложенные),
// чек-листы «- [ ]», цитаты, выноски «> [!NOTE]», блоки кода ```язык, линия ---, таблицы | a | b |.

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// ---------------------------------------------------------------------------
// Markdown → HTML
// ---------------------------------------------------------------------------

/** Строчная разметка: код, картинки, ссылки, жирный, курсив, зачёркнутый. Текст экранируется до разбора. */
function mdInline(text) {
  const codes = [];
  const escs = [];
  // экранированные символы «\*», «\<» — как есть, без разметки
  let s = String(text).replace(/\\([\\`*_[\]<>|#!.+-])/g, (m, c) => { escs.push(c); return `\u0001${escs.length - 1}\u0001`; });
  s = s.replace(/`([^`\n]+)`/g, (m, c) => { codes.push(c); return `\u0000${codes.length - 1}\u0000`; });
  s = esc(s);
  s = s.replace(/!\[([^\]]*)\]\(\s*([^)\s]+)(?:\s+&quot;[^&]*&quot;)?\s*\)/g, (m, alt, url) => `<img src="${url}" alt="${alt}">`);
  s = s.replace(/\[([^\]]+)\]\(\s*([^)\s]+)(?:\s+&quot;[^&]*&quot;)?\s*\)/g, (m, t, url) => `<a href="${url}">${t}</a>`);
  s = s.replace(/&lt;(https?:\/\/[^\s&]+)&gt;/g, (m, url) => `<a href="${url}">${url}</a>`);
  s = s.replace(/(\*\*|__)(?=\S)([\s\S]*?\S)\1/g, '<strong>$2</strong>');
  s = s.replace(/(^|[^\w*])\*(?=\S)([^*\n]*?\S)\*(?!\w)/g, '$1<em>$2</em>');
  s = s.replace(/(^|[^\w_])_(?=\S)([^_\n]*?\S)_(?!\w)/g, '$1<em>$2</em>');
  s = s.replace(/~~(?=\S)([\s\S]*?\S)~~/g, '<s>$1</s>');
  s = s.replace(/ {2,}\n|\\\n/g, '<br>').replace(/\n/g, ' ');
  return s.replace(/\u0000(\d+)\u0000/g, (m, i) => `<code>${esc(codes[+i])}</code>`).replace(/\u0001(\d+)\u0001/g, (m, i) => esc(escs[+i]));
}

const RE = {
  fence: /^\s{0,3}(```|~~~)\s*([\w+#.-]*)\s*$/,
  heading: /^\s{0,3}(#{1,6})\s+(.*?)\s*#*\s*$/,
  rule: /^\s{0,3}([-*_])(\s*\1){2,}\s*$/,   // «---» — блок с block.json → markdown: '---'
  quote: /^\s{0,3}>\s?(.*)$/,
  item: /^(\s*)([-*+]|\d+[.)])\s+(.*)$/,
  table: /^\s*\|.*\|\s*$/,
  tableSep: /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/,
};

/** Список (вложенность — по отступу): строки начиная с first → [html, следующая строка]. */
function mdList(lines, first) {
  const base = lines[first].match(RE.item)[1].length;
  const ordered = /\d/.test(lines[first].match(RE.item)[2]);
  const items = [];
  let i = first;
  while (i < lines.length) {
    const m = lines[i].match(RE.item);
    if (!m || m[1].length < base) {
      if (m || !lines[i].trim() || !/^\s/.test(lines[i]) || !items.length) break;
      items[items.length - 1].text += '\n' + lines[i].trim();   // продолжение пункта
      i++;
      continue;
    }
    if (m[1].length > base) {   // вложенный список — в последний пункт
      const [html, next] = mdList(lines, i);
      if (items.length) items[items.length - 1].nested += html;
      i = next;
      continue;
    }
    if (/\d/.test(m[2]) !== ordered) break;
    const task = m[3].match(/^\[([ xX])\]\s+(.*)$/);
    items.push({ text: task ? task[2] : m[3], checked: task ? task[1] !== ' ' : null, nested: '' });
    i++;
  }
  const checklist = !ordered && items.length && items.every((it) => it.checked !== null);
  const tag = ordered ? 'ol' : 'ul';
  const lis = items.map((it) => `<li${checklist && it.checked ? ' class="ted-checked"' : ''}>${mdInline(it.text)}${it.nested}</li>`).join('');
  return [`<${tag}${checklist ? ' class="ted-checklist"' : ''}>${lis}</${tag}>`, i];
}

/** Таблица GFM: первая строка — шапка, вторая — разделитель. */
function mdTable(lines, first) {
  const cells = (l) => l.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
  const head = cells(lines[first]);
  let i = first + 2;
  const rows = [];
  while (i < lines.length && RE.table.test(lines[i])) rows.push(cells(lines[i++]));
  const th = head.map((c) => `<th>${mdInline(c)}</th>`).join('');
  const body = rows.map((r) => `<tr>${head.map((_, k) => `<td>${mdInline(r[k] || '')}</td>`).join('')}</tr>`).join('');
  return [`<table><thead><tr>${th}</tr></thead><tbody>${body}</tbody></table>`, i];   // очистка делает из неё блок таблицы
}

const CALLOUT = /^\[!(NOTE|TIP|INFO|IMPORTANT|WARNING|CAUTION)\]\s*(.*)$/i;
const CALLOUT_TITLE = { note: 'Заметка', tip: 'Совет', info: 'Информация', important: 'Важно', warning: 'Внимание', caution: 'Осторожно' };

/** Markdown-документ → HTML блоков texted (дальше — обычная очистка). Заголовки: # → h2, ## → h3 … (как сокращения «# »). */
function markdownToHtml(md) {
  const lines = String(md || '').replace(/\r\n?/g, '\n').replace(/\t/g, '    ').split('\n');
  const out = [];
  let para = [];
  const flush = () => { if (para.length) out.push(`<p>${mdInline(para.join('\n'))}</p>`); para = []; };
  for (let i = 0; i < lines.length;) {
    const line = lines[i];
    let m;
    if (!line.trim()) { flush(); i++; continue; }
    if ((m = line.match(RE.fence))) {
      flush();
      const code = [];
      i++;
      while (i < lines.length && !new RegExp(`^\\s{0,3}${m[1]}\\s*$`).test(lines[i])) code.push(lines[i++]);
      i++;
      out.push(`<pre${m[2] ? ` data-lang="${esc(m[2].toLowerCase())}"` : ''}><code>${esc(code.join('\n'))}</code></pre>`);
      continue;
    }
    if ((m = line.match(RE.heading))) {
      flush();
      const level = Math.min(6, m[1].length + 1);
      out.push(`<h${level}>${mdInline(m[2])}</h${level}>`);
      i++;
      continue;
    }
    if (RE.rule.test(line) && !(para.length && /^\s*-+\s*$/.test(line))) { flush(); const d = markdownBlock('---'); if (d && d.fromJson) out.push(d.fromJson({})); i++; continue; }
    if (RE.quote.test(line)) {
      flush();
      const body = [];
      while (i < lines.length && RE.quote.test(lines[i])) body.push(lines[i++].match(RE.quote)[1]);
      const c = body[0].match(CALLOUT);
      if (c) {
        const title = c[2] || CALLOUT_TITLE[c[1].toLowerCase()];
        // блок, который принимает «> [!NOTE]» (block → fromMarkdownAlert); нет такого — обычная цитата
        const alert = registeredBlocks().find((d) => d.fromMarkdownAlert);
        out.push(alert ? alert.fromMarkdownAlert(mdInline(title), markdownToHtml(body.slice(1).join('\n'))) : `<blockquote><p><strong>${mdInline(title)}</strong></p>${markdownToHtml(body.slice(1).join('\n'))}</blockquote>`);
      } else out.push(`<blockquote>${markdownToHtml(body.join('\n'))}</blockquote>`);
      continue;
    }
    if (RE.item.test(line)) { flush(); const [html, next] = mdList(lines, i); out.push(html); i = next; continue; }
    if (RE.table.test(line) && i + 1 < lines.length && RE.tableSep.test(lines[i + 1])) { flush(); const [html, next] = mdTable(lines, i); out.push(html); i = next; continue; }
    para.push(line.replace(/^\s+/, ''));
    i++;
  }
  flush();
  return out.join('\n');
}

/** Похоже ли вставленное (обычный текст) на Markdown-документ: несколько строк и узнаваемая разметка. */
function looksLikeMarkdown(text) {
  const s = String(text || '');
  if (!/\n/.test(s.trim())) return false;
  let score = 0;
  if (/^\s{0,3}#{1,6}\s+\S/m.test(s)) score += 2;
  if (/^\s{0,3}(```|~~~)/m.test(s)) score += 2;
  if (/^\s*([-*+]|\d+[.)])\s+\S/m.test(s)) score += 1;
  if (/^\s*\|.*\|\s*$/m.test(s) && /^\s*\|?\s*:?-{2,}/m.test(s)) score += 2;
  if (/\*\*[^*\n]+\*\*|\[[^\]\n]+\]\([^)\s]+\)/.test(s)) score += 1;
  if (/^\s{0,3}>\s/m.test(s)) score += 1;
  return score >= 2;
}

// ---------------------------------------------------------------------------
// HTML (сохранённый, чистый) → Markdown
// ---------------------------------------------------------------------------

// < и > тоже: чужой просмотрщик Markdown не примет текст за HTML
const mdEsc = (s) => s.replace(/([\\`*_[\]<>])/g, '\\$1');

/** Строчные элементы → Markdown. */
function inlineMd(node) {
  let s = '';
  for (const c of node.childNodes) {
    if (c.nodeType === 3) { s += mdEsc(c.data.replace(/\s+/g, ' ')); continue; }
    if (c.nodeType !== 1) continue;
    const t = c.tagName;
    const inner = () => inlineMd(c);
    if (t === 'BR') s += '  \n';
    else if (t === 'STRONG' || t === 'B') s += `**${inner()}**`;
    else if (t === 'EM' || t === 'I') s += `*${inner()}*`;
    else if (t === 'S' || t === 'DEL') s += `~~${inner()}~~`;
    else if (t === 'CODE') s += `\`${c.textContent}\``;
    else if (t === 'A') s += `[${inner()}](${c.getAttribute('href') || ''})`;
    else if (t === 'IMG') s += `![${c.getAttribute('alt') || ''}](${c.getAttribute('src') || ''})`;
    else s += inner();
  }
  return s;
}

function listMd(list, depth) {
  const ordered = list.tagName === 'OL';
  const check = list.classList.contains('ted-checklist');
  const pad = '  '.repeat(depth);
  return [...list.children].map((li, k) => {
    const nested = [...li.children].filter((x) => x.tagName === 'UL' || x.tagName === 'OL');
    const clone = li.cloneNode(true);
    for (const n of clone.querySelectorAll(':scope > ul, :scope > ol')) n.remove();
    const mark = ordered ? `${k + 1}.` : '-';
    const box = check ? (li.classList.contains('ted-checked') ? '[x] ' : '[ ] ') : '';
    return `${pad}${mark} ${box}${inlineMd(clone).trim()}` + nested.map((n) => '\n' + listMd(n, depth + 1)).join('');
  }).join('\n');
}

function tableMd(table) {
  const rows = [...table.querySelectorAll('tr')].map((tr) => [...tr.children].map((c) => inlineMd(c).replace(/\|/g, '\\|').trim()));
  if (!rows.length) return '';
  const n = Math.max(...rows.map((r) => r.length));
  const line = (r) => `| ${Array.from({ length: n }, (_, k) => r[k] || '').join(' | ')} |`;
  return [line(rows[0]), `|${' --- |'.repeat(n)}`, ...rows.slice(1).map(line)].join('\n');
}

/** Один блок → Markdown: блок со своим видом (block → toMarkdown) — сам; текстовые — здесь; остальное — ссылкой или текстом. */
function blockMd(el) {
  const def = defOf(el);
  if (def && def.toMarkdown) return def.toMarkdown(el, MD_API);
  const t = el.tagName;
  const cls = el.classList;
  if (/^H[2-6]$/.test(t)) return `${'#'.repeat(+t[1] - 1)} ${inlineMd(el).trim()}`;
  if (t === 'P') return inlineMd(el).trim();
  if (t === 'PRE') return '```' + (el.getAttribute('data-lang') || '') + '\n' + el.textContent.replace(/\n$/, '') + '\n```';
  if (t === 'BLOCKQUOTE') return [...el.children].map((p) => (p.classList.contains('ted-author') ? '> — ' : '> ') + inlineMd(p).replace(/ {2}\n/g, ', ').trim()).join('\n>\n');
  if (t === 'OL' && cls.contains('ted-steps')) return [...el.children].map((li, k) => `${k + 1}. ${inlineMd(li).replace(/ {2}\n/, ' — ').trim()}`).join('\n');
  if (t === 'UL' && cls.contains('ted-facts')) return [...el.children].map((li) => `- ${inlineMd(li).replace(/ {2}\n/, ' — ').trim()}`).join('\n');
  if (t === 'UL' && cls.contains('ted-proscons')) return [...el.children].map((card) => { const title = card.querySelector(':scope > strong'); const ul = card.querySelector(':scope > ul'); return `**${title ? title.textContent.trim() : ''}**\n\n${ul ? listMd(ul, 0) : ''}`; }).join('\n\n');
  if (t === 'UL' || t === 'OL') return listMd(el, 0);
  const link = el.querySelector('a[href]');
  if (link) return `[${el.textContent.replace(/\s+/g, ' ').trim()}](${link.getAttribute('href')})`;
  return el.textContent.replace(/\s+/g, ' ').trim();
}

const MD_API = { inline: (el) => inlineMd(el), blocks: (el) => blocksMd(el), list: (el) => listMd(el, 0), table: (el) => tableMd(el) };

function blocksMd(root) {
  return [...root.children].map(blockMd).filter(Boolean).join('\n\n');
}

/** Сохранённый HTML texted → Markdown-документ. */
function htmlToMarkdown(html, doc = document) {
  const box = doc.createElement('div');
  box.innerHTML = String(html || '');
  const root = box.querySelector(':scope > .ted-content') || box;
  return blocksMd(root).replace(/\n{3,}/g, '\n\n').trim() + '\n';
}

// ---- resources/js/core/presence.js ----
// Один документ в двух вкладках браузера (решение заказчика 22.11): вкладки узнают друг о друге через BroadcastChannel.
// Открыли вторую — обе предупреждают; в другой вкладке сохранили — сохранение здесь сначала спрашивает подтверждение,
// чтобы не перезаписать чужие правки молча. Без BroadcastChannel (старый браузер) — ничего не делает.

// своя страница: редакторы на одной странице (и тесты) друг для друга не «другая вкладка»
const PAGE_ID = Math.random().toString(36).slice(2);

class Presence {
  /** key — документ (то же, что ключ черновика), onEvent(type) — 'other' (есть другая вкладка), 'saved' (там сохранили). */
  constructor(key, onEvent) {
    this.id = Math.random().toString(36).slice(2);
    this.others = new Set();
    this.otherSaved = false;
    this.onEvent = onEvent;
    if (!key || typeof BroadcastChannel === 'undefined') return;
    this.channel = new BroadcastChannel(`ted-doc:${key}`);
    this.channel.onmessage = (e) => this.receive(e.data || {});
    this.send('hello');
  }

  send(type) {
    if (this.channel) this.channel.postMessage({ type, from: this.id, page: PAGE_ID });
  }

  receive({ type, from, page }) {
    if (!from || from === this.id || page === PAGE_ID) return;
    if (type === 'hello') this.send('here');
    if (type === 'hello' || type === 'here') {
      const first = !this.others.size;
      this.others.add(from);
      if (first) this.onEvent('other');
    }
    if (type === 'bye') this.others.delete(from);
    if (type === 'saved') { this.otherSaved = true; this.onEvent('saved'); }
  }

  /** Здесь сохранили: другим вкладкам — сигнал, у себя — чужое сохранение уже учтено. */
  saved() {
    this.otherSaved = false;
    this.send('saved');
  }

  destroy() {
    this.send('bye');
    if (this.channel) this.channel.close();
    this.channel = null;
  }
}

// ---- resources/js/core/blocks.js ----
// Операции с блоками верхнего уровня: тип блока, превращение одного типа
// в другой, выравнивание, нормализация DOM редактора.






// H5 и H6 добавлены по решению заказчика (в макете списка их нет); горячие клавиши Mod+Shift+5 / 6, Markdown «#### » / «##### ».
const BLOCK_TYPES = [
];

// Меню блоков по «/» (макет editor-menu): 25 блоков по группам библиотеки.
// soon — номер этапа плана, на котором блок появится.
const SLASH_GROUPS = [
  { title: 'Текст', items: [
  ] },
  { title: 'Акцент', items: [
  ] },
  { title: 'Списки', items: [
  ] },
  { title: 'Медиа', items: [
  ] },
  { title: 'Файлы и таблицы', items: [
  ] },
  { title: 'Встраивание', items: [
  ] },
  { title: 'Макет', items: [
  ] },
  { title: 'Интерактив', items: [
  ] },
  { title: 'Действия', items: [
  ] },
];

// Подсказки пустых блоков (макет: block-heading / block-body state=empty)
const PLACEHOLDERS = {
  li: 'Пункт списка',
  pre: 'Код',
};

/**
 * Меню «/» и «Все блоки»: блоки ядра (SLASH_GROUPS) + блоки из реестра (block.json → menu: группа, место after).
 * Пока блоки переносятся по одному (этап 5), ядро ещё держит свой список; перенесённые приходят из реестра.
 */
function menuGroups() {
  const groups = SLASH_GROUPS.map((g) => ({ ...g, items: g.items.map((it, i) => ({ ...it, order: it.order ?? i * 10 })) }));
  for (const d of registeredBlocks()) {
    if (!d.menu) continue;
    let g = groups.find((x) => x.title === d.menu.group);
    if (!g) { g = { title: d.menu.group, items: [] }; groups.push(g); }
    g.items.push({ type: d.type, label: d.menu.label || d.title, icon: d.menu.icon, words: d.menu.words, convert: d.menu.convert, sample: d.menu.sample, picker: d.menu.picker, order: d.menu.order ?? 1000 });
  }
  for (const g of groups) g.items.sort((a, b) => a.order - b.order);
  return groups;
}

/** Список «Стиль текста»: блоки ядра (BLOCK_TYPES) + текстовые блоки реестра (block.json → style), по номеру order. */
function styleTypes() {
  const list = [...BLOCK_TYPES];
  for (const d of registeredBlocks()) if (d.style) list.push({ type: d.type, label: d.style.label, icon: d.style.icon, keys: d.style.keys || '', order: d.style.order });
  return list.sort((a, b) => a.order - b.order);
}

/** Подсказка пустого блока: block.json → placeholder или список ядра. */
function placeholderOf(type) {
  const d = blockDef(type);
  return t((d && d.placeholder) || PLACEHOLDERS[type] || '');   // на языке редактора (i18n)
}

/** «Превратить в…» есть у блока, если в списке блоков у него нет convert: false (меню общее, наполнение — из списка). */
function blockCanConvert(el) {
  if (!el || blockType(el) === 'raw') return false;
  const kind = kindOf(el);
  for (const g of menuGroups()) for (const it of g.items) if (it.type === kind) return it.convert !== false;
  return true;
}

function blockType(el) {
  if (!el || el.nodeType !== 1) return null;
  if (el.classList.contains('ted-ui-raw') || isWrap(el)) return 'raw';   // HTML-блок и обёртка правки (медиа)
  return el.tagName.toLowerCase();
}

/** Вид блока: как blockType, но чек-лист (<ul class="ted-checklist">) и шаги (<ol class="ted-steps">) отличаются от обычных списков. */
function kindOf(el) {
  const def = defOf(el);   // блок из реестра (этап 5)
  if (def) return def.type;
  const t = blockType(el);
  return t;
}

// ---------------------------------------------------------------------------
// Отключаемые блоки: опция blocks — 'all' (по умолчанию), имя набора ('mini', 'text', свой — core/presets.js),
// прежний 'basic' или массив типов
// ---------------------------------------------------------------------------

/** Прежний набор опции blocks (до этапа 2), оставлен для совместимости. Наборы этапа 2 — PRESETS в core/presets.js. */
const BLOCK_PRESETS = {
  basic: ['p', 'h2', 'h3', 'h4', 'h5', 'h6', 'ul', 'ol', 'blockquote', 'pre', 'hr', 'checklist', 'steps'],
};

/** Опция blocks → Set разрешённых типов или null («всё разрешено»). Абзац разрешён всегда. serverPresets — свои наборы с сервера. */
function resolveBlocks(option, serverPresets = null) {
  if (!option || option === 'all') return null;
  let list = null;
  if (typeof option === 'string') {
    const preset = presetOf(option, serverPresets);
    list = preset ? (preset.blocks === 'all' ? null : preset.blocks) : (BLOCK_PRESETS[option] || null);
  } else if (Array.isArray(option)) list = option;
  if (!list) return null;
  const set = new Set(list.map((t) => presetAlias(t)));
  set.add('p');
  return set;
}

function blockAllowed(set, type) { return !set || set.has(type); }

/** Меню «/» и «Все блоки»: только разрешённые блоки, пустые группы убираются. */
function filterGroups(groups, set) {
  if (!set) return groups;
  return groups.map((g) => ({ ...g, items: g.items.filter((it) => set.has(it.type)) })).filter((g) => g.items.length);
}

function restrictKind(el) {
  if (isWrap(el)) { const d = defOf(el.firstElementChild); return d ? d.type : 'raw'; }   // обёртка правки: вид — у блока внутри
  if (el.classList.contains('ted-ui-raw')) return 'raw';
  return kindOf(el) || el.tagName.toLowerCase();
}

function textNodesOf(el, doc, tag = 'p') {
  const p = doc.createElement(tag);
  p.innerHTML = el.innerHTML;
  return p;
}

/** Блок запрещённого вида → обычный текст (абзацы / списки), чтобы содержимое не терялось. */
function degradeBlock(el, kind, doc) {
  const def = blockDef(kind);   // блок из реестра: как превращать в текст — в block.json (degrade), то же читает сервер
  if (def && def.degrade === 'drop') return [];
  // children: вложенные блоки (абзацы) с текстом переносятся как есть и сами проверяются по набору — так же на сервере
  if (def && def.degrade === 'children') return Array.from(el.children).filter((c) => c.textContent.trim()).map((c) => c.cloneNode(true));
  const p = (html) => { const n = doc.createElement('p'); n.innerHTML = html; return n; };
  const list = (tag, items) => { const n = doc.createElement(tag); for (const html of items) { const li = doc.createElement('li'); li.innerHTML = html; n.appendChild(li); } return n; };
  const text = (n) => (n ? n.textContent.replace(/\u200b/g, '').trim() : '');
  const esc = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  if (def && def.toText) return def.toText(el, { doc, p, list, text, esc });   // блок из реестра сам превращается в текст
  switch (kind) {
    case 'checklist': return [list('ul', Array.from(el.children).map((li) => li.innerHTML))];
    case 'steps': return [list('ol', Array.from(el.children).map((li) => {
      const t = text(li.firstElementChild);
      const d = text({ textContent: Array.from(li.childNodes).slice(2).map((n) => n.textContent).join('') });
      return esc(t) + (d ? ' — ' + esc(d) : '');
    }))];
    // вложенные блоки (абзац, заголовок, список) переносятся как есть и сами проверяются по набору (restrictBlocks → walk)
    case 'facts': return Array.from(el.children).map((li) => {
      const t = text(li.firstElementChild);
      const d = text({ textContent: Array.from(li.childNodes).slice(2).map((n) => n.textContent).join('') });
      return p(esc(t) + (d ? ' — ' + esc(d) : ''));
    }).filter((n) => n.textContent.trim());
    case 'proscons': return Array.from(el.children).flatMap((card) => {
      const out = [];
      const t = text(card.firstElementChild);
      if (t) out.push(p('<strong>' + esc(t) + '</strong>'));
      const ul = card.querySelector(':scope > ul');
      if (ul) out.push(list('ul', Array.from(ul.children).map((li) => li.innerHTML).filter((h) => h.replace(/<br>/g, '').trim())));
      return out;
    });
    case 'blockquote': return Array.from(el.children).filter((c) => c.tagName === 'P' && !c.classList.contains('ted-author')).map((c) => textNodesOf(c, doc));
    case 'pre': return [p(esc(el.textContent).replace(/\n/g, '<br>'))];
    case 'ul': case 'ol': return Array.from(el.children).map((li) => textNodesOf(li, doc));
    case 'raw': return [];
    default:
      if (/^h[2-6]$/.test(kind)) return [textNodesOf(el, doc)];
      return [textNodesOf(el, doc)];
  }
}

/**
 * Привести блоки корня (элемента или фрагмента) к набору разрешённых: запрещённые превращаются в обычный текст,
 * цветной фон снимается, если он не разрешён. Вызывается при загрузке, вставке и сохранении — запрещённое не пролезает ни одним путём.
 */
function restrictBlocks(root, set, doc = document) {
  if (!set) return root;
  const stripBg = (el) => {
    if (set.has('background') || !el.classList) return;
    for (const n of BG_NAMES) el.classList.remove(`ted-bg-${n}`);
    if (!el.className) el.removeAttribute('class');
  };
  const walk = (el, depth) => {
    const kind = restrictKind(el);
    if (set.has(kind)) { stripBg(el); return [el]; }
    if (depth > 4) { const p = doc.createElement('p'); p.textContent = el.textContent; return p.textContent.trim() ? [p] : []; }
    return degradeBlock(el, kind, doc).flatMap((n) => (n.nodeType === 1 ? walk(n, depth + 1) : [n]));
  };
  for (const el of Array.from(root.children)) {
    const replacement = walk(el, 0);
    if (replacement.length === 1 && replacement[0] === el) continue;
    el.replaceWith(...replacement);
  }
  // вложенные блоки (решение 22.11): запрещённый блок внутри разрешённого (абзаца, пункта, ответа аккордеона) тоже превращается в текст,
  // а «сырые» фрейм, видео, таблица, картинка живут только внутри своего блока — то же на сервере (Presets::restrict)
  const check = (c, depth) => {
    const def = defOf(c);
    if (def) {
      if (NESTED_FREE.has(def.type) || set.has(def.type)) { stripBg(c); inner(c, depth); return; }
      const out = depth > 8 ? [] : degradeBlock(c, def.type, doc);
      if (NESTED_INLINE.test(c.parentElement ? c.parentElement.tagName : '')) {
        const t = out.map((n) => n.textContent.trim()).filter(Boolean).join(' ');
        c.replaceWith(...(t ? [doc.createTextNode(t)] : []));
        return;
      }
      c.replaceWith(...out);
      for (const n of out) if (n.nodeType === 1) check(n, depth + 1);
      return;
    }
    if (!ownedNested(c)) { const kids = Array.from(c.childNodes); c.replaceWith(...kids); for (const k of kids) if (k.nodeType === 1) check(k, depth + 1); return; }
    stripBg(c);
    inner(c, depth);
  };
  const inner = (el, depth) => { for (const c of Array.from(el.children)) check(c, depth + 1); };
  for (const el of Array.from(root.children)) inner(el, 0);
  return root;
}

// Вложенные проверки набора: списки — обычный текст (внутри плюсов-минусов, содержания, пунктов).
// Внутри текстового блока, выноски и контейнера — только оформление текста и своя разметка блока (теги из block.json → html и образца
// меню); чужой «сырой» тег (фрейм, видео, таблица, картинка) разворачивается в свой текст. Блок с собственной разметкой (медиа, таблица…) — как есть.
const NESTED_FREE = new Set(['p', 'ul', 'ol']);
const NESTED_INLINE = /^(P|H[1-6]|SUMMARY|A|STRONG|B|EM|I|U|S|SPAN|CODE|SUB|SUP|MARK|SMALL)$/;
const PHRASING = new Set(['a', 'strong', 'b', 'em', 'i', 'u', 's', 'code', 'sub', 'sup', 'mark', 'small', 'span', 'br', 'wbr', 'abbr', 'q']);
const OWN_TAGS = new Map();
function ownTags(def) {
  if (OWN_TAGS.has(def.type)) return OWN_TAGS.get(def.type);
  const tags = new Set(Object.keys(def.html || {}));
  const sample = def.menu && def.menu.sample;
  if (sample && typeof document !== 'undefined') {
    const t = document.createElement('template');
    t.innerHTML = sample;
    for (const e of t.content.querySelectorAll('*')) tags.add(e.tagName.toLowerCase());
  }
  OWN_TAGS.set(def.type, tags);
  return tags;
}
/** Элемент без своего вида на своём месте: у блока с собственной разметкой — любой; у текстового, выноски, контейнера — оформление текста и своя разметка. */
function ownedNested(c) {
  const tag = c.tagName.toLowerCase();
  for (let a = c.parentElement; a; a = a.parentElement) {
    const d = defOf(a);
    if (!d) continue;
    if (!d.text && d.degrade !== 'children' && !d.container) return true;
    return PHRASING.has(tag) || ownTags(d).has(tag);
  }
  return PHRASING.has(tag);
}

// ---------------------------------------------------------------------------
// Маркеры курсора: переживают перенос узлов между блоками
// ---------------------------------------------------------------------------

function insertMarkers(root) {
  const range = getRange(root);
  if (!range) return null;
  const doc = root.ownerDocument;
  const end = doc.createElement('span');
  end.setAttribute('data-tedui-m', 'e');
  const start = doc.createElement('span');
  start.setAttribute('data-tedui-m', 's');
  const r2 = range.cloneRange();
  r2.collapse(false);
  r2.insertNode(end);
  const r1 = range.cloneRange();
  r1.collapse(true);
  r1.insertNode(start);
  return { start, end };
}

function restoreMarkers(root, markers) {
  if (!markers) return;
  const doc = root.ownerDocument;
  const range = doc.createRange();
  const point = (m) => {
    if (!m.isConnected || !root.contains(m)) return null;
    const parent = m.parentNode;
    const index = Array.prototype.indexOf.call(parent.childNodes, m);
    parent.removeChild(m);
    return { parent, index };
  };
  const s = point(markers.start);
  const e = point(markers.end);
  root.querySelectorAll('[data-tedui-m]').forEach((m) => m.remove());
  if (!s) return;
  try {
    range.setStart(s.parent, Math.min(s.index, s.parent.childNodes.length));
    if (e && !(e.parent === s.parent && e.index < s.index)) range.setEnd(e.parent, Math.min(e.index, e.parent.childNodes.length));
    else range.collapse(true);
  } catch (err) {
    return;
  }
  const sel = doc.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
}

function withMarkers(root, fn) {
  const markers = insertMarkers(root);
  try {
    fn();
  } finally {
    restoreMarkers(root, markers);
  }
}

// ---------------------------------------------------------------------------
// Превращение блоков
// ---------------------------------------------------------------------------

// Блок → «строки» (массивы узлов) для пересборки в новый тип
function toLines(block) {
  const doc = block.ownerDocument;
  const type = blockType(block);
  const lines = [];

  const fromInline = (el) => {
    const nodes = [];
    for (const c of Array.from(el.childNodes)) {
      if (c.nodeType === 1 && (c.tagName === 'UL' || c.tagName === 'OL')) continue;
      nodes.push(c);
    }
    return nodes;
  };

  if (type === 'ul' || type === 'ol') {
    const walk = (list) => {
      for (const li of Array.from(list.children)) {
        lines.push(fromInline(li));
        for (const nested of li.querySelectorAll(':scope > ul, :scope > ol')) walk(nested);
      }
    };
    walk(block);
  } else if (type === 'blockquote') {
    for (const c of Array.from(block.childNodes)) {
      if (c.nodeType === 1 && c.tagName === 'P') lines.push(fromInline(c));
      else if (c.textContent.trim() || c.nodeName === 'SPAN') lines.push([c]);
    }
  } else if (type === 'pre') {
    const marker = block.querySelector('[data-tedui-m]');
    const text = block.textContent;
    text.split('\n').forEach((line, i) => {
      const nodes = [doc.createTextNode(line)];
      if (i === 0 && marker) nodes.unshift(marker);
      lines.push(nodes);
    });
  } else {
    lines.push(fromInline(block));
  }
  return lines.length ? lines : [[]];
}

function fill(el, nodes) {
  for (const n of nodes) el.appendChild(n);
  if (!el.textContent && !el.querySelector('br')) el.appendChild(el.ownerDocument.createElement('br'));
  return el;
}

function alignOf(block) {
  return Array.from(block.classList).filter((c) => /^ted-(align|bg)-/.test(c));
}

/**
 * Превратить блоки в тип type (p, h2…h6, ul, ol, blockquote, pre).
 * Повторное применение списка/цитаты к таким же блокам — снимает их.
 */
function convertBlocks(root, blocks, type) {
  blocks = blocks.filter((b) => {
    const t = blockType(b);
    return t && t !== 'raw' && !isObjectBlock(b);
  });
  if (!blocks.length) return;
  const doc = root.ownerDocument;

  const allSame = blocks.every((b) => kindOf(b) === type);
  // повторное применение списка / цитаты / чек-листа к тем же блокам снимает их (превращает в абзацы)
  if (allSame && (type === 'ul' || type === 'ol' || type === 'blockquote' || type === 'checklist' || type === 'steps')) type = 'p';
  else if (allSame && /^(p|h[2-6]|pre)$/.test(type)) return;

  withMarkers(root, () => {
    const align = alignOf(blocks[0]);
    const lines = [];
    for (const b of blocks) lines.push(...toLines(b));
    const created = [];

    if (type === 'ul' || type === 'ol' || type === 'checklist') {
      const list = doc.createElement(type === 'checklist' ? 'ul' : type);
      if (type === 'checklist') list.classList.add('ted-checklist');
      for (const line of lines) list.appendChild(fill(doc.createElement('li'), line));
      created.push(list);
    } else if (type === 'steps') {
      // каждая строка — шаг: заголовок жирным (описание добавляется Shift+Enter)
      // пустой абзац → блок как в макете state=empty: четыре шага с заглушками
      if (lines.every((l) => !l.some((n) => (n.textContent || '').trim()))) {
        created.push(emptyStepsBlock(doc));
      } else {
      const ol = doc.createElement('ol');
      ol.classList.add('ted-steps');
      for (const line of lines) {
        const li = doc.createElement('li');
        const title = doc.createElement('strong');
        for (const n of line) title.appendChild(n);
        if (!title.textContent && !title.querySelector('br')) title.appendChild(doc.createElement('br'));
        li.appendChild(title);
        ol.appendChild(li);
      }
      created.push(ol);
      }
    } else if (type === 'blockquote') {
      const bq = doc.createElement('blockquote');
      for (const line of lines) bq.appendChild(fill(doc.createElement('p'), line));
      created.push(bq);
    } else if (type === 'pre') {
      const pre = doc.createElement('pre');
      lines.forEach((line, i) => {
        if (i) pre.appendChild(doc.createTextNode('\n'));
        for (const n of line) {
          if (n.nodeType === 1 && n.hasAttribute('data-tedui-m')) pre.appendChild(n);
          else if (n.nodeName === 'BR') pre.appendChild(doc.createTextNode('\n'));
          else pre.appendChild(doc.createTextNode(n.textContent));
          // маркеры внутри строчных элементов не теряем
          if (n.nodeType === 1 && !n.hasAttribute('data-tedui-m')) n.querySelectorAll('[data-tedui-m]').forEach((m) => pre.appendChild(m));
        }
      });
      // блок кода: <pre><code data-nums> — шапка с языком и номера строк по умолчанию
      const code = doc.createElement('code');
      while (pre.firstChild) code.appendChild(pre.firstChild);
      if (!code.textContent.replace(/\n/g, '')) Array.from(code.childNodes).forEach((n) => { if (n.nodeType === 3) n.remove(); });   // пустой абзац: <br> не должен стать переносом строки
      if (!code.textContent) code.appendChild(doc.createElement('br'));
      pre.setAttribute('data-nums', '1');
      pre.appendChild(code);
      created.push(pre);
    } else {
      for (const line of lines) created.push(fill(doc.createElement(type), line));
    }

    if (align && align.length && type !== 'pre') for (const el of created) el.classList.add(...align);

    const anchor = blocks[0];
    for (const el of created) anchor.parentNode.insertBefore(el, anchor);   // и в теле контейнера (ответ аккордеона)
    for (const b of blocks) b.remove();
  });
}

function setAlign(blocks, align) {
  for (const b of blocks) {
    const t = blockType(b);
    if (!t || t === 'raw' || t === 'pre' || isObjectBlock(b)) continue;
    if (!alignAllowed(b)) continue;
    b.classList.remove('ted-align-center', 'ted-align-right');
    if (align === 'center' || align === 'right') b.classList.add(`ted-align-${align}`);
    if (!b.className) b.removeAttribute('class');
  }
}

// У чек-листа и шагов выравнивания нет (чек-бокс и номер всегда слева): класс не сохраняется, команда и кнопка недоступны
const NO_ALIGN_KINDS = new Set(['checklist', 'steps']);
function alignAllowed(b) {
  const ad = b && b.nodeType === 1 ? defOf(b) : null;
  if (ad && ad.canAlign && !ad.canAlign(b)) return false;   // блок из реестра решает сам (баннер кнопки — на всю ширину)
  return !(b && NO_ALIGN_KINDS.has(kindOf(b)));
}

function alignOfBlock(b) {
  if (!b || !b.classList) return 'left';
  if (b.classList.contains('ted-align-center')) return 'center';
  if (b.classList.contains('ted-align-right')) return 'right';
  return 'left';
}

// Цветной фон (подложка): палитры сайта gray / color1 / color2 → класс ted-bg-<имя>
const BG_NAMES = ['gray', 'color1', 'color2'];

// Блоки со своим видом (чек-лист, шаги, плюсы и минусы): цветной фон запрещён; выноска и цифры красятся целиком
const NO_BG_KINDS = new Set(['checklist', 'steps', 'proscons']);
function bgAllowed(b) {
  const bd = b && b.nodeType === 1 ? defOf(b) : null;
  if (bd && bd.toolbar && bd.toolbar.bg === false) return false;   // block.json → toolbar.bg
  if (bd && bd.canBg && !bd.canBg(b)) return false;   // блок из реестра решает сам
  return !(b && NO_BG_KINDS.has(kindOf(b)));
}

function setBg(blocks, name) {
  for (const b of blocks) {
    const t = blockType(b);
    if (!t || t === 'raw' || t === 'pre' || isObjectBlock(b)) continue;
    if (!bgAllowed(b)) continue;
    for (const n of BG_NAMES) b.classList.remove(`ted-bg-${n}`);
    if (BG_NAMES.includes(name)) b.classList.add(`ted-bg-${name}`);
    if (!b.className) b.removeAttribute('class');
  }
}

function bgOfBlock(b) {
  if (!b || !b.classList) return '';
  return BG_NAMES.find((n) => b.classList.contains(`ted-bg-${n}`)) || '';
}

// ---------------------------------------------------------------------------
// Нормализация DOM редактора после ввода
// ---------------------------------------------------------------------------

const INLINE_ROOT = /^(#text|B|STRONG|I|EM|U|S|STRIKE|DEL|CODE|A|SPAN|FONT|SUB|SUP|BR|MARK|SMALL|BIG)$/;

function normalizeRoot(root) {
  const doc = root.ownerDocument;
  let changed = false;
  let para = null;

  for (const node of Array.from(root.childNodes)) {
    const name = node.nodeName.toUpperCase();

    if (node.nodeType === 3 && !node.data.trim() && !para) {
      node.remove();
      continue;
    }
    if (node.nodeType === 8) {
      node.remove();
      continue;
    }
    if (node.nodeType === 3 || INLINE_ROOT.test(name)) {
      // строчное содержимое прямо в корне → в абзац
      if (name === 'BR' && !para) {
        node.remove();
        changed = true;
        continue;
      }
      if (!para) {
        para = doc.createElement('p');
        root.insertBefore(para, node);
      }
      para.appendChild(node);
      changed = true;
      continue;
    }
    para = null;

    if (node.nodeType !== 1) continue;
    if (node.matches('.ted-ui-raw') || isWrap(node)) continue;
    // блок из реестра приводит свою форму правки к порядку сам (blocks/<тип>/<тип>.js → normalize)
    const nd = defOf(node);
    if (nd && nd.normalize) {
      if (nd.normalize(node, doc)) changed = true;
      continue;
    }

    if (name === 'DIV' || name === 'H1') {
      // Chrome иногда создаёт <div> вместо <p>
      const el = doc.createElement(name === 'H1' ? 'h2' : 'p');
      while (node.firstChild) el.appendChild(node.firstChild);
      if (node.className) el.className = node.className;
      node.replaceWith(el);
      changed = true;
      continue;
    }
    if (!isBlockTag(name)) {
      node.replaceWith(makeRaw(node, doc));
      changed = true;
    }
  }

  // мусор, который оставляет браузер при склейке блоков
  // код с токенами подсветки — сразу в чистый текст одним присваиванием: снимать тысячи span по одному — тысячи перестроек
  // текста (код на 2000 строк грузился 20 с в Safari). С маркерами курсора — ниже, по одному (их мало: идёт правка)
  for (const code of root.querySelectorAll('pre > code')) {
    if (!code.children.length || code.closest('.ted-ui-raw') || code.querySelector('[data-tedui-m]') || code.querySelector(':scope > br')) continue;
    code.textContent = code.textContent;
    changed = true;
  }
  for (const el of Array.from(root.querySelectorAll('span, font'))) {
    if (el.closest('.ted-ui-raw, [contenteditable="false"]') || el.hasAttribute('data-tedui-m')) continue;   // нередактируемый снимок (карточка) со своими span
    el.replaceWith(...el.childNodes);
    changed = true;
  }
  for (const el of Array.from(root.querySelectorAll('[style]'))) {
    if (el.closest(`.ted-ui-raw, ${wrapSelector()}`)) continue;
    el.removeAttribute('style');
    changed = true;
  }

  // пустые блоки должны содержать <br>, чтобы в них можно было поставить курсор
  for (const el of root.querySelectorAll(':scope > p, :scope > h2, :scope > h3, :scope > h4, :scope > h5, :scope > h6, :scope > pre, li, blockquote > p')) {
    if (!el.firstChild) {
      el.appendChild(doc.createElement('br'));
      changed = true;
    }
  }

  // пустой список/цитата → абзац
  for (const el of root.querySelectorAll(':scope > ul, :scope > ol, :scope > blockquote')) {
    if (!el.children.length) {
      const p = doc.createElement('p');
      p.appendChild(doc.createElement('br'));
      el.replaceWith(p);
      changed = true;
    }
  }

  // всегда есть куда поставить курсор
  const last = root.lastElementChild;
  if (!last || /^(HR|PRE)$/.test(last.tagName) || last.classList.contains('ted-ui-raw') || !!(defOf(last) && (defOf(last).caretBelow || defOf(last).lineAfter)) || (last.parentNode === root && !root.classList.contains('ted-ui-host') && isContainer(last))) {
    const p = doc.createElement('p');
    p.appendChild(doc.createElement('br'));
    root.appendChild(p);
    changed = true;
  }
  // пустой пункт чек-листа не бывает отмеченным (при Enter браузер копирует класс предыдущего пункта)
  for (const li of root.querySelectorAll('ul.ted-checklist > li.ted-checked')) {
    if (!li.textContent.replace(/[​\s]/g, '')) li.classList.remove('ted-checked');
  }
  // у блоков со своим видом цветного фона нет (остаётся от превращения или вставки)
  for (const el of root.querySelectorAll(':scope > [class*="ted-bg-"]')) {
    if (bgAllowed(el)) continue;
    for (const n of BG_NAMES) el.classList.remove(`ted-bg-${n}`);
    if (!el.className) el.removeAttribute('class');
    changed = true;
  }
  // у чек-листа и шагов выравнивания нет (остаётся от превращения или вставки)
  for (const el of root.querySelectorAll(':scope > [class*="ted-align-"]')) {
    if (alignAllowed(el)) continue;
    el.classList.remove('ted-align-center', 'ted-align-right');
    if (!el.className) el.removeAttribute('class');
    changed = true;
  }
  // шаги: у каждого пункта заголовок, <br> и описание (в описании — нулевой пробел, если оно пустое)
  for (const li of root.querySelectorAll('ol.ted-steps > li, ul.ted-facts > li')) {
    if (li.closest('.ted-ui-raw')) continue;
    if (fixStepItem(li, doc)) changed = true;
    // нулевой пробел лишний, когда в описании есть текст
    const sep = li.firstElementChild && li.firstElementChild.nextSibling;
    const d = sep && sep.nextSibling;
    if (d && d.nodeType === 3 && d.data.length > 1 && d.data.startsWith(ZWSP)) {
      const sel = document.getSelection();
      const keep = sel && sel.rangeCount && sel.anchorNode === d ? sel.anchorOffset - 1 : null;
      d.data = d.data.slice(1);
      if (keep !== null && keep >= 0) sel.collapse(d, keep);
      changed = true;
    }
  }
  // плюсы и минусы: починка структуры (после вложенного списка, вынесенного пункта, разбитой карточки):
  // карточка без класса сливается с предыдущей; вложенные списки в пунктах раскрываются в обычные пункты
  for (const pc of root.querySelectorAll(':scope > ul.ted-proscons')) {
    for (const card of [...pc.children]) {
      if (card.tagName !== 'LI') { card.remove(); changed = true; continue; }
      if (!card.classList.contains('ted-pros') && !card.classList.contains('ted-cons')) {
        const prev = card.previousElementSibling;
        if (prev) {
          let target = prev.querySelector(':scope > ul');
          if (!target) { target = doc.createElement('ul'); prev.appendChild(target); }
          for (const item of [...card.querySelectorAll('li')]) {
            if (item.querySelector('li')) continue;
            if (item.textContent.replace(/\u200b/g, '').trim()) target.appendChild(item);
          }
          const own = [...card.childNodes].filter((n) => n.nodeType === 3 || (n.nodeType === 1 && !/^(UL|OL)$/.test(n.tagName)));
          const text = own.map((n) => n.textContent).join('').replace(/\u200b/g, '').trim();
          if (text) { const li = doc.createElement('li'); li.textContent = text; target.appendChild(li); }
          card.remove();
        } else card.classList.add(pc.querySelector(':scope > li.ted-pros') ? 'ted-cons' : 'ted-pros');
        changed = true;
      }
    }
    for (const list of pc.querySelectorAll(':scope > li > ul')) {
      for (const nested of [...list.querySelectorAll(':scope > li > ul, :scope > li > ol')]) {
        const owner = nested.parentElement;
        let at = owner;
        for (const item of [...nested.children]) { at.after(item); at = item; }
        nested.remove();
        if (!owner.textContent.replace(/\u200b/g, '').trim() && !owner.querySelector('br')) owner.appendChild(doc.createElement('br'));
        changed = true;
      }
    }
    // лишнее между заголовком и списком карточки (пустые строки, <br>) убираем
    for (const card of pc.querySelectorAll(':scope > li')) {
      for (const n of [...card.childNodes]) {
        if (n === card.firstElementChild || (n.nodeType === 1 && n.tagName === 'UL')) continue;
        if (n.nodeType === 3 && n.data.trim()) continue;
        if (n.nodeType === 1 && n.textContent.trim()) continue;
        n.remove();
        changed = true;
      }
    }
  }
  // плюсы и минусы: у карточки всегда есть заголовок (может быть пустым) и список с пунктами
  for (const card of root.querySelectorAll('ul.ted-proscons > li')) {
    const first = card.firstChild;
    if (!(first && first.nodeType === 1 && first.tagName === 'STRONG')) {
      const t = doc.createElement('strong');
      t.appendChild(doc.createElement('br'));
      card.insertBefore(t, card.firstChild);
      changed = true;
    } else if (!first.firstChild) {
      first.appendChild(doc.createElement('br'));
      changed = true;
    }
    if (!card.querySelector(':scope > ul')) {
      const inner = doc.createElement('ul');
      const item = doc.createElement('li');
      item.appendChild(doc.createElement('br'));
      inner.appendChild(item);
      card.appendChild(inner);
      changed = true;
    }
  }
  // номера строк кода и инициалы автора цитаты пересчитываются при правке текста
  // блок кода: внутри <pre> всегда <code>; подсветка в правке рисуется поверх текста, поэтому токены-<span> из загруженного HTML снимаем
  for (const pre of root.querySelectorAll(':scope > pre')) {
    if (pre.closest('.ted-ui-raw')) continue;
    const had = !!pre.querySelector(':scope > code');
    const code = ensureCode(pre, doc);
    if (!had) changed = true;
    if (code.hasAttribute('data-nums')) { code.removeAttribute('data-nums'); pre.setAttribute('data-nums', '1'); changed = true; }
    if (code.children.length && !code.querySelector('[data-tedui-m]') && !code.querySelector(':scope > br')) {
      const sel = document.getSelection();
      const keep = sel && sel.rangeCount && code.contains(sel.anchorNode) ? null : undefined;
      void keep;
      code.textContent = code.textContent;
      changed = true;
    }
    if (code.childNodes.length > 1 && !code.querySelector('[data-tedui-m]')) code.normalize();   // тысячи соседних текстовых узлов (после загрузки) склеиваем
    if (!pre.hasAttribute('data-lang') && !pre.hasAttribute('data-tedui-auto')) pre.setAttribute('data-tedui-auto', '');
    if (pre.hasAttribute('data-nums')) {
      const before = pre.getAttribute('data-nums');
      const n = (code.textContent.match(/\n/g) || []).length + 1;
      if (before.split('\n').length !== n || (n > 9) !== pre.hasAttribute('data-nums-d')) { setNumsAttrs(pre, n); changed = true; }
    } else if (!pre.hasAttribute('data-nonums')) {
      // номера строк по умолчанию: старый <pre> без data-nums получает их при загрузке (выключены явно — data-nonums)
      setNumsAttrs(pre, (code.textContent.match(/\n/g) || []).length + 1);
      changed = true;
    }
  }
  for (const p of root.querySelectorAll('blockquote > p.ted-author')) {
    if (fixStepItem(p, doc)) changed = true;
    const nameEl = p.querySelector('strong');
    const init = initialsOf(nameEl ? nameEl.textContent : p.textContent);
    if (p.getAttribute('data-initials') !== init) { p.setAttribute('data-initials', init); changed = true; }
  }
  return changed;
}

function emptyBlock(doc, tag = 'p') {
  const el = doc.createElement(tag);
  // список — всегда с пунктом: <ul><li><br></li></ul>, иначе получается пустой <ul>
  let inner = tag === 'ul' || tag === 'ol' ? el.appendChild(doc.createElement('li')) : el;
  if (tag === 'pre') {
    inner = el.appendChild(doc.createElement('code'));   // блок кода: шапка и номера строк по умолчанию
    el.setAttribute('data-nums', '1');
  }
  inner.appendChild(doc.createElement('br'));
  return el;
}

function isEmptyBlock(el) {
  if (!el || el.nodeType !== 1) return false;
  const t = blockType(el);
  if (t === 'raw' || isObjectBlock(el) || isContainer(el) || !!(defOf(el) && defOf(el).neverEmpty)) return false;   // пустая таблица — всё равно блок (у неё есть ручка и корзина)
  const text = el.textContent.replace(/​/g, '');
  // При преобразовании пустого абзаца его <br> становится переносом в <pre>.
  return !(t === 'pre' ? text.trim() : text).length && !el.querySelector(['img', objectSelector()].filter(Boolean).join(', '));
}

const ZWSP = '​';

/** Шаг в правке: <li><strong>заголовок</strong><br>описание</li>; пустое описание держит нулевой пробел, чтобы в нём был курсор. */
function fixStepItem(li, doc) {
  let changed = false;
  let title = li.firstChild;
  if (!(title && title.nodeType === 1 && title.tagName === 'STRONG')) {
    // старая или вставленная разметка без заголовка: заголовок пустой, всё остальное — описание
    title = doc.createElement('strong');
    title.appendChild(doc.createElement('br'));
    li.insertBefore(title, li.firstChild);
    if (li.childNodes.length > 1) li.insertBefore(doc.createElement('br'), title.nextSibling);
    changed = true;
  } else if (!title.firstChild) {
    title.appendChild(doc.createElement('br'));
    changed = true;
  }
  let sep = title.nextSibling;
  if (!(sep && sep.nodeType === 1 && sep.tagName === 'BR')) {
    sep = doc.createElement('br');
    li.insertBefore(sep, title.nextSibling);
    changed = true;
  }
  const desc = sep.nextSibling;
  if (!desc || (desc.nodeType === 1 && /^(UL|OL)$/.test(desc.tagName))) {
    li.insertBefore(doc.createTextNode(ZWSP), desc);
    changed = true;
  }
  return changed;
}

/** Новый шаг: пустой заголовок и пустое описание. */
function emptyStepItem(doc) {
  const li = doc.createElement('li');
  fixStepItem(li, doc);
  return li;
}

/** Пустой блок «Шаги»: один пустой шаг с заглушками «Шаг» / «Описание шага»; следующие создаются Enter. */
function emptyStepsBlock(doc) {
  const ol = doc.createElement('ol');
  ol.classList.add('ted-steps');
  ol.appendChild(emptyStepItem(doc));
  return ol;
}

// ---- resources/js/core/yo.js ----
// Ted — ёфикатор: «е» → «ё» там, где ё не вызывает сомнений.
// Словарь встроенный (без внешних запросов) и намеренно осторожный: в него входят только корни,
// где «е» вместо «ё» не бывает во всех формах, поэтому нет «все/всё», «моем», «берем», «счета» и т. п.
// Пополняется списками ниже.

const ADJ = 'ый|ого|ому|ым|ом|ая|ой|ую|ое|ые|ых|ыми|ою';
const NOUN = '|а|у|ом|е|ы|ов|ам|ами|ах|ей|и|ь|я|ю|ем|ям|ями|ях|ка|ки|ку|кой|ке|ков|кам|ками|ках';

// Корни в форме с «ё» + набор окончаний
const ADJ_STEMS = ('зелён тёмн чёрн жёлт тёпл твёрд лёгк мёртв чётк дешёв тяжёл весёл жёстк надёжн серьёзн озёрн ёмк пёстр ' +
  'шёлков шёрстн учёбн полётн приёмн зачётн отчётн счётн мёдов лёдян лёгочн ёлочн костёрн берёзов клёнов').split(' ');
const NOUN_STEMS = ('вертолёт самолёт полёт перелёт отчёт расчёт почёт учёт зачёт приём объём подъём съём наём заём ' +
  'актёр ёлк ёрш берёз клён костёр мёд свёкр тёщ щётк учёб тётк чёлк чёрт шёпот шёлк ребёнк телёнк котёнк жеребёнк утёнк ' +
  'орлёнк ягнёнк поросёнк ёмкост плёнк серёжк лётчик дёрн').split(' ');
// Слова целиком (изменяемые формы, где «ё» не везде, и слова с «ё» в окончании)
const WORDS = ('ещё её неё моё твоё своё ничьё чьё лёд лён пёс ёж жён идёт идёшь живёт живёшь берёт берёшь несёт несёшь ведёт ведёшь ' +
  'растёт поёт пьёт даёт даёшь встаёт признаёт продаёт передаёт создаёт узнаёт ждёт ждёшь зовёт течёт печёт жмёт везёт ' +
  'придёт найдёт уйдёт пойдёт зайдёт выйдёт пройдёт подойдёт придёшь найдёшь уйдёшь пойдёшь пришёл ушёл нашёл зашёл ' +
  'прошёл подошёл дошёл вошёл шёл нёс принёс унёс привёз увёз довёз вёз привёл увёл довёл ввёл').split(' ');

const toE = (s) => s.replace(/ё/g, 'е');
const map = new Map();           // «е-форма» целиком → «ё-форма»
const prefixes = [];             // {e: 'зелен', yo: 'зелён', ends: Set}

const addWord = (w) => map.set(toE(w), w);
WORDS.forEach(addWord);
const adjEnds = new Set(ADJ.split('|'));
const nounEnds = new Set(NOUN.split('|'));
for (const s of ADJ_STEMS) prefixes.push({ e: toE(s), yo: s, ends: adjEnds });
for (const s of NOUN_STEMS) prefixes.push({ e: toE(s), yo: s, ends: nounEnds });
prefixes.sort((a, b) => b.e.length - a.e.length);

const WORD_RE = /[А-Яа-яЁё]+/g;

function keepCase(src, yo) {
  if (src === src.toUpperCase() && src.length > 1) return yo.toUpperCase();
  if (src[0] !== src[0].toLowerCase()) return yo[0].toUpperCase() + yo.slice(1);
  return yo;
}

/** Заменяет «е» на «ё» в словах из словаря. Слова, где ё уже стоит, не трогает. */
function yofy(text) {
  return text.replace(WORD_RE, (word) => {
    if (!/[еЕ]/.test(word)) return word;
    const low = word.toLowerCase();
    if (map.has(low)) return keepCase(word, map.get(low));
    for (const p of prefixes) {
      if (low.length >= p.e.length && low.startsWith(p.e) && p.ends.has(low.slice(p.e.length))) {
        return keepCase(word, p.yo + low.slice(p.e.length));
      }
    }
    return word;
  });
}

/** Добавляет слова сайта в словарь: список слов в форме с «ё» (например, ['щётка']). */
function registerYo(words) {
  for (const w of words || []) {
    const word = String(w).trim().toLowerCase();
    if (word && /ё/.test(word)) map.set(toE(word), word);
  }
}

// ---- resources/js/core/typo.js ----
// Правила разбиты на категории (TYPO_CATEGORIES): каждую можно отключить, для каждой считается число правок.
// Работает по текстовым узлам блоков, не трогает код (<code>, <pre>), адреса и слова-исключения. Регистр не меняет.

const NBSP = ' ';

/** Категории правок: id, подпись в панели. Порядок — порядок в панели. */
const TYPO_CATEGORIES = [
  { id: 'quotes', label: 'Кавычки' },
  { id: 'dashes', label: 'Тире и диапазоны' },
  { id: 'punct', label: 'Знаки препинания' },
  { id: 'spaces', label: 'Лишние пробелы' },
  { id: 'nbsp', label: 'Неразрывные пробелы' },
  { id: 'numbers', label: 'Числа и валюта' },
  { id: 'phones', label: 'Телефоны' },
  { id: 'symbols', label: 'Символы и единицы' },
  { id: 'terms', label: 'Термины' },
  { id: 'yo', label: 'Буква ё' },
];

// Короткие слова, после которых пробел должен быть неразрывным (русский)
const RU_SHORT = '(?:[А-Яа-яЁё]{1,3}|что|если|чтобы|как|так|также|или|для|без|над|под|при|про|это|все|уже|ещё|даже|либо|между|через|перед|после)';
const RU_SHORT_RE = new RegExp(`(^|[\\s${NBSP}«„("—–-])(${RU_SHORT}) +(?=\\S)`, 'gi');
// Короткие слова английского: артикли и предлоги не отрываем от следующего слова
const EN_SHORT_RE = /(^|[\s"“(])(a|an|the|of|in|on|to|at|by|or|as|is|it|if|we|my|no|so|up|do|go|he|me|us) +(?=\S)/gi;

const UNITS = '%|₽|\\$|€|руб\\.?|р\\.|коп\\.|км\\/ч|м\\/с|кг|км|мм|см|дм|мг|мл|шт\\.?|лет|года?|гг\\.|г\\.|мин\\.?|сек\\.?|ч\\.|ГБ|МБ|КБ|ТБ|Гб|Мб|Кб|dpi|px|кВт|Вт|кГц|МГц|ГГц|Гц|°C|м²|м³|см²|см³|км²|мс|мкс|м|г|л|В|А';
const RU_TAIL_UNITS = new RegExp(`(\\d) +(${UNITS})(?![\\wА-Яа-яЁё])`, 'g');

const SP = '[ \\t\\u00a0]';            // пробел или неразрывный
const MONTHS = 'январ[ьяе]|феврал[ьяе]|март[ае]?|апрел[ьяе]|ма[йяе]|июн[ьяе]|июл[ьяе]|август[ае]?|сентябр[ьяе]|октябр[ьяе]|ноябр[ьяе]|декабр[ьяе]';
const DAYS = 'понедельник|вторник|сред[аы]|четверг|пятниц[аы]|суббот[аы]|воскресень[ея]';
const ABBR_NOBREAK = '(?:г|гг|обл|ул|пр-т|пр|кв|корп|стр|д|оф|илл|рис|табл|им|пос|пл|пер|наб|тел|ст|гл|с|мкр|эт|пом|вл)';
const LEGAL = '(?:АО|ОАО|ЗАО|ООО|ПАО|ИП|НКО|ФГУП)';
const CUR_SIGN = { usd: '$', eur: '€', руб: '₽', р: '₽', rur: '₽', rub: '₽' };
const NOT_LETTER = '(?<![A-Za-zА-Яа-яЁё])';

function detectLang(text) {
  const cyr = (text.match(/[А-Яа-яЁё]/g) || []).length;
  const lat = (text.match(/[A-Za-z]/g) || []).length;
  return cyr >= lat ? 'ru' : 'en';
}

// ---------------------------------------------------------------------------
// Сравнение строк: сколько «правок» и где (для счётчиков и подсветки)
// ---------------------------------------------------------------------------

const TOKEN = /[\p{L}\p{N}]+|[\s\S]/gu;
function tokens(s) {
  const out = [];
  TOKEN.lastIndex = 0;
  for (let m = TOKEN.exec(s); m; m = TOKEN.exec(s)) out.push({ t: m[0], i: m.index });
  return out;
}

/** Отличия b от a: массив {start, end} — диапазоны символов в b. Пустой, если строки равны. */
function diffRanges(a, b) {
  if (a === b) return [];
  const A = tokens(a);
  const B = tokens(b);
  let p = 0;
  while (p < A.length && p < B.length && A[p].t === B[p].t) p += 1;
  let q = 0;
  while (q < A.length - p && q < B.length - p && A[A.length - 1 - q].t === B[B.length - 1 - q].t) q += 1;
  const a2 = A.slice(p, A.length - q);
  const b2 = B.slice(p, B.length - q);
  const n = a2.length;
  const m = b2.length;
  const posAt = (j) => (j < m ? b2[j].i : (b2[m - 1] ? b2[m - 1].i + b2[m - 1].t.length : (B[p] ? B[p].i : b.length)));
  if (!n && !m) return [];
  if (n * m > 250000) return [{ start: posAt(0), end: posAt(m) }];
  const dp = Array.from({ length: n + 1 }, () => new Uint16Array(m + 1));
  for (let i = n - 1; i >= 0; i -= 1) {
    for (let j = m - 1; j >= 0; j -= 1) {
      dp[i][j] = a2[i].t === b2[j].t ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const hunks = [];
  let cur = null;
  let i = 0;
  let j = 0;
  while (i < n || j < m) {
    if (i < n && j < m && a2[i].t === b2[j].t && dp[i][j] === dp[i + 1][j + 1] + 1) { cur = null; i += 1; j += 1; }
    else if (j < m && (i === n || dp[i][j + 1] >= dp[i + 1][j])) {
      const tk = b2[j];
      if (!cur) { cur = { start: tk.i, end: tk.i + tk.t.length }; hunks.push(cur); } else cur.end = tk.i + tk.t.length;
      j += 1;
    } else {
      if (!cur) { const pos = posAt(j); cur = { start: pos, end: pos }; hunks.push(cur); }
      i += 1;
    }
  }
  return hunks;
}

// ---------------------------------------------------------------------------
// Правила
// ---------------------------------------------------------------------------

// Устойчивые написания (СБОЛ): латинские термины работают в любом тексте, русские — только в русском
const TERMS_ANY = [
  [new RegExp(`${NOT_LETTER}master[\\s-]?card(?![A-Za-z])`, 'gi'), 'Mastercard'],
  [new RegExp(`${NOT_LETTER}google[\\s-]?pay(?![A-Za-z])`, 'gi'), 'Google Pay'],
  [new RegExp(`${NOT_LETTER}apple[\\s-]?pay(?![A-Za-z])`, 'gi'), 'Apple Pay'],
  [new RegExp(`${NOT_LETTER}wi[\\s-]?fi(?![A-Za-z])`, 'gi'), 'Wi-Fi'],
  [new RegExp(`${NOT_LETTER}e-?mail(?![A-Za-z])`, 'gi'), 'email'],
  [new RegExp(`${NOT_LETTER}qr[\\s-]?код`, 'gi'), 'QR-код'],
  [new RegExp(`${NOT_LETTER}(cvv|cvc)(2?)[\\s-]?код`, 'gi'), (m, a, b) => `${a.toUpperCase()}${b}-код`],
  [new RegExp(`${NOT_LETTER}(cvv|cvc)(?![A-Za-z0-9])`, 'gi'), (m, a) => a.toUpperCase()],
  [new RegExp(`${NOT_LETTER}push[\\s-]?(уведомлени)`, 'gi'), 'Push-$1'],
];
const TERMS_RU = [
  [/(?<![А-Яа-яЁё])пин[\s-]?код/gi, 'ПИН-код'],
  [/(?<![А-Яа-яЁё])сим[\s-]?карт/gi, 'сим-карт'],
  [/(?<![А-Яа-яЁё])смс(?![А-Яа-яЁё])/gi, 'СМС'],
  [/(?<![А-Яа-яЁё])офф?-?лайн/gi, 'офлайн'],
  [/(?<![А-Яа-яЁё])он-?лайн/gi, 'онлайн'],
  [/(?<![А-Яа-яЁё])мск(?![А-Яа-яЁё])/gi, 'мск'],
];

const escapeRe = (w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function terms(s, ru, extra) {
  for (const [re, to] of TERMS_ANY) s = s.replace(re, to);
  if (ru) for (const [re, to] of TERMS_RU) s = s.replace(re, to);
  // свои термины сайта: [что, как] — строка (слово целиком, без учёта регистра) или RegExp
  for (const [from, to] of extra || []) {
    const re = from instanceof RegExp ? from : new RegExp(`(?<![\\p{L}\\d])${escapeRe(String(from))}(?![\\p{L}\\d])`, 'giu');
    s = s.replace(re, to);
  }
  return s;
}

const groupThousands = (digits) => digits.replace(/\B(?=(\d{3})+(?!\d))/g, NBSP);

/** Валюта и числа перед ней (СБОЛ): ₽ $ €, группы по тысячам, запятая, копейки, тыс. / млн / млрд / трлн. */
function currency(s) {
  const unit = '(?:тыс\\.|(?:млн|млрд|трлн)\\.?)';
  // знак впереди: «$ 109», «$109» → «109 $»
  s = s.replace(new RegExp(`([$€₽])${SP}*(\\d+(?:[\\u00a0 ]\\d{3})*(?:[.,]\\d+)?)`, 'g'), '$2 $1');
  // копейки сливаем: «45 руб. 5 коп.» → «45,05 ₽»
  s = s.replace(new RegExp(`(\\d+)${SP}*(?:руб\\.?|р\\.|₽)${SP}*(\\d{1,2})${SP}*коп\\.?(?![А-Яа-яЁё])`, 'gi'), (m, r, k) => `${r},${k.padStart(2, '0')} ₽`);
  // слова-валюты → знак
  s = s.replace(new RegExp(`(\\d|${unit})${SP}*(usd|eur|rur|rub|руб(?:лей|ля|ль)?\\.?|р\\.|р)(?![A-Za-zА-Яа-яЁё0-9])`, 'gi'), (m, a, w) => {
    const key = w.toLowerCase().replace(/\.$/, '').replace(/^руб.*/, 'руб');
    return `${a} ${CUR_SIGN[key] || w}`;
  });
  // знак после числа через неразрывный пробел
  s = s.replace(new RegExp(`(\\d|${unit})${SP}*([$€₽])`, 'g'), '$1 $2');
  // тыс. — с точкой, млн / млрд / трлн — без
  s = s.replace(/(\d)[\s ]*тыс\.?(?![А-Яа-яЁё])/gi, '$1 тыс.');
  s = s.replace(/(\d)[\s ]*(млн|млрд|трлн)\.?(?![А-Яа-яЁё])/gi, '$1 $2');
  // группы тысяч и запятая — только у сумм
  s = s.replace(new RegExp(`(?<![\\d.,])(\\d+(?:[\\u00a0 ]\\d{3})*)(?:[.,](\\d{1,2}))?(?=\\u00a0(?:${unit}\\u00a0)?[$€₽])`, 'g'),
    (m, int, frac) => groupThousands(int.replace(/[  ]/g, '')) + (frac ? `,${frac}` : ''));
  // процент без пробела
  s = s.replace(/(\d)[ \t ]+%/g, '$1%');
  return s;
}

/** Телефоны (СБОЛ): 8 800 555-55-50, +7 495 500-55-50, +7 4212 79-40-35. */
function phones(s, keep) {
  const hold = (m) => { keep.push(m); return `\u0001${keep.length - 1}\u0002`; };
  const four = /(?<![\d])(?:\+7|8)[\s-]*\(?(\d{4})\)?[\s ]+(\d{2})-(\d{2})-(\d{2})(?!\d)/g;
  s = s.replace(four, (m, a, b, c, d) => hold(`+7 ${a} ${b}-${c}-${d}`));
  const gen = /(?<![\d])(\+7|8|7)[\s-]*\(?(\d{3})\)?[\s-]*(\d{3})[\s-]*(\d{2})[\s-]*(\d{2})(?!\d)/g;
  return s.replace(gen, (m, p, a, b, c, d) => hold(a === '800' ? `8 800 ${b}-${c}-${d}` : `+7 ${a} ${b}-${c}-${d}`));
}

/** Символы, единицы, стрелки, дроби. */
function symbols(s) {
  s = s.replace(/\(c\)/gi, '©').replace(/\(r\)/gi, '®').replace(/\(tm\)/gi, '™');
  s = s.replace(/\+-/g, '±');
  s = s.replace(/(?<=\s|^)->(?=\s|$)/g, '→').replace(/(?<=\s|^)<-(?=\s|$)/g, '←');
  s = s.replace(/(?<=\s)!=(?=\s)/g, '≠').replace(/(?<=\s)<=(?=\s)/g, '≤').replace(/(?<=\s)>=(?=\s)/g, '≥');
  // 1920x1080 и 5 x 3 → ×  (0x1F не трогаем)
  s = s.replace(/(?<!\b0)(?<=\d)[xх](?=\d)/g, '×');
  s = s.replace(/(?<=\d) [xх] (?=\d)/g, ' × ');
  // дроби
  s = s.replace(/(?<![\d/.,])1\/2(?![\d/])/g, '½').replace(/(?<![\d/.,])1\/4(?![\d/])/g, '¼').replace(/(?<![\d/.,])3\/4(?![\d/])/g, '¾')
    .replace(/(?<![\d/.,])1\/3(?![\d/])/g, '⅓').replace(/(?<![\d/.,])2\/3(?![\d/])/g, '⅔');
  // градусы: «20 C», «20°С» → «20 °C» (латинская C)
  s = s.replace(/(\d)[ \t ]*[°º˚][ \t ]*([CFСсf])(?![A-Za-zА-Яа-яЁё])/g, (m, d, u) => `${d} °${u === 'С' || u === 'с' || u === 'C' ? 'C' : u.toUpperCase()}`);
  // квадратные и кубические единицы: 20 м2 → 20 м²
  s = s.replace(/(\d[ \t ]*)(мм|см|дм|км|м|га)([23])(?![\dA-Za-zА-Яа-яЁё])/g, (m, pre, u, p) => `${pre}${u}${p === '2' ? '²' : '³'}`);
  return s;
}

/** Тире: между словами, в начале строки и предложения, диапазоны. */
function dashes(s, ru) {
  // минус перед числом (решение 22.11: только перед числом): «-5 °C», «(-3)», «= -2,5» → «−5»; дефис между буквами и цифрами не трогаем
  s = s.replace(/(^|[\s(=:;«"„])-(?=\d)/g, '$1−');
  s = s.replace(/([^\s-])\s+(?:--|-|–|—)\s+(?=\S)/g, `$1${ru ? NBSP : ' '}— `);
  s = s.replace(/(\S)--(\S)/g, '$1—$2');
  if (!ru) return s;
  // в начале строки и предложения: «— » с неразрывным пробелом
  s = s.replace(/^[ \t]*(?:--|-|–|—)(?:[ \t ]+|(?=[А-Яа-яЁё«„"]))/, '— ');
  s = s.replace(/([.!?…])[ \t]+(?:--|-|–|—)[ \t ]+(?=[А-ЯЁ«„"])/g, '$1 — ');
  // диапазоны: числа, время, даты, римские цифры, месяцы, дни недели — короткое тире без пробелов
  s = s.replace(/(?<![\d-])(\d+)[ \t ]*[-–—][ \t ]*(\d+)(?![\d-])/g, '$1–$2');
  s = s.replace(/(\d{1,2}:\d{2})[ \t]*[-–—][ \t]*(\d{1,2}:\d{2})/g, '$1–$2');
  s = s.replace(/(?<![A-Za-zА-Яа-яЁё])([IVXLC]{1,6})[ \t]*[-–—][ \t]*([IVXLC]{1,6})(?![A-Za-zА-Яа-яЁё])/g, '$1–$2');
  s = s.replace(new RegExp(`(?<![А-Яа-яЁё])(${MONTHS})[ \\t]*[-–—][ \\t]*(${MONTHS})(?![А-Яа-яЁё])`, 'gi'), '$1–$2');
  s = s.replace(new RegExp(`(?<![А-Яа-яЁё])(${DAYS})[ \\t]*[-–—][ \\t]*(${DAYS})(?![А-Яа-яЁё])`, 'gi'), '$1–$2');
  return s;
}

/** Знаки препинания: многоточие, «?!», повторы, точка за кавычкой, точка в конце заголовка. */
function punct(s, ru, block) {
  // русские знаки до многоточия: «!?» → «?!», «...?» и «?...» → «?‥», «...!» и «!...» → «!‥»
  if (ru) s = s.replace(/!\?/g, '?!').replace(/(?:…|\.{3})\?|\?(?:…|\.{3})/g, '?‥').replace(/(?:…|\.{3})!|!(?:…|\.{3})/g, '!‥');
  s = s.replace(/\.{3,}/g, '…').replace(/…{2,}/g, '…');
  if (!ru) return s;
  s = s.replace(/([?!,;:])\1+/g, '$1');
  s = s.replace(/(?<!\.)\.{2}(?!\.)/g, '.');
  // точка уходит из-под закрывающей кавычки: «текст.» → «текст».
  s = s.replace(/(?<![.…!?])\.([»“”])/g, '$1.');
  // убрать точку в конце одно-предложенческой строки (заголовок, пункт списка)
  if (block && /^(H[2-6]|LI)$/.test(block) && !/[.!?…][ \t ]+\S/.test(s)) s = s.replace(/(?<![.…!?])\.[ \t ]*$/, '');
  return s;
}

/** Лишние пробелы: подряд идущие, у знаков препинания и скобок, после знаков. */
function spaces(s) {
  s = s.replace(/[ \t]{2,}/g, ' ');
  s = s.replace(/[ \t ]+([,.;:!?…‥%)\]»”])(?!\d)/g, '$1');
  s = s.replace(/([(\[«“„])[ \t ]+/g, '$1');
  s = s.replace(/([,;!?])(?=[A-Za-zА-Яа-яЁё«“"(])/g, '$1 ');
  s = s.replace(/([А-Яа-яЁё]{2,}|[a-z]{2,})([:])(?=[A-Za-zА-Яа-яЁё«“])/g, '$1$2 ');
  s = s.replace(/([a-zа-яё]{2,})\.(?=[A-ZА-ЯЁ][a-zа-яё])/g, '$1. ');
  return s;
}

/** Неразрывные пробелы. */
function nbspRules(s, ru) {
  if (!ru) {
    s = s.replace(EN_SHORT_RE, (m, pre, w) => `${pre}${w}${NBSP}`);
    return s.replace(/(\d) +(%|km|kg|mm|cm|GB|MB|KB|TB|px|dpi)(?![A-Za-z])/g, `$1${NBSP}$2`);
  }
  s = s.replace(/(?<![А-Яа-яЁё])([А-ЯЁ]\.)[\s ]*(?=[А-ЯЁ]\.)/g, '$1');                          // А. А. → А.А.
  s = s.replace(/(?<![А-Яа-яЁё])([А-ЯЁ]\.)[ \t]*(?=[А-ЯЁ][а-яё])/g, '$1 ');                     // А.А. Иванов
  s = s.replace(/([А-ЯЁ][а-яё]+)[ \t]+(?=[А-ЯЁ]\.)/g, '$1 ');                                  // Петров К.П.
  s = s.replace(/(?<=\S)[ \t ]+(и)[ \t ]+(т)\.[ \t ]*(д|п)\./gi, ' $1 $2. $3.');
  s = s.replace(/(?<=\S)[ \t ]+(и)[ \t ]+(др|пр)\./gi, ' $1 $2.');
  s = s.replace(/(\d)[ \t]+(?=[A-Za-zА-Яа-яЁё])/g, '$1 ');                                      // число + слово
  s = s.replace(/[ \t]+(?=(?:б|бы|ж|же|ли|ль)(?![А-Яа-яЁё]))/gi, ' ');                           // частицы
  s = s.replace(new RegExp(`(?<![А-Яа-яЁё.])(${ABBR_NOBREAK}\\.|№|§)[ \\t]+(?=\\S)`, 'g'), '$1 '); // г. ул. кв. № §
  s = s.replace(new RegExp(`(${LEGAL})[ \\t]+(?=[«„"A-ZА-ЯЁ])`, 'g'), '$1 ');                     // ООО «…»
  // последнее короткое слово предложения и строки
  s = s.replace(/[ \t]+(?=[А-Яа-яЁё]{1,4}[»”)]*(?:[.!?…‥]+|$)(?:[ \t ]|$))/g, ' ');
  // слова до трёх букв и союзы не отрываем от следующего слова
  s = s.replace(RU_SHORT_RE, (m, pre, w) => `${pre}${w}${NBSP}`);
  s = s.replace(RU_SHORT_RE, (m, pre, w) => `${pre}${w}${NBSP}`); // подряд идущие «и в», «а в»
  s = s.replace(RU_TAIL_UNITS, `$1${NBSP}$2`);
  return s.replace(/(\d{1,3}(?: \d{3})+)(?![\d])/g, (m) => m.replace(/ /g, NBSP));
}

function quotes(s, lang, state) {
  const ru = lang === 'ru';
  const open1 = ru ? '«' : '“';
  const close1 = ru ? '»' : '”';
  const open2 = ru ? '„' : '‘';
  const close2 = ru ? '“' : '’';
  let out = '';
  for (let i = 0; i < s.length; i += 1) {
    const c = s[i];
    if (c !== '"' && c !== '“' && c !== '”' && c !== '«' && c !== '»' && c !== '„') { out += c; continue; }
    const prev = s[i - 1];
    const next = s[i + 1];
    const startsWord = !prev || /[\s(\[{—–-]/.test(prev) || prev === NBSP || (prev && /[«„“]/.test(prev));
    const endsWord = !next || /[\s)\].,;:!?…—–-]/.test(next) || next === NBSP || (next && /[»”“]/.test(next));
    // «ёлочки» и „лапки“ уже стоят — нормализуем к нужному виду
    let opening;
    if (c === '«' || c === '“' && ru === false || c === '„') opening = true;
    else if (c === '»' || c === '”') opening = false;
    else opening = startsWord && !endsWord ? true : (!startsWord && endsWord ? false : state.depth === 0);
    if (opening) {
      out += state.depth === 0 ? open1 : open2;
      state.depth += 1;
    } else {
      if (state.depth > 0) state.depth -= 1;
      out += state.depth === 0 ? close1 : close2;
    }
  }
  return out;
}

/**
 * Исправляет строку. state.depth — вложенность кавычек (переносится между узлами одного блока).
 * block — имя тега блока. ctx: { off: Set категорий, stats: {категория: число правок}, protect: RegExp, terms: [] }.
 */
function typografText(text, lang, state = { depth: 0 }, block = '', ctx = {}) {
  if (!text) return text;
  const off = ctx.off || new Set();
  const stats = ctx.stats || null;
  const ru = lang === 'ru';
  // адреса, почта, слова-исключения не трогаем: прячем под метки и возвращаем в конце
  const keep = [];
  const hold = (m) => { keep.push(m); return `\u0001${keep.length - 1}\u0002`; };
  let s = text.replace(/(?:https?:\/\/|www\.|mailto:)\S+|[\w.+-]+@[\w-]+\.[\w.-]+|\b[\w-]+\.[a-z]{2,6}(?:\/\S*)/gi, hold);
  if (ctx.protect) s = s.replace(ctx.protect, hold);

  const step = (cat, fn) => {
    if (off.has(cat)) return;
    const before = s;
    s = fn(s);
    if (stats && s !== before) stats[cat] = (stats[cat] || 0) + diffRanges(before, s).length;
  };

  if (ru) step('phones', (v) => phones(v, keep));
  step('spaces', (v) => v.replace(/[ \t]{2,}/g, ' '));
  step('symbols', symbols);
  step('punct', (v) => punct(v, ru, ctx.single ? block : ''));
  step('dashes', (v) => dashes(v, ru));
  step('quotes', (v) => quotes(v, lang, state));
  // точка уходит из-под закрывающей кавычки — после того, как кавычки приведены к «ёлочкам»
  if (ru) step('punct', (v) => v.replace(/(?<![.…!?])\.([»“”])/g, '$1.'));
  step('spaces', spaces);
  step('terms', (v) => terms(v, ru, ctx.terms));
  if (ru) step('yo', yofy);
  step('numbers', (v) => (ru ? currency(v) : v));
  step('nbsp', (v) => nbspRules(v, ru));
  // апостроф в английском: don't → don’t
  if (!ru) step('punct', (v) => v.replace(/([A-Za-z])'([a-z])/g, '$1’$2'));

  return s.replace(/\u0001(\d+)\u0002/g, (m, i) => keep[Number(i)]);
}

const SKIP = 'code, pre, kbd, samp, script, style';

/** Слова-исключения → RegExp для typografText (ctx.protect). */
function protectRegExp(words) {
  const list = (words || []).map((w) => String(w).trim()).filter(Boolean).sort((a, b) => b.length - a.length);
  if (!list.length) return null;
  return new RegExp(`(?<![\\p{L}\\d])(?:${list.map(escapeRe).join('|')})(?![\\p{L}\\d])`, 'gu');
}

/**
 * Обходит блоки и исправляет текстовые узлы.
 * Возвращает { changed, edits: [{ node, before }], stats } (edits — для подсветки и отката).
 * opts: { lang: 'ru' | 'en' | 'auto', off: Set, protect: RegExp, terms: [] }
 */
function typografBlocks(blocks, opts = {}) {
  const lang = opts.lang || 'auto';
  const stats = {};
  const edits = [];
  for (const block of blocks) {
    if (!block || block.nodeType !== 1 || block.matches(SKIP) || block.classList.contains('ted-ui-raw')) continue;
    const l = lang === 'auto' ? detectLang(block.textContent || '') : lang;
    const state = { depth: 0 };
    const walker = block.ownerDocument.createTreeWalker(block, NodeFilter.SHOW_TEXT);
    const nodes = [];
    for (let n = walker.nextNode(); n; n = walker.nextNode()) {
      if (n.parentElement && n.parentElement.closest(SKIP)) continue;
      nodes.push(n);
    }
    nodes.forEach((n, i) => {
      const tag = nodes.length === 1 ? (n.parentElement.closest('li, h2, h3, h4, h5, h6, p, blockquote') || block).tagName : '';
      let next = typografText(n.data, l, state, tag, { off: opts.off, stats, protect: opts.protect, terms: opts.terms, single: nodes.length === 1 });
      // пробел между узлами (…слово </b>…) не схлопываем с соседним
      if (i === 0) next = next.replace(/^[ \t]+(?=\S)/, (m) => (block.tagName === 'LI' || block.tagName === 'P' ? '' : m));
      if (i === nodes.length - 1) next = next.replace(/[ \t]+$/, '');
      if (next !== n.data) { edits.push({ node: n, before: n.data }); n.data = next; }
    });
  }
  return { changed: edits.length, edits, stats };
}

// ---- resources/js/core/keys.js ----
// Горячие клавиши. Сравниваем по физической клавише (event.code), поэтому
// сочетания работают и в русской раскладке (Ctrl+B = Ctrl+И).
// Mod = Ctrl на Windows/Linux, ⌘ на macOS.

const HOTKEYS = [
  // Строчное форматирование
  { cmd: 'bold', code: 'Mod+KeyB', keys: 'Mod+B', label: 'Жирный' },
  { cmd: 'italic', code: 'Mod+KeyI', keys: 'Mod+I', label: 'Курсив' },
  { cmd: 'underline', code: 'Mod+KeyU', keys: 'Mod+U', label: 'Подчёркнутый' },
  { cmd: 'strike', code: 'Mod+Shift+KeyS', keys: 'Mod+Shift+S', label: 'Зачёркнутый' },
  { cmd: 'code', code: 'Mod+KeyE', keys: 'Mod+E', label: 'Код в строке' },
  { cmd: 'link', code: 'Mod+KeyK', keys: 'Mod+K', label: 'Ссылка' },

  // Типы блоков
  // (заголовки, списки, цитата — из block.json своих блоков, после «Ссылки»)

  // Выравнивание
  { cmd: 'align:left', code: 'Mod+Shift+KeyL', keys: 'Mod+Shift+L', label: 'По левому краю' },
  { cmd: 'align:center', code: 'Mod+Shift+KeyE', keys: 'Mod+Shift+E', label: 'По центру' },
  { cmd: 'align:right', code: 'Mod+Shift+KeyR', keys: 'Mod+Shift+R', label: 'По правому краю' },

  // Правка
  { cmd: 'undo', code: 'Mod+KeyZ', keys: 'Mod+Z', label: 'Отменить' },
  { cmd: 'redo', code: 'Mod+Shift+KeyZ', keys: 'Mod+Shift+Z', label: 'Повторить' },
  { cmd: 'redo', code: 'Mod+KeyY', keys: 'Mod+Y', label: 'Повторить', hidden: true },

  // Редактор
  { cmd: 'mode', code: 'Mod+Shift+KeyP', keys: 'Mod+Shift+P', label: 'Просмотр / редактирование' },
  { cmd: 'save', code: 'Mod+KeyS', keys: 'Mod+S', label: 'Сохранить' },
  { cmd: 'help', code: 'Mod+Slash', keys: 'Mod+/', label: 'Горячие клавиши' },
  // работа с блоками без мыши (доступность, 22.11): меню блока и перенос вверх / вниз
  { cmd: 'blockmenu', code: 'Mod+Period', keys: 'Mod+.', label: 'Меню блока' },
  { cmd: 'moveup', code: 'Mod+Shift+ArrowUp', keys: 'Mod+Shift+↑', label: 'Блок выше' },
  { cmd: 'movedown', code: 'Mod+Shift+ArrowDown', keys: 'Mod+Shift+↓', label: 'Блок ниже' },
];

const KEYS_IS_MAC = typeof navigator !== 'undefined' && /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);

function eventCombo(e) {
  const mod = KEYS_IS_MAC ? e.metaKey : e.ctrlKey;
  if (!mod) return '';
  // Ctrl+Alt на Windows — это AltGr, его не трогаем
  if (e.altKey) return '';
  return `Mod+${e.shiftKey ? 'Shift+' : ''}${e.code}`;
}

function findHotkey(e) {
  const combo = eventCombo(e);
  if (!combo) return null;
  return HOTKEYS.find((k) => k.code === combo) || null;
}

function keysFor(cmd) {
  const k = HOTKEYS.find((x) => x.cmd === cmd && !x.hidden);
  return k ? k.keys : '';
}

// ---- resources/js/core/registry.js ----
// Реестр блоков (этап 5 MODULAR_PLAN.md). Блок — папка blocks/<тип>/: описание block.json и код <тип>.js, который
// регистрирует себя: Ted.registerBlock({ ...описание, ...функции }). Ядро не знает конкретных блоков — спрашивает реестр.
// Перенос идёт по одному блоку (решение 18.11); пока не перенесённые блоки живут в ядре по-старому.
//
// Описание (block.json — общее для браузера и сервера src/Blocks.php):
//   type        — вид блока ('hr'); aliases — другие имена в наборах и опции blocks ('separator')
//   title       — название; menu — { group, icon, words, convert, after } — плитка в меню «/» и «Все блоки»
//   object      — true: блок без текста (линия, медиа): выделяется целиком, панель «line», нет «Превратить в…»
//   outline     — true: рамка выделения рисуется обводкой вокруг элемента, а не подложкой (::after)
//   handleAt    — 'middle': ручка ⠿ по центру всей высоты блока (линия), иначе — по первой строке текста
//   markdown    — строка, после которой Enter вставляет блок ('---')
//   hotkey      — { code, keys, label, after, convert } — горячая клавиша: вставка блока (cmd 'insert:<тип>') или,
//                 с convert: true, превращение текущего блока (cmd 'block:<тип>'); after — место в справке
//   text        — true: текстовый блок (абзац, заголовок, цитата, код, список) — его правку ведёт текстовый движок ядра
//                 (ввод, Enter, Backspace, Markdown, превращение); в папке блока — описание, меню, стили, тесты
//   style       — { label, icon, keys, order } — пункт списка «Стиль текста»; placeholder — подсказка пустого блока
//   jsonType    — имя вида в Ted.fromBlocks, если не type (цитата — «quote»)
//   menu.picker — своя группа в «Все блоки», если там группы мельче, чем в «/» (файл — «Файлы», таблица — «Таблицы»)
//   menu.order  — место в группе меню (у блоков ядра — номер × 10 по порядку в SLASH_GROUPS)
//   html        — { тег: [атрибуты] } — белый список очистки (JS и PHP)
//   degrade     — как превращается в текст в наборе без этого блока: 'drop' — исчезает; 'children' — остаются вложенные
//                 блоки с текстом (выноска → её абзацы); иначе — код ядра (блоки, ещё не перенесённые)
//   compound    — составной блок: Delete в конце абзаца перед ним не втягивает его текст
//   classes     — классы, которые очистка сохраняет у элемента блока (выноска: ted-callout на blockquote)
//   container   — true: блок-контейнер (внутри — обычные блоки в «хостах» .ted-ui-host): не пустая строка, под ним строка текста,
//                 нормализация (normalize(el, doc, normalizeBody)) и очистка тел — общим кодом контейнеров (containers.js)
//   jsonExample — пример блока для промта нейросети (Ted.fromBlocks), строкой JSON (меню «Ещё» → «Скопировать промт», 22.11)
//   toMarkdown(el, md) — блок → Markdown (Ted.toMarkdown, выгрузка .md); md = { inline, blocks, list, table }
//   fromMarkdownAlert(title, html) — «> [!NOTE] Заголовок» в Markdown → HTML блока (выноска)
//   narrow      — true: тела контейнера узкие (колонки): туда не вставляются блоки с inNarrow: false (решение 22.11)
//   inNarrow    — false: блок слишком широкий для узкого тела контейнера (товар, таблица) — в колонки не вставляется и не переносится
//   wrap        — класс обёртки правки (медиа: ted-ui-media): в редакторе блок живёт внутри <div class="…" contenteditable="false">
//                 со своей панелью; ядро узнаёт обёртку через isWrap / wrapSelector, вид — у блока внутри
//   insertMenu  — 'media': пункт меню кнопки «Медиа ▾» панели (title, menu.icon), вставка — insert
//   ids         — атрибуты из html, значение которых — идентификатор CMS (латиница, цифры, _ и -, до 64): иначе удаляется
//                 (JS allowlist.js и PHP Sanitizer одинаково)
//   create      — может вернуть { el, focus } — куда поставить курсор после вставки
//   placeholders(editor, root), onKey(editor, e) — заглушки пустых частей и клавиши внутри блока
//   noBold      — CSS-селектор частей блока, где «Жирный» не действует (название вкладки, заголовок выноски)
//   linePlaceholder — заглушка новой пустой строки (абзаца) внутри блока, где стоит курсор (выноска: «Текст выноски»)
//   toolbar     — { bg, align, style: false; marks: [разрешённые] } — что убрать из панели, когда курсор в блоке
//   neverEmpty  — true: блок не считается пустой строкой (кнопка, карточка) — Backspace и вставка его не заменяют
//   caretBelow  — true: после вставки из меню курсор встаёт в строку текста под блоком
//   lineAfter   — true: последним в тексте под блоком всегда есть строка текста (у caretBelow — тоже), курсор после вставки — по create
//   frames      — true: <iframe> прямо в элементе блока — фрейм блока: любой https-адрес (или iframe.hosts настроек) и песочница
//                 блока; вне такого блока — только площадки видео (JS allowlist.js и PHP Sanitizer одинаково)
// Функции (только в браузере):
//   match(el)         — это элемент блока (сохранённый HTML и правка)
//   create(doc)       — новый пустой блок
//   clean(node, doc)  — очистка входящего элемента → элемент блока (вставка, загрузка)
//   fromJson(b)       — HTML из описания блока в JSON (Ted.fromBlocks)
//   clean(node, doc, idOk) — третий аргумент: проверка якоря (id)
//   serialize(el)     — HTML блока для сохранения (из формы правки), пустая строка — блок не сохраняется
//   normalize(el, doc) — привести форму правки к порядку (true — что-то поменялось)
//   toText(el, h)     — блок в наборе без него → массив узлов текста; h = { doc, p, list, text, esc } (то же — <Тип>.php → degrade)
//   canAlign(el), canBg(el) — можно ли выравнивать / красить фоном этот блок (баннер — нет)
//   editorUi(editor)  — правка блока в редакторе (<тип>.editor.js): объект с onKey(e), sync(), focusBlock(), destroy();
//                       editorUiName — имя свойства редактора (editor.buttons)
//   afterInsert(editor, el) — после вставки из меню (открыть окно настроек)
//   insert(editor, block)   — блок вставляет себя сам (медиа: пустой блок с выбором файла) — меню «/», «Все блоки», «Медиа ▾»
//   blank(doc)        — пустая форма правки без окон (колонки ставят пустое изображение)
//   adopt(node)       — очистка: чужой элемент, который блок забирает себе (аккордеон — одиночный <details>)
//   unnest(el, doc)   — блок внутри тела контейнера не живёт: чем его заменить (вкладки → заголовки жирным и содержимое)
//   fromRaw(el, doc)  — вставили чужой HTML: блок забирает элемент себе (одиночная картинка → «Изображение»), иначе null
//   filesOf(html, base) — адреса своих файлов блока в HTML (после сохранения лишние удаляются с сервера)
//   clean(node, doc, idOk, wrap), serialize(el, wrap) — у блока с обёрткой: el — блок внутри, wrap — обёртка правки;
//                       clean → false: «не мой» — элемент очищается как обычно (сложная таблица — «сырой» HTML)
//   blockMenu(editor, block, done) — свои пункты меню блока (⠿): таблица — «Шапка», «Границы»
//   editorUi может ещё: refresh() — после каждой правки; statsOf(el) → { text, filled } — для сводки; pasteFiles(e, block),
//                       pasteLink(url, link, block), afterPaste(before) — вставка файлов, одной ссылки, HTML;
//                       selectedItem() — пункт, выбранный нажатием (кнопки ⠿ 🗑 у него); ownsItem(li) — пункт блока: тогда
//                       itemInside (кнопки пункта — внутри строки) и afterItemRemove() (блок остаётся и без пунктов);
//                       itemAt(node) — пункт блока под курсором (вкладка); itemAbove — кнопки пункта над ним; itemRemoved(li, parent) —
//                       пункт удалён (вкладка — вместе со своим содержимым); blockOfItems(parent) — что заменить абзацем после
//                       последнего пункта; removedToast — сообщение «… удалена»; itemRow(li) — строка, у которой кнопки пункта
//                       (вопрос аккордеона); itemCaret(li) — куда курсор после удаления соседнего пункта; itemAbove — кнопки над
//                       пунктом ('above' — вкладка, 'card' — колонка); canRemove(li) — можно ли удалить (колонок не меньше двух);
//                       syncFirst() — раньше кнопок блока (таблица: место под «Добавить …»), afterSync() — после них;
//                       onKeyFirst(e) — Enter, Tab, стрелки, Backspace, Delete раньше всех (ячейки таблицы); onPaste(cd, block, r) —
//                       вставка (таблица из Excel); lockStyle() — стиль блока и выравнивание сейчас не действуют (курсор в ячейке)
//   fromLink(editor, block, url), canFromLink(editor) — вставили ссылку отдельным абзацем: блок предлагает показать её
//                       собой (карточка встраивания) — «Встроить карточкой» в окне ссылки (media.js); canFromLink — доступно ли сейчас
// В block.json ещё: selector (CSS-селектор элемента), menu.sample (образец на плитке «Все блоки»), figma (компонент макета).

const REGISTRY = new Map();
const REG_TYPE = /^[a-z][a-z0-9-]{0,31}$/;

/** Зарегистрировать блок. Повторная регистрация того же вида — ошибка (два блока с одним именем). */
function registerBlock(def) {
  if (!def || typeof def !== 'object' || !REG_TYPE.test(def.type || '')) throw new Error('Ted.registerBlock: нужен вид блока type (латиница, цифры, «-»)');
  if (REGISTRY.has(def.type)) throw new Error(`Ted.registerBlock: блок «${def.type}» уже зарегистрирован`);
  if (typeof def.match !== 'function') throw new Error(`Ted.registerBlock: у блока «${def.type}» нет match(el)`);
  REGISTRY.set(def.type, Object.freeze({ aliases: [], html: {}, ...def }));
  // горячая клавиша вставки — в общий список (справка «Горячие клавиши» показывает её на месте after)
  if (def.hotkey) {
    const k = { cmd: `${def.hotkey.convert ? 'block' : 'insert'}:${def.type}`, code: def.hotkey.code, keys: def.hotkey.keys, label: def.hotkey.label };
    let at = -1;
    for (let i = 0; i < HOTKEYS.length; i++) if (HOTKEYS[i].cmd === def.hotkey.after) at = i;
    HOTKEYS.splice(at < 0 ? HOTKEYS.length : at + 1, 0, k);
  }
  return REGISTRY.get(def.type);
}

/** Описание блока по виду (или другому имени). */
function blockDef(type) {
  if (REGISTRY.has(type)) return REGISTRY.get(type);
  for (const d of REGISTRY.values()) if (d.aliases.includes(type)) return d;
  return null;
}

/** Элемент лежит в узком теле контейнера (block.json контейнера → narrow: true, например колонки). */
function inNarrowHost(host) {
  for (let a = host; a && a.nodeType === 1; a = a.parentElement) {
    const d = defOf(a);
    if (d && d.container) return !!d.narrow;
  }
  return false;
}

/** Все зарегистрированные блоки в порядке регистрации. */
function registeredBlocks() { return [...REGISTRY.values()]; }

/** Блок, которому принадлежит элемент (верхнего уровня), или null. */
function defOf(el) {
  if (!el || el.nodeType !== 1) return null;
  for (const d of REGISTRY.values()) if (d.match(el)) return d;
  return null;
}

/** Элемент — блок без текста (линия, медиа…): выделяется целиком. */
function isObjectBlock(el) { const d = defOf(el); return !!(d && d.object); }

/** Вид — блок без текста. */
function isObjectType(type) { const d = blockDef(type); return !!(d && d.object); }

/** CSS-селектор элементов блоков без текста (для проверок «пусто ли», «куда поставить курсор»). */
function objectSelector() {
  return registeredBlocks().filter((d) => d.object && d.selector).map((d) => d.selector).join(', ');
}

/** Обёртка правки блока (block.json → wrap, медиа): элемент — обёртка. */
function isWrap(el) {
  return !!el && el.nodeType === 1 && registeredBlocks().some((d) => d.wrap && el.classList.contains(d.wrap));
}

/** CSS-селектор обёрток правки; если их нет — селектор, который ничего не выбирает. */
function wrapSelector() {
  const list = [...new Set(registeredBlocks().filter((d) => d.wrap).map((d) => `.${d.wrap}`))];
  return list.length ? list.join(', ') : ':not(*)';
}

/** Блок, который вставляется Markdown-строкой (например «---»). */
function markdownBlock(text) {
  for (const d of REGISTRY.values()) if (d.markdown && d.markdown === text) return d;
  return null;
}

